-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[9632] = {id=9632,name="Newfound Allies",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=3524,mapID=97,description="Harbinger Mikolaas has done a commendable job of safeguarding Blood Watch, , but our enemies are many and our resources few. Our weakness is well known to our enemies, but your contact with the forces of the Alliance is something they haven't accounted for. I have prepared a letter of introduction to the people of Auberdine, the closest Alliance settlement, proposing cooperation in the fight against our foes. Take it with you and seek out Huntress Kella Nightbow near the docks west of the Exodar.",starts={{npcID=17424,x=0.546,y=0.54,mapID=106}},ends={{npcID=17614,x=0.242,y=0.542,mapID=97}},coords={x=0.546,y=0.54,source="quest_giver",mapID=97},questType="standard"},
[9708] = {id=9708,name="Familiar Fungi",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3521,mapID=102,description="Yes, that's it, I knew I had seen this particular phylum of mushroom elsewhere in the marsh! To the north is a place known as the Hewn Bog. Odd name for the place if you ask me, but I've never been there. I'll need samples of those mushrooms to confirm my hypothesis. Just be careful, . I'd heard that ogres have moved in to the area, so you'll have to get the samples from them. Could that be why the bog lords are no longer going there for their food?",starts={{npcID=17831,x=0.232,y=0.662,mapID=102}},ends={{npcID=17831,x=0.232,y=0.662,mapID=102}},coords={x=0.232,y=0.662,source="quest_giver",mapID=102},questType="standard"},
[10238] = {id=10238,name="How to Serve Goblins",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3483,mapID=100,description="Why would fel orcs steal my shredder parts? I hate them so much. They just sneak into my camp here and take things all the time. A couple of days ago they stole three of my peons! Now the rest of my peons have run off because they are afraid they are going to be eaten by fel orcs. I can't run a mine without peons. If you could save the peons that I lost maybe the others would come back. The fel orcs have their camps along the wall to the southwest.",starts={{npcID=16915,x=0.512,y=0.306,mapID=100}},ends={{npcID=16915,x=0.512,y=0.306,mapID=100}},coords={x=0.512,y=0.306,source="quest_giver",mapID=100},questType="standard"},
[10255] = {id=10255,name="Testing the Antidote",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3483,mapID=100,description="I think there's something we can use in the blood as the base of an antidote. Don't look at me like I've lost my mind! It's a common theme in nature. Often, the cure for something can be derived from the toxin itself. That's just what I aim to do. Ridding the boars of their demonic influence would probably eliminate their aggression and give us insight into how to best attempt to help other species.",starts={{npcID=16991,x=0.156,y=0.522,mapID=100}},ends={{npcID=16991,x=0.156,y=0.522,mapID=100}},coords={x=0.156,y=0.522,source="quest_giver",mapID=100},questType="standard"},
[10839] = {id=10839,name="Veil Skith: Darkstone of Terokk",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3519,mapID=108,description="Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed. Take this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.",starts={{npcID=22272,x=0.374,y=0.514,mapID=108}},ends={{npcID=22272,x=0.374,y=0.514,mapID=108}},coords={x=0.374,y=0.514,source="quest_giver",mapID=108},questType="standard"},
[10900] = {id=10900,name="The Mark of Vashj",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,questType="raid"},
[10920] = {id=10920,name="For the Fallen",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3519,mapID=108,description="When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle. We pursued the creatures into the night. Some of our people we found dead in the dark, others we could hear struggling against their captors. By morning we had come to this place and we fought a fierce battle but we were beaten. Dreadfang poison will soon take my companions and I cannot last long. Before I die I must know that the dreadfang widows were beaten.",starts={{npcID=22462,x=0.496,y=0.762,mapID=108}},ends={{npcID=22462,x=0.496,y=0.762,mapID=108}},coords={x=0.496,y=0.762,source="quest_giver",mapID=108},questType="standard"},
[24993] = {id=24993,name="Annihilate the Worgen",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=85,description="These worgen must be dealt with, and quickly. Our first priority is to eliminate any which may have infiltrated Brill. I want you to be on the lookout for any suspicious activity here in Brill, . We know that these worgen can hide in the shadows, so look for any signs you can find... footsteps, kicked-up rocks... anything.",starts={{npcID=1515,x=0.604,y=0.518,zoneID=85}},ends={{npcID=1515,x=0.604,y=0.518,zoneID=85}},coords={x=0.604,y=0.518,source="quest_giver",zoneID=85},questType="standard"},
[25039] = {id=25039,name="Have You Seen Anything Weird Out There?",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=85,description="! Listen up, I got somethin'... odd to discuss. I was out fishin' by Brightwater Lake when I saw the darnedest thing... some sorta wolf-man, running around Tirisfal. Ya don't suppose that could be a... worgen, do ya? Anyway, I keep tellin' myself I should tell Executor Zygand about it, but I just get so scared when I talk to that guy. Maybe you could talk with him?",starts={{npcID=6785,x=0.618,y=0.518,zoneID=85}},ends={{npcID=1515,x=0.604,y=0.518,zoneID=85}},coords={x=0.618,y=0.518,source="quest_giver",zoneID=85},questType="standard"},
[29393] = {id=29393,name="Brew For Brewfest",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,description="So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be? Now before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures. So here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams. Keep the ram at a trot, canter and gallop for 8 seconds each.",ends={{npcID=24497,x=0.426,y=0.178,zoneID=14}},questType="standard"},
[29400] = {id=29400,name="A Season for Celebration",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=85,description="Well met, . Hallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken. Travel to the Ruins of Lordaeron and speak to Darkcaller Yanka . She can tell you more about the Wickerman ceremony.",starts={{npcID=19169,x=0.542,y=0.508,zoneID=3430},{npcID=19169,x=0.778,y=0.576,zoneID=3487},{npcID=19175,x=0.516,y=0.752,zoneID=1637},{npcID=19176,x=0.402,y=0.488,zoneID=1637},{npcID=19177,x=0.49,y=0.612,zoneID=1637},{npcID=19176,x=0.41,y=0.558,zoneID=1638},{npcID=19178,x=0.632,y=0.48,zoneID=1497},{npcID=20102,x=0.69,y=0.706,zoneID=17},{npcID=20102,x=0.406,y=0.844,zoneID=67},{npcID=20102,x=0.522,y=0.284,zoneID=440},{npcID=20102,x=0.598,y=0.496,zoneID=618},{npcID=20102,x=0.338,y=0.64,zoneID=3523},{npcID=20102,x=0.53,y=0.504,zoneID=3703},{npcID=20102,x=0.416,y=0.742,zoneID=5287},{npcID=220307,x=0.46,y=0.548,zoneID=14771},{npcID=220870,x=0.554,y=0.61,zoneID=14771},{npcID=220307,x=0.512,y=0.764,zoneID=15969}},ends={{npcID=15197,x=0.672,y=0.128,zoneID=1497},{npcID=15197,x=0.62,y=0.678,zoneID=85}},coords={x=0.542,y=0.508,source="quest_giver",zoneID=3430},questType="standard"},
[29401] = {id=29401,name="Blown Away",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,description="Please, , you just gotta help me! My pa brought me a bunch of balloons from the Darkmoon Faire. Best... gift... EVER! They're magical, you know, and never lose their floatiness! There's just one thing... A big ol' gust of wind blew 'em right outta my hands. They're scattered all over Orgrimmar ! I'd chase after 'em myself, but this city's so big I'd get lost for sure. Can you round 'em up for me before they float away? Please?",starts={{npcID=54004,x=0.48,y=0.47,zoneID=1637}},ends={{npcID=54004,x=0.48,y=0.47,zoneID=1637}},coords={x=0.48,y=0.47,source="quest_giver",zoneID=1637},questType="standard"},
[29402] = {id=29402,name="Taking Precautions",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=10413,description="I'd be wary of anyone identifying himself as the rightful owner of the crate and its contents. He didn't warn you of the danger? Here's a better idea: let's work together to recover the crate and ensure that its contents can't hurt anyone. To protect ourselves, we're going to need a draught made from a few ingredients that can be found around the city. Acquire some strange dust , get vials from an alchemy merchant, and pick some blood nettle from the fields north of the city.",starts={{npcID=54021,x=0.64,y=0.464,zoneID=1519}},ends={{npcID=54021,x=0.64,y=0.464,zoneID=1519}},coords={x=0.64,y=0.464,source="quest_giver",zoneID=1519},questType="standard"},
[29403] = {id=29403,name="The Collector's Agent",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=85,description="According to Quincy, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara. The archmage's faithful servant is to meet with the man who has the crate in the catacombs beneath the Cathedral of Light. You must get there in time to intercept the exchange and retrieve the crate before it is lost to Xylem forever. When you have the crate, meet me at the Golden Keg.",starts={{npcID=54021,x=0.64,y=0.464,zoneID=1519}},ends={{npcID=209072,x=0.553,y=0.435,zoneID=1519}},coords={x=0.64,y=0.464,source="quest_giver",zoneID=1519},questType="standard"},
[29404] = {id=29404,name="Much to Learn",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi.",questType="standard"},
[29405] = {id=29405,name="The Lesson of the Iron Staff",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="To train, first you must be properly equipped. Retrieve a weapon from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.",questType="standard"},
[29406] = {id=29406,name="The Lesson of the Sandy Fist",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="I'd like to observe you putting your new weapon to use, my young student. This will aid me in determining what degree of training will be best suited to your talents. We have many training targets in the training grounds below. Practice your attacks upon them, and return to me once you're feeling comfortable with your new weapon.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[29407] = {id=29407,name="The First Sign of Winter",level=1,requiredLevel=1,faction="none",expansion=4,zoneID=5736,mapID=378,description="At the stream below rests a single lotus flower. Within this lotus lies a sign of things to come. Bring it to me that I might show you.",questType="standard"},
[29408] = {id=29408,name="The Lesson of the Burning Scroll",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Every wisdom has a time and place, and times are changing for those of us living here on Shen-zin Su. For this lesson, I would ask two things of you. For the first, I hold a flame in my hand. Gather your wits, and when you think you are ready, attempt to snatch the flame. Should you succeed, I want you to then climb to the top of this temple and burn the Edict of Temperance that you find there.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[29409] = {id=29409,name="The Disciple's Challenge",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", I see great strength and great courage in you, and an unsurpassed purity of soul. The hour is young, but I think you may be ready to face a greater challenge. Go to the bottom of the stairs, and cross the bridge. There, you will find Jaomin Ro , one of our eldest students. Challenge and defeat him in honorable combat, and this first phase of your training will be complete.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[29410] = {id=29410,name="Aysa of the Tushui",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="In such a short time, you've shown me that you have the potential to be a great . The training grounds are behind you, but now you must prove yourself by facing a far greater challenge, one that none of my students have accomplished. I want you to return Huo, the spirit of fire, to the Temple of Five Dawns. My two other most gifted students will help you in this task. The first is Aysa Cloudsinger. Seek her out at the pool to the west.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=54943,x=0.55,y=0.326,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[29411] = {id=29411,name="What Now?",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,description="You've finally found the crate that Anson sent you to retrieve. However, it appears the archaeology student's warnings about the nature of the crate's contents were correct. There's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Hudson Barnes , who believes it better to keep the crate's contents locked away?",starts={{npcID=209072,x=0.553,y=0.435,zoneID=1519}},ends={{npcID=53949,x=0.602,y=0.752,zoneID=1519},{npcID=54118,x=0.65,y=0.332,zoneID=1519}},coords={x=0.553,y=0.435,source="quest_giver",zoneID=1519},questType="standard"},
[29412] = {id=29412,name="Blown Away",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1519,description="Please, , you just gotta help me! Father bought me a bunch of balloons from the Darkmoon Faire. They're magical, you know, and never lose their floatiness! There's just one thing... A gust of wind blew them out of my hands. They're scattered all over Stormwind! I'd chase after them myself, but this city's so big I'd get lost for sure. Can you find them for me before they float away? Please?",starts={{npcID=54117,x=0.588,y=0.528,zoneID=1519}},ends={{npcID=54117,x=0.588,y=0.528,zoneID=1519}},coords={x=0.588,y=0.528,source="quest_giver",zoneID=1519},questType="standard"},
[29413] = {id=29413,name="The Creepy Crate",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,description="It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him. Yet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive. It seems bonded to you and now it's yours.",ends={{npcID=209076,x=0.651,y=0.333,zoneID=1519}},questType="standard"},
[29414] = {id=29414,name="The Way of the Tushui",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="It's a pleasure to meet you, . I am Aysa, of the Tushui. I've spent much time in thought since Master Shang told me we would be searching for Huo, the spirit of fire. I know where he resides, but not how to reach him. The answers are close, however. Come with me to the Cave of Meditation nearby. It is a place of great wisdom. I will meditate there, open my mind, and the path shall find us.",starts={{npcID=54567,x=0.55,y=0.324,zoneID=5736}},ends={{npcID=54608,x=0.576,y=0.348,zoneID=5736}},coords={x=0.55,y=0.324,source="quest_giver",zoneID=5736},questType="standard"},
[29415] = {id=29415,name="Missing Heirlooms",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,description="I told that courier to take the zeppelin, but no, he had to use the goblin ship! Well, now he's late and my precious family heirlooms are with him. If you're willing to help, would you go down to the docks east of Orgrimmar, board the goblin ship and see what's keeping him?",starts={{npcID=54141,x=0.544,y=0.778,zoneID=1637}},ends={{npcID=54142,x=0.574,y=0.09,zoneID=14}},coords={x=0.544,y=0.778,source="quest_giver",zoneID=1637},questType="standard"},
[29416] = {id=29416,name="Fencing the Goods",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="A quick search of the cabin reveals no evidence of the killer's identity or motives. The crate you were sent to retrieve has vanished. As you turn to leave the cabin, you notice something small moving underfoot. A trail of spiders crawls out from under the slain courier's bed. Where could they be heading?",starts={{npcID=54142,x=0.574,y=0.09,zoneID=14}},ends={{npcID=44866,x=0.54,y=0.734,zoneID=1637}},coords={x=0.574,y=0.09,source="quest_giver",zoneID=14},questType="standard"},
[29417] = {id=29417,name="The Way of the Huojin",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="We call those vicious monkeys swinging into town hozen. They keep to themselves normally, but they know something bad is coming, so they're here to steal our supplies. In situations like this, the clear answer is the only answer. These monkeys will leave when we force them to leave! To not defend our town and those we love would be the only true crime. Thus is the way of the Huojin.",starts={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},ends={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},coords={x=0.502,y=0.214,source="quest_giver",zoneID=5736},questType="standard"},
[29418] = {id=29418,name="Kindling the Fire",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Now that that's done with, let's get to it then! Huo, the spirit of fire, hungers for dry dogwood root kindling. It grows among the trees south of the village. It should be easy enough for you to gather some.",starts={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},ends={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},coords={x=0.502,y=0.214,source="quest_giver",zoneID=5736},questType="standard"},
[29419] = {id=29419,name="The Missing Driver",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="My driver went running off after the sprites just after they attacked. I don't think they'll really do him any harm, but I need him back to help me clean up the mess by the cart. He chased them off towards the cliffs to the north. If you head that direction, you should find him quickly.",starts={{npcID=54943,x=0.55,y=0.326,zoneID=5736}},ends={{npcID=54943,x=0.55,y=0.326,zoneID=5736}},coords={x=0.55,y=0.326,source="quest_giver",zoneID=5736},questType="standard"},
[29420] = {id=29420,name="The Spirit's Guardian",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="You've done very well this far, my student. You have the materials you need to rekindle Huo, the spirit of fire. In the cave to the southwest he awaits, but he is guarded by Master Li Fei , the pandaren elder you met in the Cave of Meditation. Go to Master Li Fei with the offerings. Prove yourself, then meet with Huo.",starts={{npcID=54609,x=0.502,y=0.214,zoneID=5736}},ends={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},coords={x=0.502,y=0.214,source="quest_giver",zoneID=5736},questType="standard"},
[29421] = {id=29421,name="Only the Worthy Shall Pass",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="It is time for you to face me. With these three fires illuminating your potential, we will see with certainty whether your resolved soul is truly worthy of passing.",starts={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},ends={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},coords={x=0.388,y=0.254,source="quest_giver",zoneID=5736},questType="standard"},
[29422] = {id=29422,name="Huo, the Spirit of Fire",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="You are worthy of passing, . Huo , the spirit of fire rests in the chamber beyond. Let him feast upon the kindling you've gathered, and use the wind to fan his flames. Doing so should endear you to him. Once he is ignited, if he is willing, lead him to the Temple of Five Dawns, the building standing high in the center of the island.",starts={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},ends={{npcID=54787,x=0.394,y=0.294,zoneID=5736},{npcID=57779,x=0.392,y=0.292,zoneID=5736}},coords={x=0.388,y=0.254,source="quest_giver",zoneID=5736},questType="standard"},
[29423] = {id=29423,name="The Passion of Shen-zin Su",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Huo bounces around excitedly, ready to follow you.> Master Shang Xi told you to bring Huo to meet him at the Temple of Five Dawns in the center of the island. Your next destination lies before you.>",starts={{npcID=54787,x=0.394,y=0.294,zoneID=5736}},ends={{npcID=54786,x=0.514,y=0.462,zoneID=5736}},coords={x=0.394,y=0.294,source="quest_giver",zoneID=5736},questType="standard"},
[29424] = {id=29424,name="Items of Utmost Importance",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Amberleaf scamps swarmed my cart and stole most of the training supplies I was bringing up to the training grounds. They've always been troublemakers, but they've never been this aggressive before. I don't know what happened. Please, help me recover my supplies.",starts={{npcID=54943,x=0.55,y=0.326,zoneID=5736}},ends={{npcID=54943,x=0.55,y=0.326,zoneID=5736}},coords={x=0.55,y=0.326,source="quest_giver",zoneID=5736},questType="standard"},
[29425] = {id=29425,name="Shopping Around",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="Look, I told that shady character that there might be a shop more open to his, uh, wares in the Drag. Droffer's and Son Salvage is the name of the place. Look for Dran Droffers. He oversees the 'salvage' of rare and valuable objects from all over Azeroth.",starts={{npcID=44866,x=0.54,y=0.734,zoneID=1637}},ends={{npcID=54146,x=0.58,y=0.482,zoneID=1637}},coords={x=0.54,y=0.734,source="quest_giver",zoneID=1637},questType="standard"},
[29426] = {id=29426,name="Taking Precautions",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=10413,description="So someone else hired you to retrieve this crate? I don't like the sound of that. That crate's contents belong in the care of the Reliquary. The items it holds are very powerful and very dangerous. We have to find the meeting that Dran set up between the thief and the collector, but first, we'll need to protect ourselves from the effects of handling that crate. Acquire some strange dust , get vials from an alchemy merchant, and pick some blood nettle in the Valley of Wisdom.",starts={{npcID=54146,x=0.58,y=0.482,zoneID=1637}},ends={{npcID=54146,x=0.58,y=0.482,zoneID=1637}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=1637},questType="standard"},
[29427] = {id=29427,name="The Collector's Agent",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1519,description="According to Dran, the \"collector\" who wants the crate is none other than the insane Archmage Xylem of Azshara. The archmage's faithful servant is to meet with the man who has the crate in a secluded corner of the courtyard in the Ruins of Lordaeron. Quickly, take the zeppelin to Tirisfal Glade! You must get there in time to intercept the exchange and retrieve the crate before Xylem gets his hands on it. If you can get the crate, meet me at the Wyvern's Tail in the Valley of Honor.",starts={{npcID=54146,x=0.58,y=0.482,zoneID=1637}},ends={{npcID=209094,x=0.658,y=0.747,zoneID=85},{npcID=209094,x=0.658,y=0.747,zoneID=1497}},coords={x=0.58,y=0.482,source="quest_giver",zoneID=1637},questType="standard"},
[29428] = {id=29428,name="What Now?",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="You've finally found the crate that Edgar Goodwin sent you to retrieve. However, it appears the Reliquary representative's warnings about the nature of the crate's contents were correct. There's no doubt that your employer lied to you about the dangers involved in the job. Do you really want to hand the crate over to him, or would you rather give it to Delian Sunshade , who believes it better to keep the crate's contents locked away?",starts={{npcID=209094,x=0.658,y=0.747,zoneID=85},{npcID=209094,x=0.658,y=0.747,zoneID=1497}},ends={{npcID=54141,x=0.544,y=0.778,zoneID=1637},{npcID=54170,x=0.716,y=0.498,zoneID=1637}},coords={x=0.658,y=0.747,source="quest_giver",zoneID=85},questType="standard"},
[29429] = {id=29429,name="The Creepy Crate",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="It's been sought after, stolen, and sold. Anyone who tried to tap the magic held within has seen that power turn against him. Yet, the crate itself appears unscathed and suffused with magical energy. From time to time, it shakes or bobs as if its contents were alive. It seems bonded to you and now it's yours.",ends={{npcID=209095,x=0.545,y=0.778,zoneID=1637}},questType="standard"},
[29430] = {id=29430,name="A Friend in Need",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,description="You know, I haven't seen Anson out here yet. Lately, he's been spending all his time drinking himself into a stupor at the Gilded Rose. Something must really be bothering him! Would you mind checking in on him?",starts={{npcID=51934,x=0.322,y=0.508,zoneID=12}},ends={{npcID=53949,x=0.602,y=0.752,zoneID=1519}},coords={x=0.322,y=0.508,source="quest_giver",zoneID=12},questType="standard"},
[29431] = {id=29431,name="A Friend in Need",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="There's something wrong with my friend, Edgar. Normally, he loves the Hallow's End festivities, but he's been sullen and reclusive lately. He spends all his time in the Broken Tusk in Orgrimmar drinking with the orcs. Would you mind stopping by and seeing if there's anything you can do to cheer him up?",starts={{npcID=53763,x=0.624,y=0.668,zoneID=85},{npcID=53763,x=0.686,y=0.08,zoneID=1497}},ends={{npcID=54141,x=0.544,y=0.778,zoneID=1637}},coords={x=0.624,y=0.668,source="quest_giver",zoneID=85},questType="standard"},
[29432] = {id=29432,name="Delegation Tracker",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=616,mapID=198,description="I am duty-bound to look into your claims immediately, , which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.",questType="raid"},
[29433] = {id=29433,name="Test Your Strength",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="For some people, it's all fun and games until someone gets hurt. I call those people, weak. To be the strongest, you have to hurt someone or something. You hurt yourself as you push your body to its limits. You hurt those that threaten the well-being of others. If you want to be the strongest, you have to fight. How bad do you want it? I want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.",starts={{npcID=14832,x=0.48,y=0.67,zoneID=5861}},ends={{npcID=14832,x=0.48,y=0.67,zoneID=5861}},coords={x=0.48,y=0.67,source="quest_giver",zoneID=5861},questType="standard"},
[29434] = {id=29434,name="Tonk Commander",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Welcome to our humble little steam tank battle simulator! For one token, you can demonstrate your tactical mastery by navigating the course and destroying the targets.",starts={{npcID=54605,x=0.506,y=0.65,zoneID=5861}},ends={{npcID=54605,x=0.506,y=0.65,zoneID=5861}},coords={x=0.506,y=0.65,source="quest_giver",zoneID=5861},questType="standard"},
[29436] = {id=29436,name="The Humanoid Cannonball",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="For just one Darkmoon Game Token, you can ride the Blastenheimer 5000 Ultra Cannon. But the fun doesn't end there! We've placed a target in the water near the boardwalk. If you can score five points from your landing, you can win some prize tickets! A bullseye gets you five points, a close shot three, and landing at least near it gets you one. Happy landings!",starts={{npcID=15303,x=0.526,y=0.56,zoneID=5861}},ends={{npcID=15303,x=0.526,y=0.56,zoneID=5861}},coords={x=0.526,y=0.56,source="quest_giver",zoneID=5861},questType="standard"},
[29437] = {id=29437,name="The Fallen Guardian",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=616,description="Fandral Staghelm was kept prisoner here in Hyjal. It was the green dragon Alysra - one of my very own! - who was in charge of keeping Fandral secure. We can only conclude that the Twilight's Hammer has gotten to her. You must confront her, . Destroy her if you must - I cannot bear to see it. She was last seen in the Ruins of Lar'donir, west of the World Tree.",starts={{npcID=40289,x=0.62,y=0.248,zoneID=616},{npcID=52793,x=0.602,y=0.298,zoneID=616}},coords={x=0.62,y=0.248,source="quest_giver",zoneID=616},questType="standard"},
[29438] = {id=29438,name="He Shoots, He Scores!",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Think you're a good shot? Quick on the trigger? It'll cost you just a single game token to test your skills. What do you say? How good are you?",starts={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},ends={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},coords={x=0.494,y=0.608,source="quest_giver",zoneID=5861},questType="standard"},
[29439] = {id=29439,name="The Call of the World-Shaman",level=35,requiredLevel=35,faction="alliance",expansion=4,zoneID=616,description="The Earthen Ring calls to you once more, . As a member of the Alliance, I know that you may have reservations working with the one you call Thrall , the former Warchief of the Horde. But he has specifically requested an Alliance hero to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world. Cast aside your doubts, , and heed the world-shaman's call. You will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree.",starts={{npcID=45226,x=0.744,y=0.188,zoneID=1519}},ends={{npcID=54313,x=0.606,y=0.314,zoneID=616}},coords={x=0.744,y=0.188,source="quest_giver",zoneID=1519},questType="standard"},
[29440] = {id=29440,name="The Call of the World-Shaman",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=616,description="The Earthen Ring calls to you once more, . Thrall has cast aside his mantle as warchief of the Horde, but in his new role he needs the support of his people more than ever. He has requested one of the Horde's finest to accompany him in his next endeavor, a ritual of healing that will profoundly impact our world. You will find him under the boughs of Nordrassil in Mount Hyjal, on the southern side of the tree. Heed the call!",starts={{npcID=45244,x=0.504,y=0.382,zoneID=1637}},ends={{npcID=54313,x=0.606,y=0.314,zoneID=616}},coords={x=0.504,y=0.382,source="quest_giver",zoneID=1637},questType="standard"},
[29441] = {id=29441,name="From the Belly of the Beast",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=130,mapID=21,questType="standard"},
[29443] = {id=29443,name="A Curious Crystal",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5788,description="Power swirls inside this strange crystal. Perhaps it was once a magical focus, an energy source, or simply a good luck charm. There's no way to know for certain. The Darkmoon Adventurer's Guide indicates that the crystal would be of interest to Professor Thaddeus Paleo at the Darkmoon Faire.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29444] = {id=29444,name="An Exotic Egg",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5789,description="You're not certain what kind of creature this egg harbors, but it sure doesn't look like the egg of any ordinary animal. The Darkmoon Adventurer's Guide says that an intrepid adventurer might come across any number of strange eggs in his travels. It further notes that the Darkmoon Faire's Zoo Bizarre is always interested in acquiring such specimens. Take the egg to Yebb Neblegear at the Darkmoon Faire.",ends={{npcID=14829,x=0.51,y=0.818,zoneID=5861}},questType="standard"},
[29445] = {id=29445,name="An Intriguing Grimoire",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5844,description="This massive spellbook reveals very little of its origins. Its pages are filled with a variety of spells and enchantments, only a few of which are familiar. The Darkmoon Adventurer's Guide says the tome may be of some interest to Sayge , the famous gnoll fortuneteller at the Darkmoon Faire.",ends={{npcID=14822,x=0.53,y=0.758,zoneID=5861}},questType="standard"},
[29446] = {id=29446,name="A Wondrous Weapon",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5788,description="An inspection of the weapon reveals expert craftsmanship and intricate inlay work, but this is no ceremonial blade. Faint marks and nicks along the blade attest to its use in combat. The Darkmoon Adventurer's Guide lists several types of rare and valuable weapons, leaving no doubt that Professor Thaddeus Paleo at the Darkmoon Faire would be interested in taking a look at this piece.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29451] = {id=29451,name="The Master Strategist",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5788,description="This tome of strategy is the masterwork of the famous human general, Anduin Lothar. In his own words, the commander describes the proper deployment of forces and strategies needed to win almost any battle. Professor Thaddeus Paleo of the Darkmoon Faire would probably love to have a look at such a rare book.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29452] = {id=29452,name="Your Time Has Come",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=1637,description="Young , be still and hear my words. I am called to collect you, to deliver you, to one whose eye none can escape. Find me in Orgrimmar, mortal, for your time has come.",ends={{npcID=52382,x=0.488,y=0.704,zoneID=1637}},questType="standard"},
[29453] = {id=29453,name="Your Time Has Come",level=35,requiredLevel=35,faction="alliance",expansion=4,zoneID=1519,description="Young , be still and hear my words. I am called to collect you, to deliver you, to one whose eye none can escape. Find me in Stormwind, mortal, for your time has come.",ends={{npcID=52408,x=0.494,y=0.874,zoneID=1519}},questType="standard"},
[29455] = {id=29455,name="Target: Turtle",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Hey there! Step right up ! Why not show everyone how skilled you are? Just land three rings on the Darkmoon Turtle and you'll get a prize. For one game token you can buy a stack of rings and show the world why we call you the \"Eagle Eyed .\"",starts={{npcID=54485,x=0.514,y=0.778,zoneID=5861}},ends={{npcID=54485,x=0.514,y=0.778,zoneID=5861}},coords={x=0.514,y=0.778,source="quest_giver",zoneID=5861},questType="standard"},
[29456] = {id=29456,name="A Captured Banner",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=10440,description="This tattered banner bears a faded guild crest. This old banner must've seen more than its share of battles. Professor Thaddeus Paleo of the Darkmoon Faire collects banners and other relics of combat and he might be interested in acquiring this one. Show the banner to him next time you visit the Darkmoon Faire.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29457] = {id=29457,name="The Enemy's Insignia",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=10440,description="This battered badge carries the insignia of an enemy officer. While worth little more to you than the metal it's made from, this piece would have significant value to a collector of military memorabilia. Professor Thaddeus Paleo of the Darkmoon Faire is famous all over Azeroth for his large collection of military artifacts. Show the badge to him the next time you visit the Darkmoon Faire.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29458] = {id=29458,name="The Captured Journal",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=10440,description="This book is covered in battered leather stained with blood and mud. Leafing through the pages, you discover that it is a personal journal of an adventurer with a high opinion of himself and his adventures. Professor Thaddeus Paleo of the Darkmoon Faire might want to see something like this.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29463] = {id=29463,name="It's Hammer Time",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="So you want to whack some gnolls? Well you've come to the right place. Your goal is simple, score 30 points in a minute. Use the mallet I give you and get ready to whack. Speak to me when you are ready to start.",starts={{npcID=54601,x=0.532,y=0.546,zoneID=5861}},ends={{npcID=54601,x=0.532,y=0.546,zoneID=5861}},coords={x=0.532,y=0.546,source="quest_giver",zoneID=5861},questType="standard"},
[29464] = {id=29464,name="Tools of Divination",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5892,description="This collection of well-worn runestones has seen much use. The pieces seem old; you can't recognize any of the markings on their surfaces. Perhaps a scholar or a collector would know more about them. Bring them to Professor Thaddeus Paleo next time you're at the Darkmoon Faire.",ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},questType="standard"},
[29475] = {id=29475,name="Goblin Engineering",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=1638,mapID=88,description="A skilled engineer can choose ONE specialization, and I know the secrets of goblin engineering. You look like you're ready to blow things up, but I'll need some samples of your work. Bring me twenty big iron bombs , twenty sticks of solid dynamite , and five explosive sheep . Submit these items to an engineering trainer in any of the capital cities and you'll be an official goblin engineer with access to all the schematics!",starts={{npcID=5174,x=0.684,y=0.442,mapID=87},{npcID=5518,x=0.628,y=0.32,mapID=84},{npcID=11017,x=0.568,y=0.564,mapID=85},{npcID=52651,x=0.364,y=0.596,mapID=88}},ends={{npcID=5174,x=0.684,y=0.442,mapID=87},{npcID=5518,x=0.628,y=0.32,mapID=84},{npcID=11017,x=0.568,y=0.564,mapID=85},{npcID=52651,x=0.364,y=0.596,mapID=88}},coords={x=0.684,y=0.442,source="quest_giver",mapID=88},questType="standard"},
[29477] = {id=29477,name="Gnomish Engineering",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=1637,description="A skilled engineer can choose ONE specialization, and I can teach you the ways of gnomish engineering. You look like you know what you're doing, but I'll need some samples of your work. Bring me six mithril tubes , an accurate scope , and two advanced target dummies. Submit these items to an engineering trainer in any of the capital cities and you'll be an official gnomish engineer with access to all the schematics!",starts={{npcID=5174,x=0.684,y=0.442,zoneID=1537},{npcID=5518,x=0.628,y=0.32,zoneID=1519},{npcID=11017,x=0.568,y=0.564,zoneID=1637}},ends={{npcID=7944,x=0.698,y=0.502,zoneID=1537},{npcID=5518,x=0.628,y=0.32,zoneID=1519},{npcID=11017,x=0.568,y=0.564,zoneID=1637}},coords={x=0.684,y=0.442,source="quest_giver",zoneID=1537},questType="standard"},
[29481] = {id=29481,name="Elixir Master",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=1519,description="Elixirs are all about potency! If you want to become an elixir master , I can teach you. I can't just train anyone, and I require proof that you are devoted before we continue. Several flasks should be sufficient to show your dedication. Remember , you can only learn ONE specialization, so if you complete your elixir training, then potion and transmutation specialization will no longer be available.",starts={{npcID=3347,x=0.556,y=0.458,zoneID=1637},{npcID=5499,x=0.556,y=0.858,zoneID=1519}},ends={{npcID=3347,x=0.556,y=0.458,zoneID=1637},{npcID=5499,x=0.556,y=0.858,zoneID=1519}},coords={x=0.556,y=0.458,source="quest_giver",zoneID=1637},questType="standard"},
[29482] = {id=29482,name="Transmutation Master",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=1497,mapID=90,description="Iron to gold, water to fire... if you want to become an transmutation master , then I can show you the way. The training is very expensive, so you'll have to bring me some of the finest transmuted materials in the world. Remember , you can only learn ONE specialization, so if you complete your transmutation training, then potion and elixir specialization will no longer be available.",starts={{npcID=3347,x=0.556,y=0.458,mapID=85},{npcID=5177,x=0.666,y=0.55,mapID=87},{npcID=5499,x=0.556,y=0.858,mapID=84}},ends={{npcID=3347,x=0.556,y=0.458,mapID=85},{npcID=5177,x=0.666,y=0.55,mapID=87},{npcID=5499,x=0.556,y=0.858,mapID=84},{npcID=4611,x=0.476,y=0.728,mapID=90}},coords={x=0.556,y=0.458,source="quest_giver",mapID=90},questType="standard"},
[29506] = {id=29506,name="A Fizzy Fusion",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="I'm sure you've made a lot of potions in your time as an alchemist. How would you like to help with something a bit more light-hearted? I've always wanted to try creating a fruit-flavored version of our popular fizzy drinks. If you're willing to give it a try, you can buy some of the base drink from me and mix it with some moonberry juice. Any innkeeper in Elwynn Forest or Mulgore should be able to sell you enough juice to make your creation.",starts={{npcID=14844,x=0.502,y=0.694,zoneID=5861}},ends={{npcID=14844,x=0.502,y=0.694,zoneID=5861}},coords={x=0.502,y=0.694,source="quest_giver",zoneID=5861},questType="standard"},
[29507] = {id=29507,name="Fun for the Little Ones",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Children are always full of questions about what an archaeologist does and how it works, so I prepared a demonstration for them. I take artifacts and fossils and bury them in the sandbox beside the tent. The children get to dig and make their own discoveries, learn how bones fit together, and see how archaeology can teach them about history. If you have any spare fossils, would you consider donating them to my side project?",starts={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},ends={{npcID=14847,x=0.518,y=0.606,zoneID=5861}},coords={x=0.518,y=0.606,source="quest_giver",zoneID=5861},questType="standard"},
[29508] = {id=29508,name="Baby Needs Two Pair of Shoes",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="You may have seen my horse, Baby , over near the wagons. She pulls the cart that hauls some of the animals in our Zoo Bizarre. She's a hard worker and she tears through shoes like you wouldn't believe. It's about time for a new set. I've already bought the raw materials. All you need to do is shape them over an anvil and apply them to Baby 's feet. It's a quick job and worth some tickets, wouldn't you say?",starts={{npcID=14829,x=0.51,y=0.818,zoneID=5861}},ends={{npcID=14829,x=0.51,y=0.818,zoneID=5861}},coords={x=0.51,y=0.818,source="quest_giver",zoneID=5861},questType="standard"},
[29509] = {id=29509,name="Putting the Crunch in the Frog",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The Darkmoon Faire's crunchy frog is famous all over Azeroth! We've just had a fresh batch of frogs delivered. How'd you like to help whip up a few and practice your cooking skills in the process? You can get the flour you'll need to bread the frogs from any trade goods vendor in Elwynn Forest or Mulgore.",starts={{npcID=14845,x=0.526,y=0.68,zoneID=5861}},ends={{npcID=14845,x=0.526,y=0.68,zoneID=5861}},coords={x=0.526,y=0.68,source="quest_giver",zoneID=5861},questType="standard"},
[29510] = {id=29510,name="Putting Trash to Good Use",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="People don't just come to the faire for fun and fortunes, . Most want something to take home with them, so I help to create the magical trinkets visitors purchase with their prize tickets. For that, I need a steady supply of soothsayer's dust . Take a look around the grounds and you'll see a lot of discarded weapons . Those are just the kinds of items that can be broken down into dust with enchanting skills like yours. Would you like to help?",starts={{npcID=14822,x=0.53,y=0.758,zoneID=5861}},ends={{npcID=14822,x=0.53,y=0.758,zoneID=5861}},coords={x=0.53,y=0.758,source="quest_giver",zoneID=5861},questType="standard"},
[29511] = {id=29511,name="Talkin' Tonks",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The steam tonks are one of the Darkmoon Faire's most popular amusements. Our visitors love to test their skills for hours and hours, but the tonks take a real beating from all that fun. You look like you know your way around a wrench. Mind helping me fix some of the damaged tonks and return them to working order? I'll compensate you for your time.",starts={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},ends={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},coords={x=0.494,y=0.608,source="quest_giver",zoneID=5861},questType="standard"},
[29513] = {id=29513,name="Spoilin' for Salty Sea Dogs",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="We've just introduced another exciting new menu item, the salty sea dog. It's so popular, we can barely keep up with the demand! You look like a decent angler and a spry . Would you help me restock my fish supplies? We wouldn't want to disappoint all those faire-goers looking to try a new food, would we?",starts={{npcID=14845,x=0.526,y=0.68,zoneID=5861}},ends={{npcID=14845,x=0.526,y=0.68,zoneID=5861}},coords={x=0.526,y=0.68,source="quest_giver",zoneID=5861},questType="standard"},
[29514] = {id=29514,name="Herbs for Healing",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The little purple flowers that grow wild around the grounds aren't just pretty. They play a role in everything from treating wounds to seasoning food. You seem to have some talent for harvesting herbs. Would you like to help me rebuild my stocks of darkblossom ?",starts={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},ends={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=5861},questType="standard"},
[29515] = {id=29515,name="Writing the Future",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="As the popularity of the Darkmoon Faire grows, more and more people seek me out to peer into their futures. Most times, they ask for knowledge best left hidden in the mists of time, but it is not my place to give such advice. My stock of written fortunes is running low and you look to have a steady hand. Take these herbs, make ink from them, and pen a few fortunes for me. You can get the parchment you'll need from any trade goods vendor in Elwynn Forest or Mulgore.",starts={{npcID=14822,x=0.53,y=0.758,zoneID=5861}},ends={{npcID=14822,x=0.53,y=0.758,zoneID=5861}},coords={x=0.53,y=0.758,source="quest_giver",zoneID=5861},questType="standard"},
[29516] = {id=29516,name="Keeping the Faire Sparkling",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The Darkmoon Faire's performers and animals go through more jewelry than I'd ever imagined. Thankfully, the gems are just cut glass, but someone has to craft all of it. If you've some skill as a jewelcrafter, perhaps you'd be willing to help craft some of the sparkling glass gems for our performers. Sometimes you can find odd and amazing bits of glass around the grounds. Those make stunning gems when cut by someone with an eye for this craft.",starts={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},ends={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=5861},questType="standard"},
[29517] = {id=29517,name="Eyes on the Prizes",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The games are more popular than ever, and that means we're giving out prizes faster than we ever have before! We're going to need more prizes, and fast. If you've some skill in leatherworking, I can give you a kit. You'll need to buy some of the pieces from any trade goods merchant in Elwynn Forest or Mulgore, but they're inexpensive. Are you willing to help?",starts={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},ends={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},coords={x=0.494,y=0.608,source="quest_giver",zoneID=5861},questType="standard"},
[29518] = {id=29518,name="Rearm, Reuse, Recycle",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Faire-goers just love the steam tonks! And when the Darkmoon Faire closes, these grounds will be littered with tonk scrap . It'd be a shame to let all that good metal just sit in the dirt. If you help me collect some of the larger scraps, I can use them to reforge broken tonk parts. It's a lot less expensive than buying new metal every time. What do you say?",starts={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},ends={{npcID=14841,x=0.494,y=0.608,zoneID=5861}},coords={x=0.494,y=0.608,source="quest_giver",zoneID=5861},questType="standard"},
[29519] = {id=29519,name="Tan My Hide",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="The Darkmoon Faire always needs more leather for tents, boots, and just about anything you can imagine! I've trapped some creatures and staked the skins out for the next part of their treatment. You seem to have some knowledge of skinning. I'll reward you if you help me with the job of scraping some of those new skins.",starts={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},ends={{npcID=14833,x=0.55,y=0.706,zoneID=5861}},coords={x=0.55,y=0.706,source="quest_giver",zoneID=5861},questType="standard"},
[29520] = {id=29520,name="Banners, Banners Everywhere!",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Isn't it wonderful to see Darkmoon banners everywhere? It's my favorite part of setting up, but we have so many old and tattered ones that need to be replaced. If you've some skill with a needle and thread, would you mind making a banner from this kit and putting it up in some loose stones scattered around the grounds of the faire? It's missing a few pieces, but you should be able to get what you need from any trade goods vendor in Elwynn Forest or Mulgore.",starts={{npcID=10445,x=0.554,y=0.548,zoneID=5861}},ends={{npcID=10445,x=0.554,y=0.548,zoneID=5861}},coords={x=0.554,y=0.548,source="quest_giver",zoneID=5861},questType="standard"},
[29521] = {id=29521,name="The Singing Pools",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="It is crucial that we bring all of the three remaining spirits back safely. I am too old to do this myself, and for all their strengths, both Aysa and Ji are single-minded in their ideals. You possess all the qualities of a hero, and a balance that they do not. It is you that must do this. Shu, the spirit of water is somewhere in the singing pools to the east. Find Aysa there and work with her to locate him. We are all depending on you.",starts={{npcID=54786,x=0.514,y=0.462,zoneID=5736}},ends={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},coords={x=0.514,y=0.462,source="quest_giver",zoneID=5736},questType="standard"},
[29522] = {id=29522,name="Ji of the Huojin",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Another of my most talented students is awaiting you in Wu-Song Village to the northwest. He is of a different mind than Aysa, but in their differences, they bring balance to each other. Ji Firepaw will instruct you on gathering the offerings for the spirit of fire. Trust in his wisdom.",starts={{npcID=54608,x=0.576,y=0.348,zoneID=5736}},ends={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},coords={x=0.576,y=0.348,source="quest_giver",zoneID=5736},questType="standard"},
[29523] = {id=29523,name="Fanning the Flames",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Strange thing about wind, it can be hard to wrap your hands around it. Best practice for me has been finding some sort of living wind. If it can punch you, you can punch it back, and it won't slip through your grasp. Head over to the Shrine of the Summer Breeze to the south and summon just such a living wind using this wind stone . Best it, gather a Fluttering Breeze from it, and come back over this way so that we can figure out what's next.",starts={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},ends={{npcID=54568,x=0.502,y=0.214,zoneID=5736}},coords={x=0.502,y=0.214,source="quest_giver",zoneID=5736},questType="standard"},
[29524] = {id=29524,name="The Lesson of Stifled Pride",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=15543,description="Facing a living opponent is a very different thing from the stationary targets in the yard. Living opponents strike back. There is the very real fear of failure, and sometimes, even death. You must have the courage to overcome those fears. Challenge the other trainees within the temple or down the steps below, and defeat them.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[29527] = {id=29527,name="War on the Ramparts",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3562,description="Watchkeeper Gargolmar and Vazruden the Herald are in charge of defending these ramparts. If you take them out, their forces will be in complete disarray. Slay them both and bring me proof so the invasion can begin!",questType="dungeon"},
[29528] = {id=29528,name="War on the Ramparts",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3562,description="Hellfire Citadel's entire defensive network relies on the ramparts as a sort of early warning system. You need to take out Watchkeeper Gargolmar and Vazruden the Herald. Without them, taking the ramparts will be simple.",questType="dungeon"},
[29529] = {id=29529,name="Demons in the Citadel",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3562,description="One of our scouts spotted what he thought was an agent of the Burning Legion somewhere in the ramparts. If that is true, then Honor Hold may be in grave danger of a combined assault! If you find this fiend in there, kill it on sight.",questType="dungeon"},
[29530] = {id=29530,name="Demons in the Citadel",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3562,description="One of our scouts brought back unpleasant news. We've spotted a powerful agent of the Burning Legion in the ramparts! I need you to kill this demon before he has a chance to relay news of our efforts to his superiors.",questType="dungeon"},
[29531] = {id=29531,name="Kill Stuff",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=151,description="I really need you to kill some stuff for me. It's pretty important.",questType="standard"},
[29534] = {id=29534,name="Collect Things",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=151,description="The Quest Wizard demands Stuff Tails ! Go now and fetch them.",questType="standard"},
[29535] = {id=29535,name="Make Them Bleed",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3713,description="The Maker serves the purpose of creating more fel orcs by infusing them with demon blood. My superiors believe that we may be able to reverse the process, but we need samples of their blood and The Maker's infusion rod before we can know for sure.",questType="dungeon"},
[29536] = {id=29536,name="Heart of Rage",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3713,description="We know that the fel orcs are growing their forces by infusing orcs with demon blood. I need you to venture deep inside these unholy halls and find out how that's happening. We can't risk sending an army into this place until we know exactly what we're dealing with.",questType="dungeon"},
[29537] = {id=29537,name="Mind the Gap",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3713,description="In all of the Blood Furnace , there is one area where our scryers cannot reach despite their efforts. This 'gap', as they've been calling it, is fairly large, and must be where Magtheridon is being held captive.. You must find the source of the interference and dispose of it.",questType="dungeon"},
[29538] = {id=29538,name="Make Them Bleed",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3713,description="The Maker uses demon blood and a special rod to turn brown and green orcs into red ones. We'd like to see if we can take that blood, mess around with it a bit, and make it turn orcs of all colors into harmless docile lumps. You're going to bring me some samples of their blood so we can see. Don't forget to grab that rod!",questType="dungeon"},
[29539] = {id=29539,name="Heart of Rage",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3713,description="As it turns out, the eggheads back at Honor Hold can't see much into this place. Bunch of lying lazy mages, is what they are. Either way, we don't really know exactly what's going on in here. So, you're going in to find out!",questType="dungeon"},
[29540] = {id=29540,name="The Breaker",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3713,description="So they've got this big ol' demon stashed away in this place, is what they're telling me. And there's an orc that's in charge of keeping him under wraps. Killing an orc is killing an orc, am I right? Doesn't matter what he did or what he's doin', orcs are always ripe for the slaughter!",questType="dungeon"},
[29541] = {id=29541,name="Take Care of It",level=5,requiredLevel=5,faction="both",expansion=4,questType="standard"},
[29542] = {id=29542,name="Invading the Citadel",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3562,description="With the Legion to one side and the fel orcs to the other, Thrallmar is going to be overrun if we don't do something about it. Head west to the Hellfire Ramparts and speak with Stone Guard Stok'ton . He's in charge of a covert operation to start a Horde invasion on the entire citadel.",starts={{npcID=19256,x=0.58,y=0.412,zoneID=3483}},coords={x=0.58,y=0.412,source="quest_giver",zoneID=3483},questType="dungeon"},
[29543] = {id=29543,name="Invading the Citadel",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3562,description="With the Legion to one side and the fel orcs to the other, Honor Hold is going to be overrun in a matter of time if we don't do something about it. Head west to the Hellfire Ramparts and speak with Advance Scout Chadwick . He's in charge of a covert operation to start an Alliance invasion on the entire citadel.",starts={{npcID=19309,x=0.616,y=0.608,zoneID=3483}},coords={x=0.616,y=0.608,source="quest_giver",zoneID=3483},questType="dungeon"},
[29547] = {id=29547,name="The King's Command",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1519,description="Greetings, . I have been asked to assemble a team for a high priority mission. Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn. I will be waiting in the King's war room.",starts={{npcID=1750,x=0.856,y=0.328,zoneID=1519},{npcID=206111,x=0.629,y=0.717,zoneID=1519},{npcID=206294,x=0.623,y=0.301,zoneID=1519}},ends={{npcID=55789,x=0.788,y=0.398,zoneID=1519}},coords={x=0.856,y=0.328,source="quest_giver",zoneID=1519},questType="standard"},
[29548] = {id=29548,name="The Mission",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Well, you heard the King. Admiral Taylor's last transmission came from somewhere in the southern seas. We will begin our search from the air! Locating the Prince - the White Pawn - is of critical priority. The Skyfire is fueled, supplied, and ready to depart. She and her crew idle in the sky just north of the harbor. Make your last preparations, then meet Admiral Rogers on the deck. We will depart without delay.",starts={{npcID=55789,x=0.788,y=0.398,zoneID=1519}},ends={{npcID=66292,x=0.414,y=0.702,zoneID=1519},{npcID=66292,x=0.42,y=0.928,zoneID=5785}},coords={x=0.788,y=0.398,source="quest_giver",zoneID=1519},questType="standard"},
[29552] = {id=29552,name="Critical Condition",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="We may have won the first battle, but a critical task still remains. Dozens of Skyfire pilots were shot down during the initial aerial battle. Without medical aid, their condition will deteriorate over time, until they finally perish. We are their only hope for survival. Go into the orchard and revive as many pilots as you can find. We will leave no one behind.",starts={{npcID=54614,x=0.46,y=0.846,zoneID=5785},{npcID=66574,x=0.46,y=0.846,zoneID=5785}},ends={{npcID=54614,x=0.46,y=0.846,zoneID=5785}},coords={x=0.46,y=0.846,source="quest_giver",zoneID=5785},questType="standard"},
[29553] = {id=29553,name="The Missing Admiral",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Alright. According to the clues you found, that was Anduin's ship, and Admiral Taylor was the captain. And Admiral Taylor 's last entry says he was going to fight off the hozen and protect the vessel after the shipwreck. The locals say these hozen sometimes take prisoners, and I didn't see Taylor's corpse anywhere among the wreckage. So you'll probably find Taylor at the hozen encampment to the northeast. Get going, we have no time to lose!",starts={{npcID=54615,x=0.504,y=0.882,zoneID=5785}},ends={{npcID=59022,x=0.542,y=0.824,zoneID=5785}},coords={x=0.504,y=0.882,source="quest_giver",zoneID=5785},questType="standard"},
[29555] = {id=29555,name="The White Pawn",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Alright, soldier. I've got a critical mission for you. Get down to the coastline south of here - in the cove there you'll find a wrecked Alliance vessel. I need you to search it and find out if it was the ship that was carrying Anduin. Then, recover the Captain's Log and see if it has any information on where we can find him. Since the log is from a military ship, it'll be written using a cipher - take it to Nodd Codejack afterwards. He's keeping watch on the wreck from the other end of the cove.",starts={{npcID=66292,x=0.414,y=0.702,zoneID=1519},{npcID=66292,x=0.42,y=0.928,zoneID=5785}},ends={{npcID=54615,x=0.504,y=0.882,zoneID=5785}},coords={x=0.414,y=0.702,source="quest_giver",zoneID=1519},questType="standard"},
[29556] = {id=29556,name="Hozen Aren't Your Friends, Hozen Are Your Enemies",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="We've located an Alliance wreck to the south. Unfortunately, the locals have informed us that it's currently being scavenged by a group of creatures called \"hozen.\" By pillaging our wrecked ships, these creatures have already shown that they aren't friendly. We can't have them taking spoils from our ships, stealing our supplies, and worse, potentially capturing or killing any survivors. Get down there and take them out! When you're done, meet up with Nodd Codejack , our SI:7 agent in the area.",starts={{npcID=66292,x=0.414,y=0.702,zoneID=1519},{npcID=66292,x=0.42,y=0.928,zoneID=5785}},ends={{npcID=54615,x=0.504,y=0.882,zoneID=5785}},coords={x=0.414,y=0.702,source="quest_giver",zoneID=1519},questType="standard"},
[29558] = {id=29558,name="The Path of War",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I see you want to save your friend. I can help you, if you will help me. First of all, it should be obvious that the fewer the Slingtail roaming around, the easier it will be to escape. Kill the hozen guards around us, and we will be one step closer to freedom.",starts={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},ends={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},coords={x=0.542,y=0.824,source="quest_giver",zoneID=5785},questType="standard"},
[29559] = {id=29559,name="Freeing Our Brothers",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="You may be an outsider, but you and I have a common enemy in the hozen. Many members of my tribe are trapped in cages nearby. I have also seen your... Alliance... soldiers as well. I cannot leave without freeing my brethren, just as you cannot leave yours. The Slingtail hold the keys to those cages. Find the keys and free our friends.",starts={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},ends={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},coords={x=0.542,y=0.824,source="quest_giver",zoneID=5785},questType="standard"},
[29560] = {id=29560,name="Ancient Power",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Hozen skulls are prized tokens among my village. We use them to perform ceremonial rites, and the older the skull, the more potent its magic. Luckily for us, the hozen are careless, filthy beasts. They leave the skulls of their dead scattered among their huts and campfires. Collect these skulls for me, and I will reward you handsomely.",starts={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},ends={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},coords={x=0.542,y=0.824,source="quest_giver",zoneID=5785},questType="standard"},
[29562] = {id=29562,name="Jailbreak",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Without healing, your friend Taylor will die. My village is just east of here, in the middle of the large lake. I will take Taylor myself, but the fighting is most dangerous in that direction. I need you to help clear a path through the hozen, so that I may run safely into my village. Can you do this?",starts={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},ends={{npcID=56222,x=0.588,y=0.816,zoneID=5785}},coords={x=0.542,y=0.824,source="quest_giver",zoneID=5785},questType="standard"},
[29563] = {id=29563,name="Lost in Action",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,description="You have to help me! We were sent here to investigate the various parts of the reservoir, but my friends haven't come back yet, and it's been a long time. That's why I need you to discover what became of them. Naturalist Bite and Weeder Greenthumb went this way.",questType="dungeon"},
[29564] = {id=29564,name="A Brother Betrayed",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,description="My village was able to escape the naga onslaught at first. We would have all made it to Nagrand had it not been for my brother. He sold our souls for his own freedom. Now he works here as a slave driver, whipping his own brothers until their backs bleed. Make Mennu pay, .",questType="dungeon"},
[29565] = {id=29565,name="The Heart of the Matter",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,description="From what Nahuud has told me, two mighty creatures, Rokmar the Crackler and Quagmirran, were among the first enslaved by the naga when they arrived. They helped to subjugate many of the native races of Zangarmarsh. Though it pains me greatly to ask you to do so, you must put them down.",questType="dungeon"},
[29566] = {id=29566,name="Checking Up",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3717,description="These marshes are beautiful, wouldn't you agree? That is, except for the naga forces draining the water away. I sent a small expedition to the Coilfang Reservoir to investigate the naga, and they haven't returned. I'm concerned that something has happened to them. Would you travel to the Slave Pens underneath Serpent Lake and find Watcher Jhang ?",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="dungeon"},
[29567] = {id=29567,name="Stalk the Stalker",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,description="The spore giants may be attacking my people today, but the marsh walkers have taken more innocent lives than any creature I've ever seen. They are our ancient enemies. Their brood mother, the Black Stalker, resides deep within this bog. If you were to destroy her and bring me her brain as proof, I would tell tales of your bravery to my grandchildren.",questType="dungeon"},
[29568] = {id=29568,name="A Necessary Evil",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,description="Hungarfen and Quagmirran used to jointly rule over the spore giants. With Quagmirran gone, the burden rests solely on Hungarfen 's tendrils. We have no choice but to put the giant down before he can be enslaved and turned into a weapon.",questType="dungeon"},
[29570] = {id=29570,name="Rescuing the Expedition",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,description="The last members of my expedition are somewhere in here. We're going to need the knowledge they've gathered and their skills if we're to have any chance at defeating the naga. See if you can find Earthbinder Rayge and Windcaller Claw , and make sure they're ok.",questType="dungeon"},
[29571] = {id=29571,name="Defending the Wilds",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,description="The Earthen Ring often finds itself working closely with the druids of the Cenarion Circle. Now is one such time. Travel north to the Underbog and speak with Watcher Jhang . She is in charge of an expedition in the Coilfang Reservoir to stop the naga there and save Zangarmarsh.",starts={{npcID=18074,x=0.604,y=0.224,zoneID=3518}},coords={x=0.604,y=0.224,source="quest_giver",zoneID=3518},questType="dungeon"},
[29573] = {id=29573,name="Safety is Job One",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3792,description="It's nearly safe for our men to come in here and take what's rightfully ours. The real danger now is Shaffar's personal army that he has crawling all over this place. I need you to take care of his forces for me while I regain my strength.",questType="dungeon"},
[29574] = {id=29574,name="Intriguing Specimens",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3792,description="There is a creature not far inside these halls called Pandemonius who is able to twist void energies to sustain and empower itself. A bit further in lies Tavarok, a being that takes those same void energies and converts them into a crystalline structure stronger than any I've ever seen! I absolutely must obtain samples for further study.",questType="dungeon"},
[29575] = {id=29575,name="Undercutting the Competition",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3792,description="With his ward in place and his forces ready, Nexus-Prince Shaffar has been able to pillage this place for all it's worth without so much as an ounce of trouble. Unsurprisingly, Nexus-Prince Haramad isn't pleased by this, and has placed a hefty bounty on Shaffar's head.",questType="dungeon"},
[29576] = {id=29576,name="An Air of Worry",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="My sight has long since faded, but when the wind is right I can still smell the blossoms of Nectarbreeze Orchard as if they were in my own palm. Today, though, their fragrance is muddled with smoke. Please, if you are able, check in on the orchard and see that things are okay. Perhaps my old nose is playing tricks on me. You'll find the orchard to the southwest, beyond the statue of the Jade Serpent.",starts={{npcID=59383,x=0.482,y=0.46,zoneID=5785}},ends={{npcID=54697,x=0.434,y=0.758,zoneID=5785}},coords={x=0.482,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29577] = {id=29577,name="Ashyo's Vision",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Have a look at that! This must be the water supply for the whole valley! Think about it, : the pandaren use this water to grow vegetables the size of a house. Where could it come from? What is so special about it? The elders among my people know a technique for speaking with the water and divining the future. Perhaps this same technique can provide insight into the water's source... It's worth a shot at least!",starts={{npcID=56113,x=0.612,y=0.342,zoneID=5805}},ends={{npcID=56802,x=0.598,y=0.278,zoneID=5805}},coords={x=0.612,y=0.342,source="quest_giver",zoneID=5805},questType="standard"},
[29578] = {id=29578,name="Defiance",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The damn mogu hit us out of nowhere! Anyone they don't kill on sight is being dragged away into the woods. This is the only safehouse, and its all I can do to hold the door. What do you say, friend? Are you willing to stand up and fight for the weak?",starts={{npcID=54697,x=0.434,y=0.758,zoneID=5785}},ends={{npcID=54697,x=0.434,y=0.758,zoneID=5785}},coords={x=0.434,y=0.758,source="quest_giver",zoneID=5785},questType="standard"},
[29579] = {id=29579,name="Rally the Survivors",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The people of this village are simple farmers - not fighters like you and I. Still, they are stubbornly defending their homes as best they can. Search the village for anyone still on their feet and tell them to rally here at Hanae's place.",starts={{npcID=54697,x=0.434,y=0.758,zoneID=5785}},ends={{npcID=54697,x=0.434,y=0.758,zoneID=5785}},coords={x=0.434,y=0.758,source="quest_giver",zoneID=5785},questType="standard"},
[29580] = {id=29580,name="Orchard-Supplied Hardware",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="They may not be weaponmasters, but many of these farmers can wield a simple hoe or a rake as an extension of their own will. That mastery coupled with the right motivation could muster a force capable of standing against the mogu. If you can bring back some tools from the orchard, I'll distribute them to anyone willing to fight.",starts={{npcID=54854,x=0.432,y=0.76,zoneID=5785}},ends={{npcID=54854,x=0.432,y=0.76,zoneID=5785}},coords={x=0.432,y=0.76,source="quest_giver",zoneID=5785},questType="standard"},
[29581] = {id=29581,name="The Golden Dream",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Ashyo must have experienced what we call the golden dream. Many of us working here have seen it, too - often after a long day of toiling in the pools. It is said this vision--and the feeling of elation it brings--is a reward to the mind for working the body. There IS an easier way, though we rarely resort to it anymore: a tea can be brewed using lotus root and dreamleaf, which grows around the shrine on the upper tier. Bring the dreamleaf to Yan back in town and he can brew the tea for you.",starts={{npcID=56802,x=0.598,y=0.278,zoneID=5805}},ends={{npcID=56773,x=0.606,y=0.338,zoneID=5805}},coords={x=0.598,y=0.278,source="quest_giver",zoneID=5805},questType="standard"},
[29582] = {id=29582,name="Grek's Crazy Night",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=3792,description="Grek had bad night last night. Shiny mummy man came into Grek 's house and told Grek that he had to go to Mana Tombs in Auchindoun. But Grek still trying to read wanted poster! Grek 's face lights up.> Grek knows! You go find shiny mummy man and tell him Grek sent you. It perfect plan!",starts={{npcID=19606,x=0.498,y=0.452,zoneID=3519}},coords={x=0.498,y=0.452,source="quest_giver",zoneID=3519},questType="dungeon"},
[29583] = {id=29583,name="Eckert the Mad",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=3792,description="I'm a skilled engineer, a brilliant inventor, the heart of any party, and the best dancer Azeroth has ever seen. Do they call me those things? No. But you have one run-in with an ethereal and all of the sudden everyone and their mother calls you \"the mad\". I saw one right here just yesterday, I swear it! He said if I followed him to the Mana Tombs in Auchindoun there would be vast treasure and ancient knowledge awaiting me!",starts={{npcID=21400,x=0.576,y=0.534,zoneID=3519}},coords={x=0.576,y=0.534,source="quest_giver",zoneID=3519},questType="dungeon"},
[29585] = {id=29585,name="Spitfire",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="We've tended these orchards and made cider from their nectar for generations. In that time, we've learned a special trick for putting out fires in a pinch. The cider itself - when mixed with crushed gingerleaf and saliva - quickly becomes sticky and viscous. Perfect for smothering flames. Please, while you're out there, try to get the flames under control. I've already mixed in the gingerleaf, just swig and spit.",starts={{npcID=54854,x=0.432,y=0.76,zoneID=5785}},ends={{npcID=54854,x=0.432,y=0.76,zoneID=5785}},coords={x=0.432,y=0.76,source="quest_giver",zoneID=5785},questType="standard"},
[29586] = {id=29586,name="The Splintered Path",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="First... before the war-cries... we heard the trees. Groaning, creaking, and finally crashing down as the mogu cut their way through the woods. They were making the return trip easier... They're dragging our friends back down that path, to the ruins west of the village! Those ruins have been empty for years - our children play there. Why would the mogu come back to them now?",starts={{npcID=55209,x=0.432,y=0.758,zoneID=5785}},ends={{npcID=55009,x=0.41,y=0.74,zoneID=5785}},coords={x=0.432,y=0.758,source="quest_giver",zoneID=5785},questType="standard"},
[29587] = {id=29587,name="Unbound",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Can you see them, $p? Farmers from the orchard, tied up and under inspection. Being hauled off in chains. The mogu value strength above all else. Anyone deemed fit for work will be sent to toil under their cruel whips. As for the others, well... Let's not waste any more time.",starts={{npcID=55009,x=0.41,y=0.74,zoneID=5785}},ends={{npcID=55009,x=0.41,y=0.74,zoneID=5785}},coords={x=0.41,y=0.74,source="quest_giver",zoneID=5785},questType="standard"},
[29590] = {id=29590,name="The Dead Watcher",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3790,description="A terrifying otherworldly being haunts both the spirit and physical worlds. We call it Shirrak. It can only be harmed in your realm. Please help rid us of this nightmare.",questType="dungeon"},
[29591] = {id=29591,name="Raging Spirits",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3790,description="The Auchenai have turned their backs on everything we used to stand for. They've taken to raising the dead as unholy minions! This cannot stand. Put the spirits back to rest, and massacre those responsible for raising them into undeath.",questType="dungeon"},
[29593] = {id=29593,name="Hitting Them Where It Hurts",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3562,description="The fel orcs have stockpiled many of their supplies here. Stealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, ?",questType="dungeon"},
[29594] = {id=29594,name="Hitting Them Where It Hurts",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=3562,description="The fel orcs have stockpiled many of their supplies here. Stealing them would be a severe blow to their war effort and a great boon to ours. Are you up to the task, ?",questType="dungeon"},
[29595] = {id=29595,name="Everything Will Be Alright",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3790,description="You've had quite an adventure, . And before you've even set foot inside of the Auchenai Crypts . I am one of the fortunate spirits. I was neither bound to Levixus nor a part of Exarch Maladaar's vile experiments in necromancy. While you have destroyed Levixus, Maladaar lives on, continuing to torment the spirits inside the crypts. What I ask is simple. Enter the Auchenai Crypts and speak with the Draenei Spirit there. You must destroy Exarch Maladaar.",starts={{npcID=19698,x=0.35,y=0.652,zoneID=3519}},coords={x=0.35,y=0.652,source="quest_giver",zoneID=3519},questType="dungeon"},
[29596] = {id=29596,name="The End of the Exarch",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3790,description="Exarch Maladaar performs his unholy work in the deepest part of the crypts. He poses a threat to both of our worlds if he is not stopped. You must slay him for the benefit of us all, dead and alive.",questType="dungeon"},
[29600] = {id=29600,name="Snap Judgment",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="These pools are very special: they nurture life like nothing else in Pandaria. Unfortunately this means they draw all kinds of attention from local fauna. Recently, dragon turtles have discovered that toadspawn pools are common on the tier just above us. They're running wild up there, trampling the lotuses and snapping at my workers. They aren't much of a threat on their own, but in groups they can be pretty nasty. Please, if you can spare your strength, help clear them out.",starts={{npcID=56802,x=0.598,y=0.278,zoneID=5805}},ends={{npcID=56802,x=0.598,y=0.278,zoneID=5805}},coords={x=0.598,y=0.278,source="quest_giver",zoneID=5805},questType="standard"},
[29601] = {id=29601,name="The Darkmoon Field Guide",level=1,requiredLevel=1,faction="none",expansion=4,description="Do you have a copy of the Darkmoon Field Guide, friend? It's a most useful book to carry with you. It can help you find and identify valuable artifacts throughout your travels in Azeroth. Its detailed descriptions make it easy to decide if you've found your five hundredth brass button or that rare treasure the Darkmoon Faire's collectors crave.",questType="standard"},
[29605] = {id=29605,name="Brother Against Brother",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3791,description="The Sethekk departed Skettis when Auchindoun exploded. My brother, Syth, was one of their leaders and told us we had to go into the ruins and face our god. In time, Syth had me cast out of the Halls for doubting them, but he refused to let me take our sister Lakka . Will you help me rescue her?",questType="dungeon"},
[29606] = {id=29606,name="Terokk's Legacy",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3791,description="Terokk, hero of the Arakkoa, mysteriously vanished one day, leaving only his mask and spear behind. Darkweaver Syth still holds his mask and Talon King Ikiss guards his spear. It would mean a great deal to my people if these items were returned to us.",questType="dungeon"},
[29607] = {id=29607,name="Eyes of Desire",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=3791,description="I have a buyer who is interested in the eyes of the Cobalt Serpents that have taken up residence here. If you were to bring me some of these rare gems, I would cut you a portion of the profits. Do we have a deal?",questType="dungeon"},
[29608] = {id=29608,name="Allies in Dalaran",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=6611,description="Welcome to Northrend, . I have been asked to arrange travel for you to Dalaran so that you can meet with our allies there. Ride the gryphon to Dalaran and once you land, make your way to our inn there, A Hero's Welcome. Find Isirami Fairwind and speak with her immediately. She can help you bind your hearthstone to the city so you can use the Silver Enclave's portal to travel back to Stormwind quickly.",starts={{npcID=23736,x=0.598,y=0.632,zoneID=495},{npcID=26879,x=0.588,y=0.682,zoneID=3537}},coords={x=0.598,y=0.632,source="quest_giver",zoneID=495},questType="standard"},
[29609] = {id=29609,name="Friends in Dalaran",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=6611,description="Welcome to Northrend. I have been asked to arrange travel for you to Dalaran so that you can meet our friends in the city. Speak with me and accept a ride to Dalaran . Once you land, make your way to The Filthy Animal. Make contact with Uda the Beast immediately. She can help you bind your hearthstone to the city so you can use the portal in Sunreaver's Sanctuary to travel back to Orgrimmar quickly.",starts={{npcID=25288,x=0.404,y=0.514,zoneID=3537},{npcID=27344,x=0.79,y=0.296,zoneID=495}},ends={{npcID=31557,x=0.786,y=0.846,zoneID=6611},{npcID=31557,x=0.646,y=0.324,zoneID=6611}},coords={x=0.404,y=0.514,source="quest_giver",zoneID=3537},questType="standard"},
[29611] = {id=29611,name="The Art of War",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,description="Lok'tar ogar, . I am Nazgrim. You are hereby ordered to present yourself at Grommash Hold immediately. All in service to the Horde are to swear an oath of allegiance to their new Warchief. Do not keep him waiting, .",starts={{npcID=54870,x=0.486,y=0.708,zoneID=1637},{npcID=206109,x=0.497,y=0.766,zoneID=1637},{npcID=206116,x=0.664,y=0.492,zoneID=1637}},ends={{npcID=54870,x=0.486,y=0.708,zoneID=1637}},coords={x=0.486,y=0.708,source="quest_giver",zoneID=1637},questType="standard"},
[29612] = {id=29612,name="The Art of War",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,description="Lok'tar Ogar, old friend. It has been too long since last we spoke. It is good to see that you emerged safely from the depths of Vashj'ir. I am stationed here in Grommash Hold. All in service to the Horde are to swear allegiance to their new Warchief. You would do well not to keep him waiting, .",starts={{npcID=54870,x=0.486,y=0.708,zoneID=1637}},ends={{npcID=54870,x=0.486,y=0.708,zoneID=1637}},coords={x=0.486,y=0.708,source="quest_giver",zoneID=1637},questType="standard"},
[29613] = {id=29613,name="A Proper Fate",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3715,description="Warlord Kalithresh is in charge of the entire Steamvault operation. I need you to kill him, . The naga have left us with no option but violence. Show him no mercy.",questType="dungeon"},
[29614] = {id=29614,name="Containment is Key",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3715,description="The naga are working with leper gnomes to spread a horrific disease across Zangarmarsh. It's already spread throughout the Steamvault . Clear out anything that's been contaminated and bring me the central gear from Mekgineer Steamrigger, quickly!",questType="dungeon"},
[29615] = {id=29615,name="Windcaller Claw and the Water Thief",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3715,description="The Steamvault is the heart of the naga's efforts to pump the water out of Zangarmarsh, and Hydromancer Thespia personally oversees those efforts. Taking her out would seriously hinder their operation.",questType="dungeon"},
[29616] = {id=29616,name="Storming the Steamvault",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3715,description="We have not as of yet been able to stop the naga in the Steamvault , where most of their pumping infrastructure is located. Thankfully, the expedition I sent there is hard at work trying to change that fact. Will you travel to the Steamvault and offer Watcher Jhang and her crew your aid?",starts={{npcID=17841,x=0.784,y=0.62,zoneID=3521}},coords={x=0.784,y=0.62,source="quest_giver",zoneID=3521},questType="dungeon"},
[29617] = {id=29617,name="Tian Monastery",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="People come from all over Pandaria to train at the Tian Monastery, just to the north of here. Probably because they never turn anybody down. They'll accept jinyu, hozen... or even a foreign like you! My childhood friend, Lin, just joined the monastery's order a few weeks ago. If you're interested in learning how our monks train, maybe you should go talk with her!",starts={{npcID=54998,x=0.496,y=0.458,zoneID=5785}},ends={{npcID=54913,x=0.45,y=0.25,zoneID=5785}},coords={x=0.496,y=0.458,source="quest_giver",zoneID=5785},questType="standard"},
[29618] = {id=29618,name="The High Elder",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="How strange, to have such a foreign-looking visiting our temple. Are you here to study? You... you look very strong. You wouldn't have any trouble getting accepted into the monastery. You should talk to the High Elder, up on the balcony above.",starts={{npcID=54913,x=0.45,y=0.25,zoneID=5785}},ends={{npcID=54914,x=0.428,y=0.232,zoneID=5785}},coords={x=0.45,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[29619] = {id=29619,name="A Courteous Guest",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I heard, I heard! The High Elder wants you to train with us! There's going to be a banquet for us, the trainees... and you should probably bring a gift, as a sign of courtesy. The oranges in the grove south of the temple are extra-sweet right now. Bring some back, for the banquet.",starts={{npcID=54913,x=0.45,y=0.25,zoneID=5785}},ends={{npcID=54913,x=0.45,y=0.25,zoneID=5785}},coords={x=0.45,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[29620] = {id=29620,name="The Great Banquet",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The banquet should be starting any time now. Go find the High Elder and pay your respects. I'll be right behind you.",starts={{npcID=54913,x=0.45,y=0.25,zoneID=5785}},ends={{npcID=54914,x=0.428,y=0.232,zoneID=5785}},coords={x=0.45,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[29622] = {id=29622,name="Your Training Starts Now",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Xiao does not look up from his bowl.> Hey, new ! Glad to see you survived the banquet! Trial One: Complete! Xiao eats noisily.> You'd better speak up with Instructor Xann . He'll be expecting you for your daily exercises.",starts={{npcID=54926,x=0.43,y=0.236,zoneID=5785}},ends={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},coords={x=0.43,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29623] = {id=29623,name="Perfection",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Perfection can be achieved through repetition. Every single student in the training arena below will eventually perfect his or her form... assuming they don't give up first. This is a fact. I encourage you to join them, . As an honorary guest of the monastery, you are not required to perform the requisite 10,000 daily strikes. Simply follow the leader's example for a few minutes.",starts={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},ends={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},coords={x=0.416,y=0.284,source="quest_giver",zoneID=5785},questType="standard"},
[29624] = {id=29624,name="Attention",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Your next test also involves concentration and attention. I want you to practice your abilities on the training bags in the pit below. The bags are hung in groups of two. When I call out \"Left\", attack the bag on the left. When I call out \"Right\", attack the bag on the right. If you fail to follow my simple directions, this task will become much harder. Now beat on those practice bags until they burst, .",starts={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},ends={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},coords={x=0.416,y=0.284,source="quest_giver",zoneID=5785},questType="standard"},
[29626] = {id=29626,name="Groundskeeper Wu",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="We don't have many rules here, but we do have one particular rule that is worth remembering. If you want to eat... Xiao 's stomach grumbles audibly.> ...you have to work. Groundskeeper Wu can give you your chores for the day. He's in the market, to the west.",starts={{npcID=54926,x=0.43,y=0.236,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.43,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29627] = {id=29627,name="A Proper Weapon",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="First things first, though. A proper trainee needs a proper weapon. And a scrupulous trainee builds his own... or at least gathers the materials. The switches which grow nearby should suffice for any respectable weapon. You'll also need to shop for black walnut extract to treat the wood. While you're there, get some ale, for... ...well, you know what ale is for.",starts={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.416,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29628] = {id=29628,name="A Strong Back",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Some of our trainees have... larger-than normal appetites. We have occasionally had difficulty supplying enough food for all of them. In times like these, we have to ask for help. A kindly older woman, who lives in a small house to the northwest, has agreed to make some stew for our trainees. All you need to do is go and get it.",starts={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.416,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29629] = {id=29629,name="A Steady Hand",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The black walnut extract you purchased from Miss Whiteblossom is but one of many extracts we keep in stock for various applications. Blushleaf extract can be gathered from the flowers in the Waxwood Forest to the west. Several units can be extracted from one flower, but only those with calm nerves and steady hands can remove all of the extract from one flower.",starts={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.416,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29630] = {id=29630,name="And a Heavy Fist",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The greenwood sprites in the Waxwood Forest to the west pose no direct threat to us, this is true. However, their numbers have increased as of late, as have their wily antics. Part of our duty as wardens of this forest is to maintain the balance. Your duty is to do so by returning these sprites to the earth.",starts={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},ends={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},coords={x=0.416,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29631] = {id=29631,name="Burning Bright",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Might I ask a favor of you, trainee ? Before I came to the monastery, I was a stranger to battle. During my time as a trainee, I performed adequately, but I was never placed in any real danger. Now, as a graduate and a wage-earning guard, I am expected to protect this perimeter at all costs. I can handle greenwood sprites, but the tigers in the western Waxwood are something different altogether. Would you mind taking care of them for me?",starts={{npcID=55094,x=0.38,y=0.238,zoneID=5785}},ends={{npcID=55094,x=0.38,y=0.238,zoneID=5785}},coords={x=0.38,y=0.238,source="quest_giver",zoneID=5785},questType="standard"},
[29632] = {id=29632,name="Becoming Battle-Ready",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Alright, . I'd like to see what you're really made of. You'll find my pupils all over the monastery. Challenge them to fights. Push them to their limits. They have been instructed to do the same to you. Win or lose, you both will come out of the fight stronger.",starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[29633] = {id=29633,name="Zhi-Zhi, the Dextrous",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Upon the hills to my right, you will find a hozen named Zhi-Zhi . He, too, won enough sparring matches to move up the ranks. I think he will provide you with more of a challenge. Challenge him, and try to defeat him.",starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[29634] = {id=29634,name="Husshun, the Wizened",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The jinyu are long-standing allies of the pandaren, and we welcome any of their kind into our monastery. Husshun , one of their elder shaman, is one of our newest trainees. His skills as a monk are mediocre at best, but he is still a fierce combatant. He should provide you with the challenge that you deserve.",starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[29635] = {id=29635,name="Xiao, the Eater",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You may have already met my best student, Xiao , at the banquet tables. I personally would have graduated him several times over, but Instructor Xann insists that he needs more discipline. If you ask me, discipline means very little if you win every fight you enter. I'm curious to see if Xiao can keep his streak alive against you.",starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[29636] = {id=29636,name="A Test of Endurance",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I have taught you everything that I can, . It is time you spoke with Instructor Myang . The fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait. Farewell, , and best of luck on the remainder of your training.",starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54918,x=0.39,y=0.24,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[29637] = {id=29637,name="The Rumpus",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Master Stone Fist has trained you in the art of one-on-one combat. Now you learn the art of one-on-many. How does fifty sound? Lower yourself into the Ring of Inner Focus below, then, when you're ready, set off this firework. My assistants will come at you, several at a time. All you need to do is survive.",starts={{npcID=54918,x=0.39,y=0.24,zoneID=5785}},ends={{npcID=54918,x=0.39,y=0.24,zoneID=5785}},coords={x=0.39,y=0.24,source="quest_giver",zoneID=5785},questType="standard"},
[29639] = {id=29639,name="Flying Colors",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You have passed every test we prepared for you, . It is now time for you to move on to bigger and better things. ...but not before another banquet. The High Elder will be waiting for you at the banquet grounds to celebrate your graduation from our monastery.",starts={{npcID=54917,x=0.416,y=0.284,zoneID=5785}},ends={{npcID=54914,x=0.428,y=0.232,zoneID=5785}},coords={x=0.416,y=0.284,source="quest_giver",zoneID=5785},questType="standard"},
[29640] = {id=29640,name="Find Spy To'gun",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="The Shadow Council has already killed most of our spies, but To'gun was foolish enough to escape only to go back in! You must find him. He may be reckless, but we need to find out what he knows.",questType="dungeon"},
[29641] = {id=29641,name="The Soul Devices",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="They've been torturing me, trying to get me to tell them everything that I know. They fed the others to Hellmaw, and I was to be next. But I told them nothing! They're using special devices to make their summoning more powerful. You must steal these devices!",questType="dungeon"},
[29642] = {id=29642,name="Trouble at Auchindoun",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="I have spies within Auchindoun and they have been sending me disturbing reports. That place has been nothing but trouble ever since it exploded a couple of years ago. Something in there has gone horribly wrong - again - and the Shadow Council is now on a war footing. Though the reports were lacking on details, their preparations appear to be directed inward. You must make your way to the Shadow Labyrinth . My field commander, Mahfuun, will fill you in on what needs to be done.",starts={{npcID=18893,x=0.504,y=0.452,zoneID=3703}},coords={x=0.504,y=0.452,source="quest_giver",zoneID=3703},questType="dungeon"},
[29643] = {id=29643,name="The Codex of Blood",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="Two years ago the Shadow Council summoned forth a being that shattered Auchindoun in its wake. Read the Codex of Blood to find out what happened. Be warned, Grandmaster Vorpil guards it with his life.",questType="dungeon"},
[29644] = {id=29644,name="Into the Heart of the Labyrinth",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="The Shadow Council has lost control of the cosmic being that they summoned here almost two years ago. Known only as Murmur , it threatens to overrun the Shadow Council and break free into the outside world!",starts={{npcID=182947,zoneID=3789},{npcID=182947,zoneID=3789}},ends={{npcID=54890,zoneID=3789}},questType="dungeon"},
[29645] = {id=29645,name="Ambassador Hellmaw",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3789,description="When the Cabal found our spies, they fed them to Ambassador Hellmaw one by one. Our men deserve justice. Slay the ritualists binding him, then dispose of Hellmaw. It is a most deserving fate.",questType="dungeon"},
[29646] = {id=29646,name="Flying Colors",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Well, I've done all that I can with you. Sounds like the others have, too. High Elder Cloudfall will be waiting at the banquet grounds, ready to celebrate your departure. Not that we're happy you're leaving... he just enjoys celebrations.",starts={{npcID=54915,x=0.416,y=0.236,zoneID=5785}},ends={{npcID=54914,x=0.428,y=0.232,zoneID=5785}},coords={x=0.416,y=0.236,source="quest_giver",zoneID=5785},questType="standard"},
[29647] = {id=29647,name="Flying Colors",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The Rumpus was your final test. You have mastered the disciplines taught at this monastery. Just as your training began with a banquet, so shall it end. High Elder Cloudfall should be waiting at the banquet grounds. I'll be right behind you.",starts={{npcID=54918,x=0.39,y=0.24,zoneID=5785}},ends={{npcID=54914,x=0.428,y=0.232,zoneID=5785}},coords={x=0.39,y=0.24,source="quest_giver",zoneID=5785},questType="standard"},
[29649] = {id=29649,name="How to Save a Life",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=3714,description="Gunny is dying from a powerful curse, . Grand Warlock Nethekurse augments his power with a pair of mystical braziers. If you bring me an ember from that brazier, perhaps it can counteract the dark magic?",questType="dungeon"},
[29650] = {id=29650,name="Fel Ember",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=3714,description="Caza'rez is dying a coward's death. Grand Warlock Netherkurse placed a terrible curse upon him. Perhaps if you were to bring me one of the embers from his braziers, we could use it to counteract the magic before it's too late?",questType="dungeon"},
[29651] = {id=29651,name="Honor the Dying",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=3714,description="Their elite warriors are ruthless... so... powerful. Caza'rez spits up blood.> You have to kill them... or we will never defeat Kargath...",questType="dungeon"},
[29652] = {id=29652,name="One Last Favor",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=3714,description="Ol' Gunny doesn't have much longer... Do me one last favor, and kill the biggest, meanest fel orcs ye can find. For old times' sake, aye?",questType="dungeon"},
[29653] = {id=29653,name="The Will of the Warchief",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=3714,description="Kargath was once one of the Horde's greatest heroes. He now wears the false mantle of Warchief. Bring me his namesake weapon so that we can remember the champion he once was, rather than the monster he's become.",questType="dungeon"},
[29654] = {id=29654,name="Turning the Tide",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=3714,description="There is only one true way to end the fel orc threat to Honor Hold and the Alliance. Their Warchief must be slain. Bring me his namesake weapon, so that we can always remember his death.",questType="dungeon"},
[29655] = {id=29655,name="A Very Special Cloth",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=3714,description="Warbringer O'mrogg has killed more brave soldiers than any enemy I've ever encountered. He is ruthless, cunning, and extremely powerful. Take him down and bring me his warcloth so that we may fashion it into a banner and show them the fury of the Horde!",questType="dungeon"},
[29656] = {id=29656,name="O'mrogg's Warcloth",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=3714,description="Stormwind wants to see proof of our successes in the war effort. Rather than showing him body bags, I thought we'd present him the warcloth of O'mrogg, Kargath's fiercest warrior. Think you can handle him?",questType="dungeon"},
[29657] = {id=29657,name="With Great Power, Comes Great Responsibility",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3849,description="The Mechanar employs my race's technology to create manacells, objects which provide great amounts of power. I need you to eliminate Mechano-Lord Capacitus so that Kael'thas' forces cannot harvest that power.",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="dungeon"},
[29658] = {id=29658,name="The Calculator",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3849,description="One more task yet remains. Pathaleon the Calculator oversees many of his master's operations. He is personally responsible for much of the recent torment that has plagued this world. I ask that you eliminate him.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[29659] = {id=29659,name="Lost Treasure",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3703,description="I sense that one of my kind's artifacts has been taken and stashed away in the Cache of the Legion. We cannot give them time to discover its power. If you would kill the Gatewatchers and retrieve it for me, I would be most grateful.",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="dungeon"},
[29660] = {id=29660,name="Saving the Botanica",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3847,description="Kael'thas' forces in the Botanica were unsuccessful in handling the numerous creatures contained within. We must take action to right their wrongs. The first step is to eliminate their forces so that they cannot cause further problems.",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="dungeon"},
[29661] = {id=29661,name="The Lesson of Dry Fur",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Through meditation, I intend to find a route to locating Shu. In the meantime, you would benefit from practice and discipline. Your first task is the task of all trainees entering the pools: cross the balance poles to the west and ring the bell without falling into the pool. Should you fall, the pool's curse will make it difficult to get on a pole again, so you will need to return to the edge of the pool to start over. Oh, and beware the cranes.",starts={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},ends={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},coords={x=0.656,y=0.426,source="quest_giver",zoneID=5736},questType="standard"},
[29662] = {id=29662,name="Stronger Than Reeds",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Gather me reeds from the nearby pools. Do not question why. Do, and then observe the results.",starts={{npcID=55021,x=0.634,y=0.42,zoneID=5736}},ends={{npcID=55021,x=0.634,y=0.42,zoneID=5736}},coords={x=0.634,y=0.42,source="quest_giver",zoneID=5736},questType="standard"},
[29663] = {id=29663,name="The Lesson of the Balanced Rock",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="I require peace to perform my meditation. Practice your arts while I meditate on Shu's location. Other monks practice balance and combat upon the balance poles in the surrounding pools. Engage them and defeat them.",starts={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},ends={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},coords={x=0.656,y=0.426,source="quest_giver",zoneID=5736},questType="standard"},
[29664] = {id=29664,name="The Challenger's Fires",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="You're strong of mind and strong of will, but you lack the skills to face me in combat. You must fight with your body, but in truth, it is your character that is being tested. Let us even the playing field. Take this torch, light it in the brazier next to me, and then use it to light the three unlit braziers around the pool.",starts={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},ends={{npcID=54135,x=0.388,y=0.254,zoneID=5736}},coords={x=0.388,y=0.254,source="quest_giver",zoneID=5736},questType="standard"},
[29665] = {id=29665,name="From Bad to Worse",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="After their ship crashed, evil creatures swept up from the sea to pick through the wreckage. Our aid may seem but a drop in the pond at the thought of the misfortune they've faced today. Defeat their tormentors. These people desperately need our help.",starts={{npcID=55940,x=0.422,y=0.864,zoneID=5736}},ends={{npcID=55940,x=0.422,y=0.864,zoneID=5736}},coords={x=0.422,y=0.864,source="quest_giver",zoneID=5736},questType="standard"},
[29666] = {id=29666,name="The Sting of Learning",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="There are dangers in the pools. The latest and most vicious are the water pincers . A time has come for their numbers to be diminished, and I am no longer up to the task. If you could clear out some of the water pincers , I would be very appreciative. Beware their numbers... sometimes it's best to lure them from the pool-side rather than wading all the way in.",starts={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},ends={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},coords={x=0.706,y=0.386,source="quest_giver",zoneID=5736},questType="standard"},
[29667] = {id=29667,name="Culling the Herd",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3847,description="It seems that Kael'thas' forces have twisted the Botanica 's specimens beyond saving. I do not want to see them unleashed upon Outland as so many others have. There is one, Laj, who I would like to examine. He is different somehow. Perhaps we can learn from him.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[29669] = {id=29669,name="A Most Somber Task",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=3847,description="I must now ask you to complete a most somber task. Warp Splinter used to act as guardian to all of the Botanica . He is now impure, and must be taken down.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[29670] = {id=29670,name="Maul Gormal",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Thanks to you, there's a small militia of farmers hiding nearby. Hanae said something about giving them \"liquid courage\" which, I'm pretty sure, means they're sauced and ANGRY. The mogu think they can walk all over us - we'll give them a fight that will open their eyes. Follow the trail through the ruins and down to the beach. Find their leader. When you engage him, we'll be there to back you up.",starts={{npcID=55009,x=0.41,y=0.74,zoneID=5785}},ends={{npcID=55009,x=0.41,y=0.74,zoneID=5785}},coords={x=0.41,y=0.74,source="quest_giver",zoneID=5785},questType="standard"},
[29674] = {id=29674,name="Unbound Darkness",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=3848,description="We imprisoned the most dangerous beings we came across in our travels. Zereketh is a powerful void lord. If he escapes into Netherstorm, he will feed off of the abundant void energy.",ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},questType="dungeon"},
[29675] = {id=29675,name="Hey There Dalliah",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=3848,description="Two powerful agents of the Burning Legion, Wrath-Scryer Soccothrates and Dalliah the Doomsayer , have begun rallying the demons on board together into a small army. You cannot let their forces grow any larger, or the Arcatraz may soon become yet another Legion stronghold.",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[29676] = {id=29676,name="Finding an Old Friend",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="It seems Shu, the spirit of water, had a play companion when he came to the pools throughout the years. An old pandaren we know as Old Man Liang . Liang moved away from the main town and stopped practicing in the pools some time ago. I am told he lives in a small house northeast of here, up the hill. Liang may know what has driven Shu away, and where the spirit might be found. Go to Liang. Ask of Shu.",starts={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},ends={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},coords={x=0.656,y=0.426,source="quest_giver",zoneID=5736},questType="standard"},
[29677] = {id=29677,name="The Sun Pearl",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Shu, the spirit of water, is eternally young, as are all the spirits of Shen-zin Su. I have been friends with Shu all of my life, but I no longer have it within me to play with him. I am old, and lack the energy. For all his complexities, Shu is simple to please: he desires friendship. When I returned to play with Shu each season, I would always bring a Sun Pearl as a gift, and then we would play together. You can find a Sun Pearl in the pools to the southeast. Perhaps you can be his new friend.",starts={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},ends={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},coords={x=0.706,y=0.386,source="quest_giver",zoneID=5736},questType="standard"},
[29678] = {id=29678,name="Shu, the Spirit of Water",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Shu, the spirit of water, is sulking in the deep pool to the north. Cross the rocks and then drop the sun pearl in the center of the pool. He will know what this means.",starts={{npcID=55020,x=0.706,y=0.386,zoneID=5736}},coords={x=0.706,y=0.386,source="quest_giver",zoneID=5736},questType="standard"},
[29679] = {id=29679,name="A New Friend",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="He wants you to play with him. Go for it!",starts={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},ends={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},coords={x=0.656,y=0.426,source="quest_giver",zoneID=5736},questType="standard"},
[29680] = {id=29680,name="The Source of Our Livelihood",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="We have done as Master Shang asked of us. I will return to the temple to inform the master of our progress. You should continue south on the road to the farmlands to seek out Wugou, the spirit of earth. Ji awaits you at the Dai-Lo Farmstead, and he'll surely need your help. I must warn you, Ji can be reckless in his directness. Remember well the things I have taught you: discipline and patience.",starts={{npcID=54975,x=0.656,y=0.426,zoneID=5736}},ends={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},coords={x=0.656,y=0.426,source="quest_giver",zoneID=5736},questType="standard"},
[29681] = {id=29681,name="Maximum Security Breakout",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=3848,description="Harbinger Skyriss is the heart of the problem in the Arcatraz . He corrupted Warden Mellichar and made him release many of the prisoners. It is only a matter of time before the Harbinger himself is let loose. , you cannot let a servant of the Old Gods live!",starts={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},ends={{npcID=18481,x=0.542,y=0.444,zoneID=3703}},coords={x=0.542,y=0.444,source="quest_giver",zoneID=3703},questType="dungeon"},
[29682] = {id=29682,name="Magisters' Terrace",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=4131,description="We recently sent in an expeditionary force to the Magisters' Terrace to stop the Legion forces there. However, we haven't heard from them since, and I fear the worst. Will you go there and try to find Exarch Larethor ? He's in charge of the expedition.",starts={{npcID=24967,x=0.474,y=0.306,zoneID=4080}},coords={x=0.474,y=0.306,source="quest_giver",zoneID=4080},questType="dungeon"},
[29684] = {id=29684,name="Severed Communications",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=4131,description="We've had a contact embedded in Magisters' Terrace gathering intelligence for us for some time now, but we've lost contact with him. The information he was collecting is vital to our mission.",questType="dungeon"},
[29685] = {id=29685,name="Hard to Kill",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=4131,description="As you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends. Kael'thas has risen from the ashes of defeat and once more leads them in their efforts. He must be stopped.",questType="dungeon"},
[29686] = {id=29686,name="A Radical Notion",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=4131,description="We cannot afford to lose this war. I'd like to empower our sentries so that brave men and women don't have to die. The Legion has gotten a hold of a powerful elemental being. Its essence could be just what we need.",questType="dungeon"},
[29687] = {id=29687,name="Twisted Associations",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=4131,description="The Legion and Kael'thas' forces are becoming increasingly intertwined. This concerns me very deeply. From what we can gather Selin Fireheart and Priestess Delrissa work closely together to unite the two armies. You need to stop them.",questType="dungeon"},
[29688] = {id=29688,name="Advancing the Campaign",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=3714,description="I mostly listen, . I listen so that the Warchief doesn't have to. I've heard of the status of our campaign against the Hellfire Citadel. It is time to take the Shattered Halls , seat of power for the fel orcs. Go speak with Stone Guard Stok'ton , he's in charge there.",starts={{npcID=16575,x=0.55,y=0.362,zoneID=3483}},coords={x=0.55,y=0.362,source="quest_giver",zoneID=3483},questType="dungeon"},
[29689] = {id=29689,name="Advancing the Campaign",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=3714,description="The time has come to lay the final blow against the fel orcs. Advance Scout Chadwick awaits your presence inside the Shattered Halls of Hellfire Citadel. Make haste, their forces could strike against Honor Hold at any moment!",starts={{npcID=16819,x=0.566,y=0.666,zoneID=3483}},coords={x=0.566,y=0.666,source="quest_giver",zoneID=3483},questType="dungeon"},
[29690] = {id=29690,name="Into the Mists",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="You smell that, ? It's the smell of our home, the lands our kind have bled and died to preserve. And listen... you hear that? It's the sound of peace and safety - a haven we've carved, where our enemies fear to tread. Remember these things. You won't experience them again anytime soon. We have ourselves a war to win. Now go get settled, we're shovin' off!",starts={{npcID=55054,x=0.612,y=0.446,zoneID=14}},ends={{npcID=55135,x=0.308,y=0.102,zoneID=5785}},coords={x=0.612,y=0.446,source="quest_giver",zoneID=14},questType="standard"},
[29691] = {id=29691,name="Bring Me A Shrubbery!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,description="My people use sanguine hibiscus for a number of purposes. It grows naturally only in the Underbog , and many of the bog's denizens have taken a liking to it. If you could bring me some, I would be very grateful.",questType="dungeon"},
[29692] = {id=29692,name="Bring Me Another Shrubbery!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=3716,questType="dungeon"},
[29693] = {id=29693,name="The General's Edge",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="As you gradually gather your senses and begin to take in your surroundings, this object stands out amongst the strewn wreckage. It occurs to you that this is the first time you've seen Nazgrim's axe outside of his tight grasp. Somehow, this fact makes your predicament even more unsettling... You know that dead or alive, the General would want his weapon back in his possession.",questType="standard"},
[29694] = {id=29694,name="Regroup!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="They have an airbase! I have underestimated this Alliance Captain for the last time. So many good warriors lost... There must have been a few survivors who were able to bail during the crash. We need every able-bodied fighter we can get. Find as many survivors as you can in the forest below, and I will investigate the wreckage itself. Rally everyone together at the nearby village for a counter-attack.",starts={{npcID=66656,x=0.336,y=0.106,zoneID=5785}},ends={{npcID=66845,x=0.292,y=0.136,zoneID=5785}},coords={x=0.336,y=0.106,source="quest_giver",zoneID=5785},questType="standard"},
[29696] = {id=29696,name="My Stars!",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="A number of Kiryn's articles have been scattered around the area by wood sprites, but this one stands out as important to you. The bag once hung from her waist, loaded with throwing stars. Without them, her arsenal will be considerably diminished. If you were to retrieve the weapons from the pests that inhabit this region, it could only help your cause.",questType="standard"},
[29703] = {id=29703,name="Barrel of Monkies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,mapID=378,description="These monkeymen are driving me insane! I was just trying to get some insight into panderan brewing tactics and these hozu things keep drinking the brews before I can properly chemical test them. Can you please go take a few of them out as a lesson to the others? I'll make it worth your while.",questType="standard"},
[29715] = {id=29715,name="The Witch in the Woods",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[29716] = {id=29716,name="The Double Hozen Dare",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="There is a witch in the woods but no one believes me. She turned my friend Shin into jade! We were all so scared we tried to run back but she sicced her big jade monsters on us. A bunch of my friends tried to get away by climbing trees. Can you help me save my friends?",starts={{npcID=55234,x=0.466,y=0.46,zoneID=5785}},ends={{npcID=55234,x=0.466,y=0.46,zoneID=5785},{npcID=55274,x=0.387,y=0.452,zoneID=5785}},coords={x=0.466,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29717] = {id=29717,name="Down Kitty!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I tried to fight one of the jade tigers in the woods but they were too scary. They stare at you and you turn to a jade statue! Honest truth! Chen's sister's friend Ni heard it from Kai's mom. I want to be brave like you though. Can you show me how to beat up those jade tigers?",starts={{npcID=55234,x=0.466,y=0.46,zoneID=5785},{npcID=55274,x=0.387,y=0.452,zoneID=5785}},ends={{npcID=55234,x=0.466,y=0.46,zoneID=5785},{npcID=55274,x=0.387,y=0.452,zoneID=5785},{npcID=55413,x=0.47,y=0.46,zoneID=5785}},coords={x=0.466,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29722] = {id=29722,name="A Lesson in Bravery",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[29723] = {id=29723,name="The Jade Witch",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The Jade Witch must still have Shin. I... I can't do it! I don't want to see the witch. Can you please go talk to her and see if she has Shin? You're an adult, I don't think she would try to turn you into jade.",starts={{npcID=55234,x=0.466,y=0.46,zoneID=5785},{npcID=55274,x=0.387,y=0.452,zoneID=5785}},ends={{npcID=55413,x=0.47,y=0.46,zoneID=5785}},coords={x=0.466,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29725] = {id=29725,name="SI:7 Report: Fire From the Sky",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Yeah, we found Amber, she's alive, and all that. That's about where the good news stops though. Let's see if I can pick up where ol' Rell left off...",starts={{npcID=55282,x=0.588,y=0.818,zoneID=5785}},ends={{npcID=55282,x=0.588,y=0.818,zoneID=5785}},coords={x=0.588,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29726] = {id=29726,name="SI:7 Report: Hostile Natives",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I... I can tell you what happened next! We continued north, into the forest...",starts={{npcID=55284,x=0.59,y=0.818,zoneID=5785}},ends={{npcID=55284,x=0.59,y=0.818,zoneID=5785}},coords={x=0.59,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29727] = {id=29727,name="SI:7 Report: Take No Prisoners",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="The final leg of our journey took us west, to a large hozen village. We set up a small camp in the mountains, outside of their line of sight...",starts={{npcID=55283,x=0.588,y=0.818,zoneID=5785}},ends={{npcID=55283,x=0.588,y=0.818,zoneID=5785}},coords={x=0.588,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29728] = {id=29728,name="Explosive Evidence",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="I must ask you to do one more thing for me, . The personal effects on this ship cannot be left for others to find. We'll have to destroy it. I cobbled together some Makeshift Dynamite from the scraps you brought me. Place the dynamite anywhere on the ship, but take care not to put them too close together. They might be...uh...a little unwieldy, so you should spread them out in case of premature detonation.",questType="standard"},
[29730] = {id=29730,name="Scouting Report: Hostile Natives",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="I bet I know your first question: \"What the ook happened to Sergeant Gorrok?\" Don't worry, don't worry. He's totally alive. Not dead or anything. Riko shuffles uncomfortably.> Well, we THINK he's alive, but he ALSO might be very, very dead. Riko looks into your eyes for approval.> Fine! Let me tell you exactly what happened.",starts={{npcID=55648,x=0.286,y=0.474,zoneID=5785}},ends={{npcID=55648,x=0.286,y=0.474,zoneID=5785}},coords={x=0.286,y=0.474,source="quest_giver",zoneID=5785},questType="standard"},
[29731] = {id=29731,name="Scouting Report: On the Right Track",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="MOST of what Riko said is true. We didn't dare pursue Gorrok - the Horde's numbers here are far too few. Our forces can only sustain so many losses, and frankly, we don't know how powerful that witch really is. Let me pick up where the hozen left off...",starts={{npcID=55646,x=0.286,y=0.474,zoneID=5785}},ends={{npcID=55646,x=0.286,y=0.474,zoneID=5785}},coords={x=0.286,y=0.474,source="quest_giver",zoneID=5785},questType="standard"},
[29732] = {id=29732,name="What Goes Down, Must Come Up!",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Rivett left behind what looks to be an important piece of equipment. Along its shaft you are able to make out the words: Goblin Drone Dispenser . With a simple calibration, the device is set to deliver drones to Nazgrim's basecamp. Easy enough.... There's just one problem. The only supply crates worth transporting have fallen to the cliff ledge below the crash impact. As you ponder the issue, you see the long, coiled tail of a Cliff Glider fly by the corner of your eye...",questType="standard"},
[29733] = {id=29733,name="SI:7 Report: Lost in the Woods",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Please, . You need to hear what we've been through. The whole damned Alliance needs to hear what we've been through. There may not be much time left.",starts={{npcID=55333,x=0.59,y=0.818,zoneID=5785}},ends={{npcID=55333,x=0.59,y=0.818,zoneID=5785}},coords={x=0.59,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29734] = {id=29734,name="Deepforge the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5042,mapID=207,starts={{npcID=55216,x=0.276,y=0.692,mapID=207}},ends={{npcID=55216,x=0.276,y=0.692,mapID=207}},coords={x=0.276,y=0.692,source="quest_giver",mapID=207},questType="standard"},
[29735] = {id=29735,name="Stonebrand the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5042,mapID=207,starts={{npcID=55217,x=0.496,y=0.548,mapID=207}},ends={{npcID=55217,x=0.496,y=0.548,mapID=207}},coords={x=0.496,y=0.548,source="quest_giver",mapID=207},questType="standard"},
[29736] = {id=29736,name="Darkfeather the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4922,mapID=241,starts={{npcID=55218,x=0.518,y=0.33,mapID=241}},ends={{npcID=55218,x=0.518,y=0.33,mapID=241}},coords={x=0.518,y=0.33,source="quest_giver",mapID=241},questType="standard"},
[29737] = {id=29737,name="Firebeard the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=4922,mapID=241,starts={{npcID=55219,x=0.508,y=0.704,mapID=241}},ends={{npcID=55219,x=0.508,y=0.704,mapID=241}},coords={x=0.508,y=0.704,source="quest_giver",mapID=241},questType="standard"},
[29738] = {id=29738,name="Moonlance the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5144,mapID=205,starts={{npcID=55228,x=0.572,y=0.862,mapID=205}},ends={{npcID=55228,x=0.572,y=0.862,mapID=205}},coords={x=0.572,y=0.862,source="quest_giver",mapID=205},questType="standard"},
[29739] = {id=29739,name="Windsong the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=616,mapID=198,starts={{npcID=55224,x=0.266,y=0.62,mapID=198}},ends={{npcID=55224,x=0.266,y=0.62,mapID=198}},coords={x=0.266,y=0.62,source="quest_giver",mapID=198},questType="standard"},
[29740] = {id=29740,name="Evershade the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=616,mapID=198,starts={{npcID=55227,x=0.626,y=0.228,mapID=198}},ends={{npcID=55227,x=0.626,y=0.228,mapID=198}},coords={x=0.626,y=0.228,source="quest_giver",mapID=198},questType="standard"},
[29741] = {id=29741,name="Sekhemi the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5034,mapID=249,starts={{npcID=55210,x=0.316,y=0.63,mapID=249}},ends={{npcID=55210,x=0.316,y=0.63,mapID=249}},coords={x=0.316,y=0.63,source="quest_giver",mapID=249},questType="standard"},
[29742] = {id=29742,name="Menkhaf the Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5034,mapID=249,starts={{npcID=55211,x=0.654,y=0.186,mapID=249}},ends={{npcID=55211,x=0.654,y=0.186,mapID=249}},coords={x=0.654,y=0.186,source="quest_giver",mapID=249},questType="standard"},
[29743] = {id=29743,name="Monstrosity",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="It's plain to see that this statue and the surrounding ruins are of ancient origin. Clearly, this land has a deep history, which means it could not have been born of the cataclysm. And yet these waters have been explored for ages now, with no record of anything here but open sea. Perhaps if you were to sketch the pieces of this broken statue, you might shed light on the continent's origins.",starts={{npcID=212181,x=0.31,y=0.175,zoneID=5785}},coords={x=0.31,y=0.175,source="quest_giver",zoneID=5785},questType="standard"},
[29744] = {id=29744,name="Some \"Pupil of Nature\"",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Wood sprites are not prone to wandering, so I'm surprised they ventured down as far as the mason's quarter. Something must be forcing them out of their natural habitat. These particular sprites are native to the Woods of the Lost, just north of here. I'd go myself, but I've heard those woods are haunted. So yeah, that's out. I guess we'll never know. Orrrr... A big brave adventurer like YOU could go check it out! What do you say?",questType="standard"},
[29745] = {id=29745,name="The Sprites' Plight",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="For now, they seem content in pummeling the forest sprites into splinters, but if they continue any further the pandaren will have more than just missing jade to worry about.>",starts={{npcID=55438,x=0.486,y=0.25,zoneID=5785}},coords={x=0.486,y=0.25,source="quest_giver",zoneID=5785},questType="standard"},
[29747] = {id=29747,name="Break the Cycle",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="It seems that destroying the statues alone will not be enough to break the cycle.>",starts={{npcID=214871,x=0.486,y=0.206,zoneID=5785}},coords={x=0.486,y=0.206,source="quest_giver",zoneID=5785},questType="standard"},
[29748] = {id=29748,name="Simulacrumble",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Whatever dark magic the mogu are employing here, it seems to make the brittle statues significantly tougher. Better to destroy them while they are still vacant. A good old-fashioned kick should do the job.>",starts={{npcID=214871,x=0.486,y=0.206,zoneID=5785}},coords={x=0.486,y=0.206,source="quest_giver",zoneID=5785},questType="standard"},
[29749] = {id=29749,name="An Urgent Plea",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Please... help... heart of the ruins... a ritual... conjuring... ...should not be here... My staff... on the altar... take it. Please hurry.",starts={{npcID=55480,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29750] = {id=29750,name="Vessels of the Spirit",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The Spiritclaws are a sect of mogu assassin-priests who, at the height of the mogu empire, were the most elite and most feared of the emperor's troops. All have mastered a deathblow which ensnares the spirit of the enemy, trapping it in a jade bottle for delivery to a Spiritbinder. If you encounter any Spiritclaws further ahead in the ruins, take note: their belts hang with a cursed weight. Relieve them of their burden and bring the bottles back to me.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29751] = {id=29751,name="Ritual Artifacts",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="So many spirits held in captivity here... I can feel them everywhere. Even the walls are a cage for the long-dead. , we cannot simply break the sorcery over this place - doing so would release countless agonized souls to wander the earth. They will need a beacon, something to guide them. With your help, I can create a tan-chao: a bridge from this world to the heavens. For this ritual, I'll need a bowl, a candle, and a jade cong . You should be able to find them all within the ruins.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29752] = {id=29752,name="The Wayward Dead",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The process of mass conjuring, as the mogu are doing here, is not without byproduct. Some spirits arrive too distraught or unruly to be harnessed, so they are confined and left to wander until their desperation leaves them more malleable. I suspect the mogu have such a holding area somewhere nearby, likely guarded by spiritclaws. Please, take my staff again and use it to collect these wayward spirits. You needn't fight them - present the staff and they should be drawn in.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29753] = {id=29753,name="Back to Nature",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I'm afraid I have another favor to ask, . The bottles you recovered contain neither the spirits of mogu ancestors nor recently slain foes; they contain spirits of beasts. It seems the spiritclaws have resorted to poaching in an effort to fuel their simulacra. This complicates our task, for I cannot take the beasts with me through the bridge. Take the bottles west to Tideview Thicket and smash them to return the spirits to nature. Some may be blind with rage and will need to be subdued.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29754] = {id=29754,name="To Bridge Earth and Sky",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="We are ready to open the tan-chao and guide all of these spirits back to peace. If I may, I would have your assistance once more. The mogu will surely sense the ritual taking place and will do everything in their power to halt it. I need only a few moments without interference, and once the path is open it will surge too greatly to be closed. If you are willing to help one more time, please accompany me to the ritual site.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29755] = {id=29755,name="Pei-Back",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="the tan-chao , Pei-Zhi 's bridge to freedom. One final chamber lingers in the ruins, just north of the tan-chao . The air above crackles with foul energy. Shan Jitong is already at work.>",starts={{npcID=214903,x=0.438,y=0.125,zoneID=5785}},ends={{npcID=59492,x=0.438,y=0.124,zoneID=5785}},coords={x=0.438,y=0.125,source="quest_giver",zoneID=5785},questType="standard"},
[29756] = {id=29756,name="A Humble Offering",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I'm almost ready for the ritual, there's just one more thing we need: An offering. Relax, I don't mean a sacrifice. Just a bit of food. There are sure to be mushrooms growing in Tideview Thicket to the northwest that are suitable for this. Please bring some.",starts={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},ends={{npcID=55614,x=0.442,y=0.15,zoneID=5785}},coords={x=0.442,y=0.15,source="quest_giver",zoneID=5785},questType="standard"},
[29757] = {id=29757,name="Bottletoads",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Have you heard about the crisis we're having at the pools? Toads have moved in and are spawning like crazy! It's become a real problem for the lotus farmers. Coincidentally, I make a jam out of gelatinous toadspawn. I call it \"Bottletoads\" and it's a big hit with the kids around here. Can't keep any in stock. If you're heading to the pools, you'd be doing everyone a favor by uh... liberating some of those toad eggs. Into this bottle. For me. Just look for bubbles and scoop right in!",starts={{npcID=56773,x=0.606,y=0.338,zoneID=5805}},ends={{npcID=56773,x=0.606,y=0.338,zoneID=5805}},coords={x=0.606,y=0.338,source="quest_giver",zoneID=5805},questType="standard"},
[29758] = {id=29758,name="Guess Whose Back",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,ends={{npcID=56773,x=0.606,y=0.338,zoneID=5805}},questType="standard"},
[29759] = {id=29759,name="Kung Din",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I hope you are capable of this next task, for our lives depend on it. There is only one key that will unlock our chains. Unfortunately, the key hangs around the neck of the hozen's pet tiger, Kung Din. They keep the tiger in the great pit to the north. The only way to retrieve the key will be to kill the beast.",starts={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},ends={{npcID=55196,x=0.542,y=0.824,zoneID=5785}},coords={x=0.542,y=0.824,source="quest_giver",zoneID=5785},questType="standard"},
[29760] = {id=29760,name="Pit Fighter",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="There must be more to being a master pit fighter than this... Perhaps Korgol Crushskull who runs the Darkmoon Deathmatch at the Faire will know.",ends={{npcID=55402,x=0.474,y=0.788,zoneID=5861}},questType="pvp"},
[29761] = {id=29761,name="Master Pit Fighter",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,starts={{npcID=55402,x=0.474,y=0.788,zoneID=5861}},ends={{npcID=55402,x=0.474,y=0.788,zoneID=5861}},coords={x=0.474,y=0.788,source="quest_giver",zoneID=5861},questType="standard"},
[29762] = {id=29762,name="Family Heirlooms",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="We recently lost a fierce battle against the hozen at Moonwater Retreat. We evacuated as many of our people as we could, but still, there were many we could not save. We have no tokens of our lost over which to send our prayers. If someone could go and retrieve heirlooms from the dead bodies, we could properly lay them to rest, and move on. It would mean so much to us if you could do this, .",starts={{npcID=56222,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=56222,x=0.588,y=0.816,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29763] = {id=29763,name="Stealing Their Thunder",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=206,description="The vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple. There's one they esteem though, goes by the name of Ingvar. Bring him down and you'll deal a mighty blow to their spirit.",questType="dungeon"},
[29764] = {id=29764,name="Disarmament",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=206,description="Take it from me, , them vrykul weapons be downright nasty! Deceptively well-balanced, wickedly sharp - just plain deadly. I need you to pilfer some o' them weapons before they're used on us!",questType="dungeon"},
[29765] = {id=29765,name="Cryin' My Eyes Out",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="I coulda taken out da whole lot of 'em, mon. Shot 'em one by one, den played dead when dey be gettin' close. Fell for it every time, dey did - well almost every time... One of 'em finally got wise. Called my bluff. Before I knew it, dey was usin' my eyes as marbles. Ran off with my goods an' left me here ta die, da savages... Help me, mon. Lemme die wit my dignity intact.",starts={{npcID=55403,x=0.31,y=0.174,zoneID=5785}},ends={{npcID=55403,x=0.31,y=0.174,zoneID=5785}},coords={x=0.31,y=0.174,source="quest_giver",zoneID=5785},questType="standard"},
[29766] = {id=29766,name="A Good Start",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="Regardless of our predicament, our orders stand. We are to learn the lay of this land and prepare it for Hellscream's fleet. But first, we must deal with these savages! You see these corpses I've stacked up around the camp? I want mountains of them! We are the Horde! These vermin have not learned to fear us yet, but we will fix that soon enough...",questType="standard"},
[29767] = {id=29767,name="Fish Fry",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=5785,mapID=371,description="Fortune favors the bold! Your calculated aggressive actions have yielded unexpected rewards. If you can slay these fishcatchers after a successful haul, you'll inherit their slippery spoils. Thinning out the enemy while feeding your allies - the picture of efficiency!",questType="standard"},
[29768] = {id=29768,name="Missing Mallet",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", I've got it! It's simple really. Let's make a ruckus so loud that there's no way he can sleep through it. Why look at that, a conveniently placed gong! Makes me think this may just be how they've awoken him in the past. We just need the matching mallet to get it ringing as loud as possible. The village leader tells me the mallet is over at the Ki-Han Brewery on the river, to the southwest. It's not far. Mind picking it up for me while I give the village some fair warning?",starts={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},ends={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},coords={x=0.69,y=0.65,source="quest_giver",zoneID=5736},questType="standard"},
[29769] = {id=29769,name="Rascals",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=7902,description="I'll keep trying to find ways to wake this stubborn little guy up, but there is no shortage of trouble on the island it seems. The crops to the south are infested with virmen, rabbit-like thieves and pillagers. Rascals! They breed faster than we can kill them! I have the perfect solution for such a situation: kill them faster! With you here, , that shouldn't be a problem.",starts={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},ends={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},coords={x=0.69,y=0.65,source="quest_giver",zoneID=5736},questType="standard"},
[29770] = {id=29770,name="Still Good!",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=7902,description="The virmen to the south have been running off with all of our crops, but they're taking more than they can eat. They must be stockpiling them somewhere - the ones they like anyway. Will you go out and recover any of the uprooted crops you can find? I've got an island's worth of people to feed, and every single vegetable makes a difference.",starts={{npcID=55479,x=0.682,y=0.664,zoneID=5736}},ends={{npcID=55479,x=0.682,y=0.664,zoneID=5736}},coords={x=0.682,y=0.664,source="quest_giver",zoneID=5736},questType="standard"},
[29771] = {id=29771,name="Stronger Than Wood",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Gather me wood planks from construction near the Ki-Han Brewery. You do not yet know the extent of my strength, so I shall display it to you.",starts={{npcID=55478,x=0.69,y=0.666,zoneID=5736}},ends={{npcID=55478,x=0.69,y=0.666,zoneID=5736}},coords={x=0.69,y=0.666,source="quest_giver",zoneID=5736},questType="standard"},
[29772] = {id=29772,name="Raucous Rousing",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="You ready for this, ? I'm thinking maybe we should have looked for something to cover our ears, but it's a bit late for that now. Just remember that the intense ringing you'll be hearing for the next few hours is the ringing sound of victory! The honor's all yours, . Ring the gong whenever you're ready!",starts={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},ends={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},coords={x=0.69,y=0.65,source="quest_giver",zoneID=5736},questType="standard"},
[29774] = {id=29774,name="Not In the Face!",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Alright , I was thinking about what we'd try next if the whole gong thing didn't work, and it came to me just like that! Water in the face always worked on me. It's got to be twice as effective for someone so dry and earthy! Mind going over and asking Shu, the spirit of water, if he'll help us out? He should be playing in the pool next to the waterfall, just on the other side of that tree.",starts={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},ends={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},coords={x=0.69,y=0.65,source="quest_giver",zoneID=5736},questType="standard"},
[29775] = {id=29775,name="The Spirit and Body of Shen-zin Su",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Well, that wraps it up here, doesn't it ? Now that we've got these two roused and all friendly towards you, we just need to get them back to the Temple of Five Dawns. You go ahead. I'm going to say my goodbyes, then I'll follow you up shortly.",starts={{npcID=55477,x=0.69,y=0.65,zoneID=5736}},ends={{npcID=54786,x=0.514,y=0.462,zoneID=5736}},coords={x=0.69,y=0.65,source="quest_giver",zoneID=5736},questType="standard"},
[29776] = {id=29776,name="Morning Breeze Village",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="The fourth and final spirit is Dafeng, the spirit of air. When he is not in the skies, he can be found on the Ridge of Laughing Winds to the west. I've sent both Aysa and Ji to help you find him. When you are ready, I will summon winds to carry you to the top of the temple. From there, cross the bridges to the west and find Ji in Morning Breeze Village.",starts={{npcID=54786,x=0.514,y=0.462,zoneID=5736}},ends={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},coords={x=0.514,y=0.462,source="quest_giver",zoneID=5736},questType="standard"},
[29777] = {id=29777,name="Tools of the Enemy",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="The hozen have stolen our brushes and are painting over our scrolls of wisdom with their own wisdoms, if you can call them that. If you're here to help, stop them and bring our brushes back before they can do more harm.",starts={{npcID=55588,x=0.316,y=0.396,zoneID=5736}},ends={{npcID=55588,x=0.316,y=0.396,zoneID=5736}},coords={x=0.316,y=0.396,source="quest_giver",zoneID=5736},questType="standard"},
[29778] = {id=29778,name="Rewritten Wisdoms",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", we must help Elder Shaopai. There are few more deserving of our kindness. On the way here, you surely noticed the scrolls of wisdom hanging in the grotto to the south. The hozen have defiled many of them, and sadly, they are not recoverable. We will deal with the problem directly - burn the defiled scrolls. Wipe the hozen writings away entirely. Do not worry for Elder Shaopai. The people shall come together and help him rewrite the wisdoms in time. I shall see to that.",starts={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},ends={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},coords={x=0.308,y=0.368,source="quest_giver",zoneID=5736},questType="standard"},
[29779] = {id=29779,name="The Direct Solution",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Alright , this is the second time we've had to deal with ravaging hozen. I think it's time we take care of this problem the Huojin way. No more patience. No more mediation. We go to the source. We're going into the hozen village to the north and we're punishing those smelly troublemakers. I've been looking forward to a chance to fight by your side again, .",starts={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},ends={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},coords={x=0.308,y=0.368,source="quest_giver",zoneID=5736},questType="standard"},
[29780] = {id=29780,name="Do No Evil",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", I need you to understand that the way of the Huojin is not the way of violence. When fighting is needed, we will not hesitate, but when fighting is not needed, neither do we instigate. However, the direct solution is often cutting the head off the snake, as they say. The hozen have a leader instigating these attacks. If we remove Ruk-Ruk , we won't have to wipe the hozen out entirely. I know you are not of the Huojin, but are you with me in what must be done, ?",starts={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},ends={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},coords={x=0.308,y=0.368,source="quest_giver",zoneID=5736},questType="standard"},
[29781] = {id=29781,name="Monkey Advisory Warning",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="The monkeys have been stealing from the village during their attacks. We should be fine without some of the extra food stores, but the idea of monkeys with fireworks... I'm a little bit concerned. Not to mention, who knows when some fireworks will come in handy? Help me recover the stolen fireworks from their village, ?",starts={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},ends={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},coords={x=0.308,y=0.368,source="quest_giver",zoneID=5736},questType="standard"},
[29782] = {id=29782,name="Stronger Than Bone",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="This giant jade tiger pillar doesn't seem to fit in amidst the hozen buildings. What it does seem is very hard. Very solid. You know just the person to bring this to.",starts={{npcID=209673,x=0.265,y=0.338,zoneID=5736}},ends={{npcID=55585,x=0.3,y=0.396,zoneID=5736}},coords={x=0.265,y=0.338,source="quest_giver",zoneID=5736},questType="standard"},
[29783] = {id=29783,name="Stronger Than Stone",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Gather me stone blocks from the Ridge of Laughing Winds to the south. You have seen my strength twice, yet I still spy doubt within your eyes. It will not last.",starts={{npcID=55585,x=0.3,y=0.396,zoneID=5736}},ends={{npcID=55585,x=0.3,y=0.396,zoneID=5736}},coords={x=0.3,y=0.396,source="quest_giver",zoneID=5736},questType="standard"},
[29784] = {id=29784,name="Balanced Perspective",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Aysa has been meditating on the lake since we've arrived, all her thoughts focused on Dafeng. I don't know what she hopes to discover out there, but she's no fool, and Master Shang Xi has entrusted this task with her. You will need to cross the ropes leading from the end of the dock to reach her. It shall test your balance, but I think you're up to the task, .",starts={{npcID=55583,x=0.308,y=0.368,zoneID=5736}},ends={{npcID=55595,x=0.246,y=0.696,zoneID=5736}},coords={x=0.308,y=0.368,source="quest_giver",zoneID=5736},questType="standard"},
[29785] = {id=29785,name="Dafeng, the Spirit of Air",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="If you listen long enough, the wind will carry the answer to you. Dafeng , the spirit of air, has been scared from the skies by Zhao-Ren, the Onyx Serpent. He hides within the Chamber of Whispers, at the south side of the plateau. Go to him. Ji and I will join you there.",starts={{npcID=55595,x=0.246,y=0.696,zoneID=5736}},ends={{npcID=55592,x=0.246,y=0.696,zoneID=5736}},coords={x=0.246,y=0.696,source="quest_giver",zoneID=5736},questType="standard"},
[29786] = {id=29786,name="Battle for the Skies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Dafeng, the spirit of air, is terrified by Zhao-Ren , the Onyx Serpent. We must help him face that fear, or face it for him ourselves. When I told Ji of the serpent, he said he had an idea and would begin preparations outside of the chamber. Despite his rash nature, I must admit, I envy his passion and conviction. Let us go outside and confront the Onyx Serpent.",starts={{npcID=55595,x=0.246,y=0.696,zoneID=5736}},ends={{npcID=55586,x=0.3,y=0.604,zoneID=5736}},coords={x=0.246,y=0.696,source="quest_giver",zoneID=5736},questType="standard"},
[29787] = {id=29787,name="Worthy of Passing",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="The four elemental spirits will help you speak with the land and uncover its plight, but first, I have one small task to ask of you. Join me, my pupil. Accompany this old pandaren to the western grove.",starts={{npcID=55586,x=0.3,y=0.604,zoneID=5736}},ends={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},coords={x=0.3,y=0.604,source="quest_giver",zoneID=5736},questType="standard"},
[29788] = {id=29788,name="Unwelcome Nature",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="You faced forest sprites in the Dawning Valley, but the forest sprites in this grove are a different breed. Crueler and more dangerous. If you would clear some of these sprites out, the spirits would thank you.",starts={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},ends={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},coords={x=0.194,y=0.512,source="quest_giver",zoneID=5736},questType="standard"},
[29789] = {id=29789,name="Small, But Significant",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="I am tired, . I must rest. We have a ritual to perform, but we require some of the charms from this grove. If you wander the grove, you should see them all over hanging from the trees. If it does not offend one as young as you, will you permit me to sit and recover my strength while you gather these charms?",starts={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},ends={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},coords={x=0.194,y=0.512,source="quest_giver",zoneID=5736},questType="standard"},
[29790] = {id=29790,name="Passing Wisdom",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="This journey shall soon be yours to undertake without me. Stay for a few moments and listen to an old man's words. Let my knowledge serve as a foundation for yours, that you might be greater than I ever was.",starts={{npcID=55672,x=0.194,y=0.512,zoneID=5736}},ends={{npcID=56662,x=0.158,y=0.492,zoneID=5736}},coords={x=0.194,y=0.512,source="quest_giver",zoneID=5736},questType="standard"},
[29791] = {id=29791,name="The Suffering of Shen-zin Su",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Now is not the time to grieve. The balloon is ready, and Shen-zin Su awaits. We shall be the first pandaren to speak to Shen-zin Su in hundreds of years. It is a great honor.",starts={{npcID=56662,x=0.158,y=0.492,zoneID=5736}},ends={{npcID=56012,x=0.512,y=0.484,zoneID=5736}},coords={x=0.158,y=0.492,source="quest_giver",zoneID=5736},questType="standard"},
[29792] = {id=29792,name="Bidden to Greatness",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="It is up to all of you to remove the thorn from the side of Shen-zin Su. Do not let your differences come between you. Trust in each other. Within the Pei-Wu Forest is a lone hermit. Head directly to his hut. He knows intimately of the dark things that now lurk in the trees.",starts={{npcID=56012,x=0.512,y=0.484,zoneID=5736}},ends={{npcID=55943,x=0.5,y=0.764,zoneID=5736}},coords={x=0.512,y=0.484,source="quest_giver",zoneID=5736},questType="standard"},
[29793] = {id=29793,name="Evil from the Seas",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="I do not know what this evil is that is infesting the forest, , but I know exactly how to deal with it. So do you, I think.",starts={{npcID=55942,x=0.364,y=0.724,zoneID=5736}},ends={{npcID=55942,x=0.364,y=0.724,zoneID=5736}},coords={x=0.364,y=0.724,source="quest_giver",zoneID=5736},questType="standard"},
[29794] = {id=29794,name="None Left Behind",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Your friend has been doing everything she can to save my crew. I'm deeply appreciative. We're still dealing with more than we can handle here: quenching the fires on the wreckage, getting my people out, fighting off these evil sea creatures, and trying to prevent the prisoners from escaping. We're simply in over our heads. I still have men on the ship that we need to get clear before the wreckage collapses on them. I know this is asking a lot, but can you help?",starts={{npcID=55944,x=0.422,y=0.864,zoneID=5736}},ends={{npcID=55944,x=0.422,y=0.864,zoneID=5736}},coords={x=0.422,y=0.864,source="quest_giver",zoneID=5736},questType="standard"},
[29795] = {id=29795,name="Stocking Stalks",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="My men are malnourished, injured, and exhausted, but they are Horde. Every one will fight to their dying breath. As our new ally, we will stand by you when the time comes, but we would stand stronger with weapons. I have my men out gathering bamboo stalks to fashion into spears. If you can spare the effort, we could use the extra pair of capable hands.",starts={{npcID=60042,x=0.502,y=0.766,zoneID=5736}},ends={{npcID=60042,x=0.502,y=0.766,zoneID=5736}},coords={x=0.502,y=0.766,source="quest_giver",zoneID=5736},questType="standard"},
[29796] = {id=29796,name="Urgent News",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="I'm sure Aysa won't love this plan, but it's the only plan we've got. Would you mind being the bearer of bad news for me, ? She needs to know what we're doing so she can get everyone to safety.",starts={{npcID=55942,x=0.364,y=0.724,zoneID=5736}},ends={{npcID=55944,x=0.422,y=0.864,zoneID=5736}},coords={x=0.364,y=0.724,source="quest_giver",zoneID=5736},questType="standard"},
[29797] = {id=29797,name="Medical Supplies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="We need supplies to tend to our wounded, but the supply crates containing them were scattered in the crash. If you can bring back any crates you find, I would be very grateful.",starts={{npcID=55944,x=0.422,y=0.864,zoneID=5736}},ends={{npcID=55944,x=0.422,y=0.864,zoneID=5736}},coords={x=0.422,y=0.864,source="quest_giver",zoneID=5736},questType="standard"},
[29798] = {id=29798,name="An Ancient Evil",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", I was looking for you! One of the escaping sailors just spotted Aysa in the wreckage of the ship, facing some enormous beast. She might need your help - you should go to her, quickly!",starts={{npcID=55940,x=0.422,y=0.864,zoneID=5736}},ends={{npcID=56416,x=0.366,y=0.842,zoneID=5736}},coords={x=0.422,y=0.864,source="quest_giver",zoneID=5736},questType="standard"},
[29799] = {id=29799,name="The Healing of Shen-zin Su",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="This is more horrific than I imagined, but we can handle this. We need to gather the healers and close the wound. We need to save Shen-zin Su. Find any healers you can! Rescue them, relieve them - whatever you need to do to get them over here healing the wound. Keep the healers safe at all costs!",starts={{npcID=56418,x=0.392,y=0.862,zoneID=5736}},ends={{npcID=56418,x=0.392,y=0.862,zoneID=5736}},coords={x=0.392,y=0.862,source="quest_giver",zoneID=5736},questType="standard"},
[29800] = {id=29800,name="New Allies",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description=", I did what had to be done. And the plan worked. Things could have been much worse had we not acted. I only wish Aysa could understand that. There will be plenty of time for reflection, but for now, we need to return to the Temple of Five Dawns. We need to let them know that Shen-zin Su has been saved, and we need to sort out the fates of these new allies.",starts={{npcID=57739,x=0.388,y=0.864,zoneID=5736}},ends={{npcID=56013,x=0.514,y=0.484,zoneID=5736}},coords={x=0.388,y=0.864,source="quest_giver",zoneID=5736},questType="standard"},
[29801] = {id=29801,name="Proving Your Worth",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5892,description="Hello, ! You've earned a reputation among the flight as having - shall we say - 'nimble fingers.' We need someone of your skills for a matter of utmost delicacy. Before I reveal more, we need to know you're the right for the job. When the course of battle takes you to the Eye of Eternity, I need you to pickpocket Hagara the Stormbinder to retrieve a cryptomancer's decoder ring . Are you up to the task?",starts={{npcID=55476,x=0.502,y=0.596,zoneID=5892}},ends={{npcID=55476,x=0.502,y=0.596,zoneID=5892}},coords={x=0.502,y=0.596,source="quest_giver",zoneID=5892},questType="standard"},
[29802] = {id=29802,name="A Hidden Message",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=4922,description="Corastrasza , currently stationed at the Vermillion Redoubt in the Twilight Highlands, has intercepted a coded message of grave importance. I'll let her explain the full situation, but we need your expertise to unravel the cipher! Take your decoder ring to an ethereal thaumaturge in your capital city - he should know how to charge it. Acquire the encoded cipher from Corastrasza and use the ring to decode it for her. Hurry! Time is ticking...",starts={{npcID=55476,x=0.502,y=0.596,zoneID=5892}},ends={{npcID=55488,x=0.29,y=0.25,zoneID=4922}},coords={x=0.502,y=0.596,source="quest_giver",zoneID=5892},questType="standard"},
[29803] = {id=29803,name="Ears of the Lich King",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=206,description="Prince Keleseth acts as Arthas' eyes and ears in the Fjord. I don't like that one bit! Go and give him a round o' pain. You'll be doing the world a favor by doing so.",questType="dungeon"},
[29804] = {id=29804,name="Seein' Red",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="I was just about ta curl up an' die, mon. Now, dis! Snuff an' me go way back. Oh, da memories... No way I can face Snuff in da afterlife without avengin' his death first, mon! Dese hooligans be led by one named Konk . We gotta sniff him out an' den snuff him out - for Snuff!",starts={{npcID=55403,x=0.31,y=0.174,zoneID=5785}},ends={{npcID=65999,x=0.316,y=0.218,zoneID=5785}},coords={x=0.31,y=0.174,source="quest_giver",zoneID=5785},questType="standard"},
[29807] = {id=29807,name="Death to the Traitor King",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=4277,description="Anub'arak, the traitor king, makes his home in the once proud Kingdom of Azjol-Nerub . He has twisted and perverted our homeland into the wretched squalor it is today. He rules over an army of undead nerubians who have pledged themselves to serving the Lich King. Bring an end to his reign.",questType="dungeon"},
[29808] = {id=29808,name="Don't Forget the Eggs!",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=4277,description="Throughout Azjol-Nerub , the scourged nerubians carefully nurture eggs that will soon hatch, providing them nerubian young to slaughter and raise. The eggs have been tainted with foul magics. Our only recourse is to dispose of them.",questType="dungeon"},
[29809] = {id=29809,name="Efficient Excavations",level=30,requiredLevel=30,faction="none",expansion=4,zoneID=5034,mapID=249,description="This manual describes outlandish theories on how to most efficiently manage large groups of workers as they engage in massive excavation projects. After a quick skim of the material, it becomes clear to you that the author of the book is the figure in charge of the over-aggressive pillagers here. A map on the back cover indicates that the author has a bunker in the southwest region of Uldum . Perhaps an introduction is in order.",questType="standard"},
[29811] = {id=29811,name="The Gatewatcher's Talisman",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=4277,description="Krik'thir, guardian of the gates to Azjol-Nerub , was not a traitor. He fell in the War of the Spider defending our home from the Scourge. As per his station, he was in possession of the key to the hidden empire. I'd like you to retrieve it so it may be returned to its people.",questType="dungeon"},
[29815] = {id=29815,name="Forensic Science",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="These creatures are everywhere - and very hostile! We'll need to deal with them before any more Alliance show up. This one's taken quite a beating, but I've still made some determinations about its anatomy. With the proper reagents, I'll be able to fashion a poison that should be quite effective against this species. In fact, I'll just need to modify a bit of the poison I have with me. Go and find me some viscous chlorophyll down by the water. Any semi-sentient flora should do.",starts={{npcID=55180,x=0.282,y=0.248,zoneID=5785}},ends={{npcID=55180,x=0.282,y=0.248,zoneID=5785}},coords={x=0.282,y=0.248,source="quest_giver",zoneID=5785},questType="standard"},
[29820] = {id=29820,name="Into the Nexus",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=4120,description="I sent Warmage Kaitlyn into the Nexus to investigate the chaos that is Malygos' domain, but she hasn't reported back in days. Would you mind going there and lending her aid? I'm certain she could use help if she hasn't been eaten by dragons.",questType="dungeon"},
[29821] = {id=29821,name="Missed Me By... That Much!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Listen, . I sent out a coupla supply drones from the gunship, and they've all been lost or crashed. Almost all, that is. One of 'em buzzed right through the camp here and crashed out by them waterfalls. How 'bout you see what you can do about bringin' the contents of that crate back here, hmm? We're all outta drones, but my rocket boots might yet come in handy... or footy, as the case may be. Hah! I just kill me...",starts={{npcID=55521,x=0.312,y=0.216,zoneID=5785}},coords={x=0.312,y=0.216,source="quest_giver",zoneID=5785},questType="standard"},
[29822] = {id=29822,name="Lay of the Land",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Curse these furry pests! Kill one, and two more rise in its place... Nothing has changed, . Orders are orders, no matter how few of us stand and regardless of the odds. I have plans to make and problems to solve. I want you to get out there and learn the lay of the land. Don't return until you have something useful to report. And silence that yammering fool while you're out there! Dismissed!",starts={{npcID=55172,x=0.284,y=0.248,zoneID=5785}},ends={{npcID=55768,x=0.276,y=0.326,zoneID=5785}},coords={x=0.284,y=0.248,source="quest_giver",zoneID=5785},questType="standard"},
[29823] = {id=29823,name="Scouting Report: The Friend of My Enemy",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="We weren't only looking for Alliance, you know. We were also looking for those snooked-up, tik-flikklin' jinyu! Well, we found 'em all right...",starts={{npcID=55648,x=0.286,y=0.474,zoneID=5785}},ends={{npcID=55648,x=0.286,y=0.474,zoneID=5785}},coords={x=0.286,y=0.474,source="quest_giver",zoneID=5785},questType="standard"},
[29824] = {id=29824,name="Scouting Report: Like Jinyu in a Barrel",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="With our leader turned to jade, our hozen guide disappeared, and a prisoner of war in tow, there was only one thing that Kiryn and I could do: March into our enemy's territory and deliver some vengeance. Want to know how it went?",starts={{npcID=55647,x=0.286,y=0.474,zoneID=5785}},ends={{npcID=55647,x=0.286,y=0.474,zoneID=5785}},coords={x=0.286,y=0.474,source="quest_giver",zoneID=5785},questType="standard"},
[29827] = {id=29827,name="Acid Rain",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Since you've been gone, more and more of these creatures are approaching our camp. They appear to be amassing for a major assault! We're going to have to take some drastic measures if we hope to see tomorrow. Here, take my poisoned throwing stars and figure out a way to thin out their numbers.",starts={{npcID=55180,x=0.282,y=0.248,zoneID=5785}},ends={{npcID=55180,x=0.282,y=0.248,zoneID=5785}},coords={x=0.282,y=0.248,source="quest_giver",zoneID=5785},questType="standard"},
[29829] = {id=29829,name="Discretion is Key",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=4415,description="Listen to me, . It's just been brought to my attention that there's been an incident at the Violet Hold . It would appear that the blues are launching a full scale invasion of Dalaran! I need you to get to the prison and speak with Lieutenant Sinclari at once. She'll give you the details. That is not all. I need this handled with utmost discretion. We mustn't alarm the citizens of Dalaran if it can possibly be avoided. Do I make myself clear? Very well. Now, go!",questType="dungeon"},
[29830] = {id=29830,name="Containment",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=4415,description="My forces are in absolute shambles, and Malygos' assailants just keep coming. I fear that the worst has yet to come. You must engage them until their leader, Cyanigosa , comes. Only her death will stop the invasion and save Dalaran. Speak to me again when you are ready.",questType="dungeon"},
[29831] = {id=29831,name="DEPRECATED: Terror on the High Seas",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="Word has reached Stormwind of terrible crimes committed against ships carrying Alliance citizens. The Horde stands accused of stopping Alliance ships, boarding them, mistreating passengers, and stealing cargo. Heroes of the Alliance, your help is needed to determine the truth of these allegations! Seek out Grand Admiral Jes-Tereth at Stormwind Keep if you would answer the call.",questType="standard"},
[29832] = {id=29832,name="DEPRECATED: Gathering Evidence",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="A ship called the Bravery routinely ferries passengers and cargo from Stormwind port to Rut'theran Village, right outside Darnassus. Well, the ship has just returned with distressing news. Both passengers and crew say that Horde vessels stopped and boarded the Bravery in the waters off Teldrassil, mistreated those on board, and stole some of the cargo before turning the ship around. We have to find out what happened, . Would you go to Stormwind Harbor and listen to the stories of the passengers?",questType="standard"},
[29833] = {id=29833,name="Unfinished Business",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="While it is true that the Prophet of Akali will trouble this world no more, there yet remains work to be done. The greater part of Akali's blood has empowered another, and it is in him that the true danger lies. Quickly, , make your way to Gundrak and speak with Tol'mar . He will be able to direct you further in this cause.",starts={{npcID=28401,x=0.636,y=0.702,zoneID=66}},coords={x=0.636,y=0.702,source="quest_giver",zoneID=66},questType="dungeon"},
[29834] = {id=29834,name="Gal'darah Must Pay",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="It musta been da most awful thing I ever seen. Da great Akali - slain right before my eyes. Horrible... My job be to observe only. But dis cannot stand! Gal'darah and his followers must pay! Avenge Akali's death, mon. It be da right thing ta do.",questType="dungeon"},
[29835] = {id=29835,name="Gal'darah Must Pay",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="Da mighty Akali has been slain, . My role in life be to record, not fight. But dis cannot stand! Gal'darah and his followers must pay! Avenge Akali's death, mon. It be da right thing ta do.",questType="dungeon"},
[29836] = {id=29836,name="Just Checkin'",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="There have been fearsome sounds echoing from Gundrak . They have been increasing in volume and frequency of late. My long-time student is currently recording events from inside Gundrak . Perhaps you could find the time to check in on her for me?",starts={{npcID=28527,x=0.598,y=0.578,zoneID=66}},coords={x=0.598,y=0.578,source="quest_giver",zoneID=66},questType="dungeon"},
[29837] = {id=29837,name="Sacred Scroll",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="The unfamiliar markings on this parchment have an elegance about them that Yoggtord and his gang don't seem capable of. You suspect that, like everything else these Hozu possess, this is stolen merchandise. Perhaps the original owner of the scroll is still nearby...",questType="standard"},
[29838] = {id=29838,name="One of a Kind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="At first glance, it be lookin' like da same old story here - trolls tappin' into forbidden powah by destroyin' da very beings dey should be worshippin'. If what I learned be true, den dey have a special golem - one like nuthin' created before! Bring me back a piece from dat golem ta study.",questType="dungeon"},
[29839] = {id=29839,name="One of a Kind",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="Dis whole mess coulda been avoided if da Drakkari had worshipped da gods instead of destroyin' dem. I heard dat dey have a special golem - one imbued with forbidden powah. Bring me back a piece from dat golem so we can learn from our bruddas and sistahs.",questType="dungeon"},
[29840] = {id=29840,name="For Posterity",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="Gundrak looks doomed. You know dis to be true. If you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end. Perhaps one day we be bringin' dem back to der former glory.",questType="dungeon"},
[29842] = {id=29842,name="Seeking Answers",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,description="So much to ponder, traveler... You first must learn how to ask before your mind can discern the truth. I have completed my meditations for today, but my candles remain at the Cairn of Blood. Go there. Clear your mind. We will speak again when you are prepared to hear my words.",questType="standard"},
[29844] = {id=29844,name="For Posterity",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4416,description="Da land of da ice trolls is a shadow of its former glory. If you be havin' the courage, search for history tablets to see what brought the Drakkari Empire to such an end. Perhaps one day we be givin' dis land back to a new line of frost trolls.",questType="dungeon"},
[29847] = {id=29847,name="To Catch a Thief",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="Just beyond this cave lies Ravenholdt Manor. You need to get inside without being seen! Mostrasz places an enchantment on you.> There - now I'll be able to keep an eye on you and communicate as you venture into the compound. Now sneak into that manor, locate the egg, and don't get caught...",starts={{npcID=56375,x=0.678,y=0.452,zoneID=267}},ends={{npcID=57777,x=0.714,y=0.456,zoneID=267}},coords={x=0.678,y=0.452,source="quest_giver",zoneID=267},questType="standard"},
[29854] = {id=29854,name="DEPRECATED: Claiming Kalimdor",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=1637,mapID=85,description="Victory shall soon be ours! Our forces have engaged the enemy all over Kalimdor. Warchief Garrosh Hellscream has commanded all able-bodied s to report for duty in support of our latest offensive. Make your way to Grommash Hold in Orgrimmar and present yourself to General Nazgrim for immediate assignment! For the Horde!",questType="standard"},
[29857] = {id=29857,name="DEPRECATED: Where Are Those Ships?",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=1637,mapID=85,description="With most of our fleet leading the attack on Theramore and engaging the enemy elsewhere, we're going to need more ships to complete our blockade of Kalimdor. The warchief ordered the shipwrights at Zoram'gar Outpost in Ashenvale to work overtime to meet the demand, but none of the new craft have arrived yet. Travel there and put the question to their overseer. Tell them the warchief wants his ships!",questType="standard"},
[29860] = {id=29860,name="Diametrically Opposed",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4272,description="I shall speak plainly to you, little . My people have not been the same since our ties with Thorim were severed. Volkhan will not rest until either he, or we, are no more. We only want peace, but it seems we have no choice but war.",questType="dungeon"},
[29861] = {id=29861,name="Whatever it Takes!",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4272,description="One way or another, Loken shall fall. The honor and glory of his defeat shall be yours. Return to me with his lying tongue, and earn my unending gratitude.",questType="dungeon"},
[29862] = {id=29862,name="Clearing the Way",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4272,description="Loken's forces prepare for war. What they are not ready for is to be attacked themselves. Now is the moment to strike. Take out General Bjarngrim and his army, lest they mount an offensive on all life on Azeroth!",questType="dungeon"},
[29863] = {id=29863,name="Stormherald Eljrrin",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=4272,description="I have sent an emissary to the Halls of Lightning to take the battle to Loken. He undoubtedly needs assistance, given the strength of Loken's armies. Lend him any aid you can so that we may finally stop the traitor.",starts={{npcID=30105,x=0.654,y=0.602,zoneID=67}},coords={x=0.654,y=0.602,source="quest_giver",zoneID=67},questType="dungeon"},
[29865] = {id=29865,name="The Silkwood Road",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="West of here is the Silkwood Road. It has fallen into shadow as the spiders there have turned to a more evil and gluttonous path. I would face these villains myself but someone has to defend the noodle shop from... um... dangers and such. Go, hero, and conquer these beasts! Should you succeed perhaps I shall regale you with some of my epic tales of heroism. I'll also pay you.",starts={{npcID=56062,x=0.464,y=0.458,zoneID=5785}},ends={{npcID=56062,x=0.464,y=0.458,zoneID=5785}},coords={x=0.464,y=0.458,source="quest_giver",zoneID=5785},questType="standard"},
[29866] = {id=29866,name="The Threads that Stick",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Ah, welcome traveler. I have need of your services! Syra Goldendraft was looking for some silk. Personally I hate silk as it always gets stuck in my fur. I really want to impress her though. If you bring me some silk from the Silkwood to the west of here I will gladly pay you for your help.",starts={{npcID=59178,x=0.466,y=0.454,zoneID=5785}},ends={{npcID=59178,x=0.466,y=0.454,zoneID=5785}},coords={x=0.466,y=0.454,source="quest_giver",zoneID=5785},questType="standard"},
[29867] = {id=29867,name="DEPRECATED: Shadow Hunter Urko'jin",level=5,requiredLevel=5,faction="none",expansion=4,description="We need to fill the remaining slots in the new blockade fleet before the night elves can reestablish their spy network in the city. The Darkspears have yet to contribute much to the war effort, but if we can convince Shadow Hunter Urko'jin to add his forces to the fleet, that will change. Problem is, Urko'jin won't go to war without the blessing of the spirits. Pay a visit to Darkspear Hold in the Echo Isles, retrieve the totem of seafaring, and deliver it to Urko'jin in the Valley of Spirits.",questType="standard"},
[29871] = {id=29871,name="Clever Ashyo",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I'm not sure where Clever Ashyo got his \"Clever\" title from. All jinyu are clever, and I wouldn't say that he's any more clever than most of them. Quite the opposite, actually. At least he's a capable fighter. He did well enough at Tian Monastery to be selected for our training mission. If you want to help him look for the Hidden Master, you can find him along the Valley's northern border.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56113,x=0.612,y=0.342,zoneID=5805}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29872] = {id=29872,name="Lin Tenderpaw",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Lin is more talented than she thinks she is. Strong of fist but weak of spirit. With more confidence, she could be better than all of us. Perhaps she will find the surety she needs on her trip into the west. She's probably on her way to Stoneplow as we speak. Stop and speak to her, if you find yourself on that side of the Valley.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56111,x=0.198,y=0.57,zoneID=5805}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29873] = {id=29873,name="Ken-Ken",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="So... Ken-Ken . The hozen. Personally, I'm impressed he's progressed so far in his training. He's got a brain between his ears, which is more than can be said for most of his kind. He said he was headed east, but, seeing as we're already on the far east side of the valley, I can't imagine he went too far from here. Look for him at Zhu's Watch, in Krasarang Wilds , down the path to the south. See what he's found.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29874] = {id=29874,name="Kang Bramblestaff",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds . I wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave was looking out for him.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56114,x=0.674,y=0.326,zoneID=6134}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29875] = {id=29875,name="Kang Bramblestaff",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Kang's pride regularly becomes overconfidence, which often leads him down dangerous paths. His current path is as dangerous as any - he is headed deep into the Krasarang Wilds . I wouldn't normally ask a favor of a stranger, but... would you make sure that he is well? It would give me relief to know that a brave was looking out for him.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56112,x=0.6,y=0.25,zoneID=6134}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29877] = {id=29877,name="A Poor Grasp of the Basics",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Virmen - they no just eat our food. They trying to start farms of their own. The problem is... well, they ookin' dumb. You no believe Muno? Last night, they break into tool sheds... steal equipment. When we wake up, we find rakes and wheelbarrows planted in ground. They was WATERING them. They was trying to GROW WHEELBARROWS. Please, while you out there, unbury our stuff.",starts={{npcID=56440,x=0.828,y=0.212,zoneID=5805}},ends={{npcID=56440,x=0.828,y=0.212,zoneID=5805}},coords={x=0.828,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[29879] = {id=29879,name="Swallowed Whole",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Now, back to your dilemma. I believe you can help your people build relations with our hozen, as my people have. The trail behind me will lead you to a body of water the hozen use to gather the fish that feeds them. Around this time every year, fearsome beasts call those waters home and many hungry hozen are lost to them. If you were to rescue some of the victims and gather some fish, perhaps you will be regarded more favorably.",starts={{npcID=63307,x=0.288,y=0.326,zoneID=5785}},ends={{npcID=56313,x=0.262,y=0.372,zoneID=5785}},coords={x=0.288,y=0.326,source="quest_giver",zoneID=5785},questType="standard"},
[29881] = {id=29881,name="The Perfect Color",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="As you have seen, this grove is abundant with beautiful pink petals. As each petal ages, the tone deepens and fades. If you would be so kind, I am in need of a few petals that have freshly fallen. Only the ones that have just fallen will have precisely the right color I am after. From it I can forge an ink that will be breathtaking. Can you help me?",starts={{npcID=56064,x=0.548,y=0.452,zoneID=5785}},ends={{npcID=56064,x=0.548,y=0.452,zoneID=5785}},coords={x=0.548,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[29882] = {id=29882,name="Quill of Stingers",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="To achieve perfect paint strokes, one must have the right tools. My own have fallen into disrepair, their bristles becoming as unmanageable as hozu hair. Have you seen the wasps throughout the Arboretum? Their stingers can be fashioned into quills that provide just the right level of sharpness in each line. Could you gather some for me please?",starts={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},ends={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},coords={x=0.552,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[29883] = {id=29883,name="The Pearlfin Situation",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I've been thinking. We are cut off from support and a long way from home. Although these Pearlfin jinyu mistrust our presence, they do not appear to be hostile. If we could convince them that we are their friends, an alliance between our races could prove extremely valuable. , you must go speak to the jinyu around the village. Convince their leaders that we are not to be feared, and that we only wish for peace.",starts={{npcID=66949,x=0.588,y=0.818,zoneID=5785}},ends={{npcID=66949,x=0.588,y=0.818,zoneID=5785}},coords={x=0.588,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29885] = {id=29885,name="Road Rations",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="We do not have time to wait around for the Admiral to recover. Sully and I are planning to search for Anduin to the north, but we'll need supplies for our journey. The lake here is teeming with wildlife, which we have received permission to hunt. Go and gather some supplies while Sully and I finalize our preparations.",starts={{npcID=66949,x=0.588,y=0.818,zoneID=5785}},ends={{npcID=66949,x=0.588,y=0.818,zoneID=5785}},coords={x=0.588,y=0.818,source="quest_giver",zoneID=5785},questType="standard"},
[29886] = {id=29886,name="Zen Healing",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Your friend Taylor is in critical shape. Unfortunately, his wounds are tainted by hozen poison, which is very difficult to cure. Luckily, through many generations of fighting the hozen, my people have developed medicines to treat such injuries. The flowers growing on the surface of Glass Lake are needed to make the antidote. , go quickly and bring back some blooms. Your Admiral's life depends on it.",questType="standard"},
[29887] = {id=29887,name="The Elder's Instruments",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Oh dear, oh dear... The Elder mustn't find out! I must have left the Elder's ceremonial instruments behind during the escape. But... Moonwater Retreat is crawling with hozen by now! What sort of Pearlkeeper am I, to have lost them so carelessly? Stranger, could you find it in your heart to help me?",starts={{npcID=59058,x=0.588,y=0.812,zoneID=5785}},ends={{npcID=59058,x=0.588,y=0.812,zoneID=5785}},coords={x=0.588,y=0.812,source="quest_giver",zoneID=5785},questType="standard"},
[29888] = {id=29888,name="Seek Out the Lorewalker",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I see that you and your people are desperate to find your Prince Anduin. I know someone who may be able to help you, a pandaren Lorewalker who knows this land better than anyone. I cannot guarantee what kind of reception you will receive, but he will almost certainly be as curious about you as you are of him! The Lorewalker lives in the forest to the southwest. Tell him that the Pearlfin have sent you.",starts={{npcID=56222,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=209845,x=0.537,y=0.915,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29889] = {id=29889,name="Borrowed Brew",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="A delicious smell wafts out from the bottle on the table. A little taste couldn't hurt, right?",starts={{npcID=209845,x=0.537,y=0.915,zoneID=5785}},ends={{npcID=54961,x=0.536,y=0.914,zoneID=5785}},coords={x=0.537,y=0.915,source="quest_giver",zoneID=5785},questType="standard"},
[29890] = {id=29890,name="Finding Your Center",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="The dream brew is complete! This time, when you drink it, you must embrace the visions you see from a state of inner focus. Follow me to my pagoda, and I will teach you how to achieve the inner calm that we pandaren value so much. Your troubled mind will present you with many distractions, but just remember to stay centered!",starts={{npcID=56287,x=0.538,y=0.906,zoneID=5785}},ends={{npcID=56434,x=0.658,y=0.792,zoneID=5785}},coords={x=0.538,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[29891] = {id=29891,name="Potency",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="To make the Dream Brew, we will need several ingredients. First, to improve its strength, I will need an ingredient from a fearsome creature, the legendary Mist Horror. It is said that this creature only appears where the fog is deepest. North and east of here, you will find smaller Mist Creepers roaming the swamps. Kill these creatures until the Mist Horror appears, and then bring me its heart.",starts={{npcID=56287,x=0.538,y=0.906,zoneID=5785},{npcID=61218,x=0.536,y=0.914,zoneID=5785}},ends={{npcID=56287,x=0.538,y=0.906,zoneID=5785}},coords={x=0.538,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[29892] = {id=29892,name="Body",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="A brew's body is an important and often overlooked factor. To create the perfect consistency, I will need pristine eyes from the Bog Crocolisks to the east. Take care. The creatures are quite vicious.",starts={{npcID=56287,x=0.538,y=0.906,zoneID=5785},{npcID=61218,x=0.536,y=0.914,zoneID=5785}},ends={{npcID=56287,x=0.538,y=0.906,zoneID=5785}},coords={x=0.538,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[29893] = {id=29893,name="Hue",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="The most distinguishing feature of the Dream Brew is its iridescent, dream-like color. To the east, you will find Glittering Amberflies. I will need their wings to create the final luminescent color of the brew. Take this knife and use it to collect 8 wings.",starts={{npcID=56287,x=0.538,y=0.906,zoneID=5785},{npcID=61218,x=0.536,y=0.914,zoneID=5785}},ends={{npcID=56287,x=0.538,y=0.906,zoneID=5785}},coords={x=0.538,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[29894] = {id=29894,name="Spirits of the Water",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Our war against the hozen rages without end, and the future of our tribe is uncertain. This is why our waterspeaker has decided to seek wisdom from the waters. Elder Lusshan is waiting. Please deliver the instruments so that they may begin.",starts={{npcID=59058,x=0.588,y=0.812,zoneID=5785}},ends={{npcID=56222,x=0.588,y=0.816,zoneID=5785}},coords={x=0.588,y=0.812,source="quest_giver",zoneID=5785},questType="standard"},
[29895] = {id=29895,name="Trail of the White Pawn",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,mapID=371,description="Although the cloak is ragged and torn, there is no mistaking the fine tailoring and the King's royal crest. You should show it to your Alliance commander.",ends={{npcID=60970,x=0.588,y=0.816,mapID=371}},questType="standard"},
[29898] = {id=29898,name="Sacred Waters",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I appreciate you coming all this way to save me, but Ren is gravely injured. The old pandaren had no reason to help me, yet still he risked his life to save my own. Before the fever set in, he mentioned that there are healing waters in the cave just down the hill. It is dangerous, but I will do anything to help my friend. Will you help me retrieve the waters?",starts={{npcID=56434,x=0.658,y=0.792,zoneID=5785}},ends={{npcID=56433,x=0.66,y=0.794,zoneID=5785}},coords={x=0.658,y=0.792,source="quest_giver",zoneID=5785},questType="standard"},
[29899] = {id=29899,name="Rest in Peace",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="The spirits... the cavedwellers... they howl in agony... Trapped... in this world... cannot move... to the next. I... will go mad... listening... to their cries... Please...go...put them to rest.",starts={{npcID=56432,x=0.66,y=0.792,zoneID=5785}},ends={{npcID=56432,x=0.66,y=0.792,zoneID=5785}},coords={x=0.66,y=0.792,source="quest_giver",zoneID=5785},questType="standard"},
[29900] = {id=29900,name="An Ancient Legend",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="My father has dedicated his life to studying the Vale of Eternal Blossoms. The Vale is a mythical place, sealed after the Pandaren revolution twelve thousand years ago. We know so little about it! My father followed a trail of clues to the cave down the hill, seeking a very old poem known as the Song of the Vale , but he is in no condition to retrieve it. It is guarded by some sort of ancestor spirit. If you are heading that way anyway, would you mind bringing it back to him?",starts={{npcID=56433,x=0.66,y=0.794,zoneID=5785}},ends={{npcID=56432,x=0.66,y=0.792,zoneID=5785}},coords={x=0.66,y=0.794,source="quest_giver",zoneID=5785},questType="standard"},
[29901] = {id=29901,name="Anduin's Decision",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="You have done all you can for the Prince's friends. You completed your mission and found the White Pawn - Prince Anduin. Admiral Taylor and the other SI:7 agents will be eager to have the boy safe in their custody. It is time to return home.",ends={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},questType="standard"},
[29903] = {id=29903,name="A Perfect Match",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Elder Lusshan and I agree that the best path forward will be to work together. We will share with the Pearlfin our superior military knowledge and weaponry. In return, they will be a powerful ally should we again encounter the Horde. Take this crate of equipment and weapons. I need you to go around the village and equip the jinyu with weapons befitting their skills.",starts={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29904] = {id=29904,name="Bigger Fish to Fry",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="I've prepared a team of bright young Pearlfin trainees who need field experience. Take them northeast, into the Bamboo Wilds, and kill any wildlife that you find. Don't bring them back until they're fit for battle.",starts={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29905] = {id=29905,name="Let Them Burn",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Advance scouts report that the hozen at the Slingtail Pits are amassing with reinforcements from their tribes to the north. Our forces are gathered for battle on the ridge to the northwest. They are just waiting for you. Now is the time to show them what we are made of. Now is the time to destroy them indefinitely.",starts={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=54960,x=0.58,y=0.806,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29906] = {id=29906,name="Carp Diem",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Despite the hozen's apparent disarray, there is an order to their chaos. Their leader, Chief Gukgut , is the shrewd mastermind behind their attacks. He is organizing their movements at the great pit at the hozen camp to the northwest. Strike now and show him no mercy, , for he will do the same.",starts={{npcID=60970,x=0.588,y=0.816,zoneID=5785}},ends={{npcID=54960,x=0.58,y=0.806,zoneID=5785}},coords={x=0.588,y=0.816,source="quest_giver",zoneID=5785},questType="standard"},
[29907] = {id=29907,name="Chen and Li Li",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="My niece and I are new to Pandaria. Probably like yourself. We're visitors from the Wandering Isle, and, to be honest, we have no idea where we're going. That farm up ahead looks as fine a place as any to take off our shoes and enjoy a brew. What do you say, Li Li ? ? Would you like to share the road with us?",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29908] = {id=29908,name="A Seemingly Endless Nuisance",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5785,description="I apologize for the state of things around here. The virmen - those rabbity creatures, down the hill - have been pushing further and further into my family's farm, and our crops - which are normally bigger, and more delicious, by the way - have been suffering because of it. I'm no soldier... but you might be! Would you mind pushing some of these virmen off of our land?",starts={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},ends={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},coords={x=0.836,y=0.21,source="quest_giver",zoneID=5805},questType="standard"},
[29909] = {id=29909,name="Low Turnip Turnout",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Your help here is appreciated, . I'd like to give you another job, if you're interested. My son, Ang, runs the small farm just down this hill. He should have brought me some fruits and vegetables this morning, but I haven't seen him all day. Would you go down there and see what's going on?",starts={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},ends={{npcID=56207,x=0.816,y=0.252,zoneID=5805}},coords={x=0.836,y=0.21,source="quest_giver",zoneID=5805},questType="standard"},
[29910] = {id=29910,name="Rampaging Rodents",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I went off this morning to watch my papa fight the virmen. When I came back, the farm was full of marmots! I don't want to kill them, but we need to get rid of them. Hey, I know! We can close the holes! Fill in their holes with dirt, so they can't come out in our farm anymore.",starts={{npcID=56465,x=0.826,y=0.256,zoneID=5805}},ends={{npcID=56465,x=0.826,y=0.256,zoneID=5805}},coords={x=0.826,y=0.256,source="quest_giver",zoneID=5805},questType="standard"},
[29911] = {id=29911,name="Practically Perfect Produce",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Here, . My father will be wanting this. Thank you, again, for helping with the virmen.",starts={{npcID=56207,x=0.816,y=0.252,zoneID=5805}},ends={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},coords={x=0.816,y=0.252,source="quest_giver",zoneID=5805},questType="standard"},
[29912] = {id=29912,name="The Fabulous Miss Fanny",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Most of these vegetables will be sold, but I'd like to keep some for my family. Specifically, my nephew Liang needs some to feed to his pigs. Unfortunately, the pathway to Liang's farm is currently swarming with Snagtooth virmen. We're going to have to ask Miss Fanny to help us out. Bring some of the food we've gathered to Miss Fanny, who stands next to my house. Then ask her - NICELY! - to send them down to Liang's ranch.",starts={{npcID=56204,x=0.836,y=0.21,zoneID=5805}},ends={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},coords={x=0.836,y=0.21,source="quest_giver",zoneID=5805},questType="standard"},
[29913] = {id=29913,name="The Meat They'll Eat",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I told you earlier, my pigs are picky eaters. They need to eat meat to grow strong, but they don't like mutton, they don't like yak, and I'm not about to feed them any pig meat. They do, however, eat meat off of the mushan beasts, and they're also quite partial to turtle. Both creatures can be found in abundance to the west. My skills as a hunter are admittedly quite weak. Can you help out a young rancher and his pigs?",starts={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},ends={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},coords={x=0.752,y=0.24,source="quest_giver",zoneID=5805},questType="standard"},
[29914] = {id=29914,name="Back to the Sty",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I try to keep an eye on my stock, but every once in a while some of them sneak away. With all the confusion these virmen are causing, I may have let my guard down for a few moments, and some of my pigs escaped. Care to look for them? I'd start by looking down the hill, to the west.",starts={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},ends={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},coords={x=0.752,y=0.24,source="quest_giver",zoneID=5805},questType="standard"},
[29915] = {id=29915,name="A Neighbor's Duty",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I'm not the only one having trouble with his stock, it seems. One of Francis' sheep has wandered over to my ranch, for the third time this week. I'm beginning to think he needs help tending to his flock. You should check up on him, neighbor. And bring this poor little thing with you.",starts={{npcID=56205,x=0.752,y=0.24,zoneID=5805}},ends={{npcID=56208,x=0.782,y=0.328,zoneID=5805}},coords={x=0.752,y=0.24,source="quest_giver",zoneID=5805},questType="standard"},
[29916] = {id=29916,name="Piercing Talons and Slavering Jaws",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="First the hawks came. You've probably seen some of them circling up above. The wolves came shortly after. I think they smelled my weakness. I'm not nearly as brave as Master Shang thought I was. The master will be quite cross with me if I don't do something about these beasts. Can... can you help, ?",starts={{npcID=56208,x=0.782,y=0.328,zoneID=5805}},ends={{npcID=56208,x=0.782,y=0.328,zoneID=5805}},coords={x=0.782,y=0.328,source="quest_giver",zoneID=5805},questType="standard"},
[29917] = {id=29917,name="Lupello",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've been thinking... the wolves might stop attacking if we kill their pack leader. We call him Lupello , and he patrols the opposite riverbank. Lupello yourself.>",starts={{npcID=56208,x=0.782,y=0.328,zoneID=5805}},ends={{npcID=56208,x=0.782,y=0.328,zoneID=5805}},coords={x=0.782,y=0.328,source="quest_giver",zoneID=5805},questType="standard"},
[29918] = {id=29918,name="A Lesson in Bravery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Francis, you need to show bravery! You have everything it takes to make a great shepherd, except the courage to face your fears! You, stranger. You helped the rest of my family. Francis is like a second son to me. Show my apprentice what it means to lack fear. Use this rope to lasso and defeat one of the great white hawks above us.",starts={{npcID=56312,x=0.782,y=0.328,zoneID=5805}},ends={{npcID=56312,x=0.782,y=0.328,zoneID=5805}},coords={x=0.782,y=0.328,source="quest_giver",zoneID=5805},questType="standard"},
[29919] = {id=29919,name="Great Minds Drink Alike",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Hello again, . What is this, the fourth time we've run into one another already? Say... my keg is quickly becoming quite empty. I've heard mention of a brewery to the southwest, and that's where we're headed. Care to join us?",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29920] = {id=29920,name="Getting Permission",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="My love, Lo, tried to get permission to marry me from the pandriarchs. Though they have passed beyond, their favor would carry a lot of weight. Thing is, they are spirits, and none of the gifts or tributes we brought impress them. To win their favor they claimed that either Lo or a champion must defeat them in single combat. Lo is a good man, but not a fighter. Would you be our champion?",starts={{npcID=56708,x=0.526,y=0.38,zoneID=5785}},ends={{npcID=55788,x=0.526,y=0.38,zoneID=5785}},coords={x=0.526,y=0.38,source="quest_giver",zoneID=5785},questType="standard"},
[29922] = {id=29922,name="In Search of Wisdom",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Lorewalker Cho came by and asked for you while you were gone. He needs your assistance urgently in the town of Dawn's Blossom to the north. For what reason, he did not say. Speak to Kitemaster Ut-Nam . He would be happy to send you there.",starts={{npcID=54960,x=0.58,y=0.806,zoneID=5785}},ends={{npcID=63577,x=0.468,y=0.46,zoneID=5785}},coords={x=0.58,y=0.806,source="quest_giver",zoneID=5785},questType="standard"},
[29924] = {id=29924,name="Kill Kher Shan",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Kher Shan is one big dooker. Grooked all my sons! Ick Ick, Nab Nab, Eet Eet, Bitty Bitty, and the others I can't remember. Wikket wanna help hozen? Go grook Kher Shan ! The dooker's over there. Nibi Nibi points to the east.>",starts={{npcID=56327,x=0.258,y=0.386,zoneID=5785}},coords={x=0.258,y=0.386,source="quest_giver",zoneID=5785},questType="standard"},
[29925] = {id=29925,name="All We Can Spare",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Alright, I called in every favor I could. Here's what we got. Cho must be on to something big! Lemme know when you're ready to go see him - I got a ride all prepared for ya.",starts={{npcID=56348,x=0.47,y=0.46,zoneID=5785}},ends={{npcID=56345,x=0.508,y=0.27,zoneID=5785}},coords={x=0.47,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29926] = {id=29926,name="Calamity Jade",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You ever seen a shale spider, ? Usually harmless, just creepin' around eatin' rocks, but they got a taste for jade like cubs on candy. The boys call 'em \"nibblers.\" A few days back, we tunneled into a huge nest of these critters. They spilled out into the mines and went crazy, chewed up damn near everything in sight - including some of the boys. You get in there and clear 'em out, and we got plenty of jade to spare. The quarry is directly west of here.",questType="standard"},
[29927] = {id=29927,name="Mann's Man",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Look, this ain't easy... I got another favor to ask. My idiot husband, Hao, is a shift lead down at the quarry. I told him not to go back, that it was too dangerous, but he's as stubborn as a hozen and twice as stupid. Says the boys need him around for \"moral support.\" What about my moral support?! What am I gonna do if that idiot dies?! Please... keep an eye out for him. Tell him to come home.",questType="standard"},
[29928] = {id=29928,name="I Have No Jade And I Must Scream",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Our whole jade supply line has fallen apart. The mines are a death trap, morale is historically low, and - as if that weren't bad enough - the mason's quarter has been overrun by wood sprites! Now even the plants are out to ruin me! You need jade so badly, you can follow the road southwest to the mason's quarter and get it from those glorified chopsticks yourself.",starts={{npcID=56346,x=0.508,y=0.27,zoneID=5785}},ends={{npcID=56346,x=0.508,y=0.27,zoneID=5785}},coords={x=0.508,y=0.27,source="quest_giver",zoneID=5785},questType="standard"},
[29929] = {id=29929,name="Trapped!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="HNNNGHHH!! Let me guess: my wife sent you? Imagine that, my delicate little snow lily all worried. Ha ha! She's always frettin' over me. Look--HNNGHH!!!--it'll take more than a little--HNNGGHHH!!--cave-in to keep ol' Hao down. Some o' the boys, on the other hand, are in trouble. Help 'em out if you find any, will ya? I'll be fine. Really.",questType="standard"},
[29930] = {id=29930,name="What's Mined Is Yours",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Aw'right, so you need jade, do ya? I'd say we owe you at least that - we got plenty in the quarry, and thanks to yer help we should be back on schedule in no time. I should probably get back to the wife, so let's you and me take this cart o' the good stuff straight to her. Now, I ain't never met no t'were too big for me to pull in a wagon. You climb on the back there and let ol' Hao do the legwork.",starts={{npcID=56467,x=0.462,y=0.294,zoneID=5785}},ends={{npcID=56346,x=0.508,y=0.27,zoneID=5785}},coords={x=0.462,y=0.294,source="quest_giver",zoneID=5785},questType="standard"},
[29931] = {id=29931,name="The Serpent's Heart",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You've done great here, kid. Thanks to you, we have quite a bit of extra jade, and I know just the someone who could use it. My friend Foreman Raike is running the great statue project at the Serpent's Heart. Bring a shipment of extra jade to him, and tell him his old friend Mann says hello. He'll be eagerly waiting your arrival.",starts={{npcID=56346,x=0.508,y=0.27,zoneID=5785}},ends={{npcID=59391,x=0.482,y=0.612,zoneID=5785}},coords={x=0.508,y=0.27,source="quest_giver",zoneID=5785},questType="standard"},
[29932] = {id=29932,name="The Temple of the Jade Serpent",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You've done us a huge favor here, traveler. Now that we have enough jade to complete the statue, we should send word of our progress to Yu'Lon, the Jade Serpent. When you arrive, speak to Elder Sage Wind-Yi outside the entrance to the Temple of the Jade Serpent. If you wish to speed your journey, speak to Kitemaster Shoku. I'm sure he can spare an extra kite for you.",starts={{npcID=59391,x=0.482,y=0.612,zoneID=5785}},ends={{npcID=56782,x=0.58,y=0.586,zoneID=5785}},coords={x=0.482,y=0.612,source="quest_giver",zoneID=5785},questType="standard"},
[29933] = {id=29933,name="The Bees' Knees",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="You really hozen friend, wikket? Let's see, hmm? Hozen at Grookin' Hill all outta slicky bait. Tigerflies' legs stay twitchy in water - make best bait! Bo Bo sick from stings. Wikket get bait and take to Grookin.",starts={{npcID=56351,x=0.258,y=0.38,zoneID=5785}},ends={{npcID=56336,x=0.28,y=0.47,zoneID=5785}},coords={x=0.258,y=0.38,source="quest_giver",zoneID=5785},questType="standard"},
[29934] = {id=29934,name="To Ravenholdt",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="If the egg is in Ravenholdt Manor, we can't risk torching it in an all-out assault. I'll need someone slippery to get in there and find out for sure. That's you, . Mostrasz will help you infiltrate the compound. Speak to him just outside and fly to Ravenholdt together. Good luck!",starts={{npcID=55488,x=0.29,y=0.25,zoneID=4922}},ends={{npcID=56375,x=0.678,y=0.452,zoneID=267}},coords={x=0.29,y=0.25,source="quest_giver",zoneID=4922},questType="standard"},
[29935] = {id=29935,name="Orders are Orders",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Hmm, maybe wikket not so bad after all! Other baldskins not nice to hozen. Hozen take this from bad wikkets! All wikket loot goes to Kah Kah - Chief's orders! Here, wikket. You take it. Kah Kah will want to meet new hozen friend. His camp south at Grookin Hill.",starts={{npcID=56313,x=0.262,y=0.372,zoneID=5785}},ends={{npcID=56336,x=0.28,y=0.47,zoneID=5785}},coords={x=0.262,y=0.372,source="quest_giver",zoneID=5785},questType="standard"},
[29936] = {id=29936,name="Instant Messaging",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Welcome, wikket! Me Kah Kah - chief of Grookin Hill hozen. Dook Ookem wanted to be chief, but good wikket grook him good - big gift to Kah Kah. Hozen has gift for good wikket too. Gift come from great crash. Hozen keep it safe for wikket.",starts={{npcID=56336,x=0.28,y=0.47,zoneID=5785}},ends={{npcID=56339,x=0.282,y=0.476,zoneID=5785}},coords={x=0.28,y=0.47,source="quest_giver",zoneID=5785},questType="standard"},
[29937] = {id=29937,name="Furious Fowl",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="So these guys like fish, huh? Well how about we finish what you started and make them LOVE us? I've still got some explosive powder from the wreck, just need something to attract the fish. Guts is sure to do the trick - never fails. I saw some birds flyin' around south of town. Well? Whatcha waitin' for?",starts={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},ends={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},coords={x=0.272,y=0.506,source="quest_giver",zoneID=5785},questType="standard"},
[29938] = {id=29938,name="Friends and Foes",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,mapID=371,description="These ookin' Jinyu grookin Kah Kah's nephews! Wikket once kill many hozen. Now wikket kill many jinyu.",questType="standard"},
[29939] = {id=29939,name="Boom Bait",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="There. I've plastered your bird guts over my explosives. I call 'em Gut Bombs , patent pending. Since you made friends with these fellas, how about you do the honors? Just light the fuse and throw 'em down by the shoreline!",starts={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},ends={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},coords={x=0.272,y=0.506,source="quest_giver",zoneID=5785},questType="standard"},
[29940] = {id=29940,name="Taking a Crop",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Alright, fine. I DON'T have everything under control here. I spent all morning fighting off virmen. I managed to clear them off of my property, but they got away with some of my crops. They took them down to the river, to the south. I have no idea what they're doing with them, but it's probably not eating them. If my father wants his delivery now, I'm going to need some help getting those crops back. Could you help me out?",starts={{npcID=56207,x=0.816,y=0.252,zoneID=5805}},ends={{npcID=56207,x=0.816,y=0.252,zoneID=5805}},coords={x=0.816,y=0.252,source="quest_giver",zoneID=5805},questType="standard"},
[29941] = {id=29941,name="Beyond the Horizon",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="I recognize all you've managed to do here, . My report to the Warchief will include an account of your deeds. But there's no time to rest! This land must be charted and prepared for Horde settlement. I've already selected an away team to do just that. Find them before they grow comfortable here. Inform them of their mission, and try to convince your new friends to send along one of their own to serve as a guide. You'll be staying here with me. We have preparations to make.",starts={{npcID=56339,x=0.282,y=0.476,zoneID=5785}},ends={{npcID=56339,x=0.282,y=0.476,zoneID=5785}},coords={x=0.282,y=0.476,source="quest_giver",zoneID=5785},questType="standard"},
[29942] = {id=29942,name="Silly Wikket, Slickies are for Hozen",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="You think hozen crazy, wikket? Wait til you see hozen with no slickies! Not enough slickies for hozen and wikkets. Snappers! Hozen hate them ookin' snappers. Wikkets can eat all the snappers! Eekle Eekle points to the south.>",starts={{npcID=56358,x=0.27,y=0.508,zoneID=5785}},ends={{npcID=56358,x=0.27,y=0.508,zoneID=5785}},coords={x=0.27,y=0.508,source="quest_giver",zoneID=5785},questType="standard"},
[29943] = {id=29943,name="Guerrillas in our Midst",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Prince Anduin Wrynn. The very son of our enemy's king! Fortune has smiled on the Horde once again, . But there's another side of this coin. We'd be naive to think the child was left alone. Any Alliance scum within sight of this land must be searching desperately for their precious princeling. You and I are going to scour the area and root out his would-be rescuers.",starts={{npcID=56339,x=0.282,y=0.476,zoneID=5785}},ends={{npcID=56339,x=0.282,y=0.476,zoneID=5785},{npcID=56490,x=0.297,y=0.501,zoneID=5785}},coords={x=0.282,y=0.476,source="quest_giver",zoneID=5785},questType="standard"},
[29944] = {id=29944,name="Leaders Among Breeders",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Before any kegs are tapped, we have work to do. These virmen are no different than the virmen on the Wandering Isle... a nuisance that breeds as fast as the rabbits they resemble. Sure, we could kill every last virmen we find, but what's the point in needless bloodshed? Let's just take out their alphas, and they'll slow down with their... reproduction.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29945] = {id=29945,name="Yellow and Red Make Orange",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Uncle Chen says we're going to help this guy out with his virmen problem. Fine by me! I LOVE messing with virmen. Here's the plan: we're going to paint some turnips orange, and then we'll try to convince the virmen that they're carrots. This can only end in comedy. I'll gather turnips. You find something that we can use to make edible orange paint.",starts={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},ends={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},coords={x=0.688,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[29946] = {id=29946,name="The Warren-Mother",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We've dealt with the alpha males. Now, the alpha female. Virmen aren't terribly selective when it comes to breeding, but most broods will still have a dominant mother figure. She's usually bigger, meaner, and tougher than anyone else in the brood. You know, I wouldn't mind testing my skills against a warren-mother. Mind if I fight alongside you?",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29947] = {id=29947,name="Crouching Carrot, Hidden Turnip",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Uncle Chen's still got his eye on me, which means I won't be wandering off any time soon. I guess it's up to you to take these turnips... I mean, \"carrots\"... into the Twisted Warren and deliver them for me. It should be pretty simple. Just toss the vegetables in front of virmen, then watch their reaction when they find out it's really a turnip!",starts={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},ends={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},coords={x=0.688,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[29948] = {id=29948,name="Thieves to the Core",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You and that Chen fellow are good people, helpin' out with the virmen like you are. I don't like to ask for favors, but I ain't gonna turn 'em away, either. While you're out there puttin' the hurt to those rabbit-men, you wouldn't mind keepin' an eye out for some bags o' hops, would ya? I'm pretty sure they lifted 'em last night. Probably usin' em for pillows, knowin' how they are.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[29949] = {id=29949,name="Legacy",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I'd say we've earned our reward. I can't wait to taste what Mudmug's been brewing.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29950] = {id=29950,name="Li Li's Day Off",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Uncle Chen asked me not to get into any fights while he was away... but that doesn't mean I can't go exploring. Finally, a chance to look around Pandaria without stopping every forty-seven steps for another rest! You want to come with me? I'll bet there's all kinds of cool places we can visit, not too far away from here.",starts={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},ends={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},coords={x=0.688,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[29951] = {id=29951,name="Muddy Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="While you're just hangin' around, I might as well get you involved in my whole beer-makin' \"process\". Ain't much of a process, really... I just mix all the stuff together and wait. You probably heard - I like to use the muddy water from the riverbanks, to the south. Would you mind fillin' up this flask with that water and bringin' it back? I'll start gettin' the hops and barley all ready.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[29952] = {id=29952,name="Broken Dreams",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5963,description="Yes, I found the Stormstout Brewery... although I didn't exactly get the warm reception I expected. Do you want to hear the story?",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[29966] = {id=29966,name="Burning Down the House",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Look, ! These Alliance dogs built a camp up on the ridge. Here, take my grog. Let's make a fire they can see from Stormwind! For the Horde!",starts={{npcID=56339,x=0.282,y=0.476,zoneID=5785},{npcID=56490,x=0.297,y=0.501,zoneID=5785}},ends={{npcID=56339,x=0.282,y=0.476,zoneID=5785}},coords={x=0.282,y=0.476,source="quest_giver",zoneID=5785},questType="standard"},
[29967] = {id=29967,name="Boom Goes the Doonamite!",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="It's an emergency! Looks like you stirred up a hornet's nest killin' all them fish-folk. They're conductin' a full-on counterattack on Grookin Hill! I was hopin' to get some R&D time, but we're gunna hafta put my methane-grenade theory to work right away! Meet me on the east side of the fort, and bring yer throwin' arm!",starts={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},ends={{npcID=56525,x=0.29,y=0.49,zoneID=5785}},coords={x=0.272,y=0.506,source="quest_giver",zoneID=5785},questType="standard"},
[29968] = {id=29968,name="Green-ish Energy",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="One word: Methane! We're going green. Clean burning, high availability, all natural, and will keep the druids off my back when we get back to our neck of the world. That, and I ran out of blasting powder... So, I need your help, . No, no, I wouldn't ask you to do the dirty work - especially not in front of the general. I'll collect these 'deposits' myself. You gather up some wood for an outhouse - I'm thinking long-term here!",starts={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},ends={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},coords={x=0.272,y=0.506,source="quest_giver",zoneID=5785},questType="standard"},
[29971] = {id=29971,name="The Scouts Return",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Hey, while you were out our scouts came back. And get this, they found some Alliance kid. You should probably go debrief them.",starts={{npcID=56406,x=0.272,y=0.506,zoneID=5785}},ends={{npcID=55647,x=0.286,y=0.474,zoneID=5785}},coords={x=0.272,y=0.506,source="quest_giver",zoneID=5785},questType="standard"},
[29981] = {id=29981,name="Stemming the Swarm",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I'm not from here. I've never even BEEN here before today. But even I can tell you that something's wrong. That wall over there was built to keep mantid off of pandaren lands. Now, the mantid are sending their winged scouts over the top, as if the wall wasn't even there! The only reason those spindly scouts aren't dying is because they're attacking farmers, not soldiers. They wouldn't stand a chance against someone like you.",starts={{npcID=56111,x=0.198,y=0.57,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.198,y=0.57,source="quest_giver",zoneID=5805},questType="standard"},
[29982] = {id=29982,name="Evacuation Orders",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="A few farmers remain in the fields... some perilously close to the crumbling wall. I don't want any farmers pretending to be heroes. We will take care of this mantid swarm, and then they can return to their homes. My Shado-Pan are too busy defending this town to organize evacuations. You want to prove yourself useful? Get those farmers out of harm's way.",starts={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.194,y=0.568,source="quest_giver",zoneID=5805},questType="standard"},
[29983] = {id=29983,name="The Hidden Master",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We should be able to handle the defense of Stoneplow from here on out. Lin here is searching for someone she calls \"The Hidden Master\". I believe I know who she's talking about, and I have a clue for you. Go north.",starts={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.194,y=0.568,source="quest_giver",zoneID=5805},questType="standard"},
[29984] = {id=29984,name="Unyielding Fists: Trial of Bamboo",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We will start with a test: The Trial of Bamboo. Your friend Lin failed this test. Follow me, and listen carefully to my instructions.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29985] = {id=29985,name="They Will Be Mist",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The mist in this forest is a constant nuisance - one which I'm glad to hand off to trainees like you. Strange creatures lurk in the mist between these trees, and they must constantly be pushed back. Consider this part of your training.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29986] = {id=29986,name="Fog Wards",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Trainee. Several wards surround us, hidden in the woods near my home. They are quite effective at dispersing the mist, but they require constant upkeep. You will find one to the north, one to the west, and one to the south. Find these wards and light them.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29987] = {id=29987,name="Unyielding Fists: Trial of Wood",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You have progressed in your training, I think. Come with me, and we will attempt the Trial of Wood.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29988] = {id=29988,name="A Taste For Eggs",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I can sense your anxiety, but you are not ready yet. Your training must continue before you perform the final test. As for your task... I need you to fetch me some eggs. Yes, eggs. The marshland atop the hills to the east is home to a number of birds, all of which are generally peaceful in nature. You should have no trouble gathering enough eggs to last me several weeks.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29989] = {id=29989,name="Unyielding Fists: Trial of Stone",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You have accomplished much in the short time you have been here, . I would not normally offer this test so soon... but I feel that you're ready. It is time you attempted the Trial of Stone.",starts={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},ends={{npcID=56714,x=0.182,y=0.312,zoneID=5805}},coords={x=0.182,y=0.312,source="quest_giver",zoneID=5805},questType="standard"},
[29990] = {id=29990,name="Training and Discipline",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I told myself that, if I ever made it here to the Hidden Master, I would learn everything I could from him. This is my chance, . I'm not going to let it slip away. Still, I fear that Stoneplow needs us. I left early, before we were able to push the mantid scouts back. I'd feel better if you would check in with the Watch Commander for me. Oh, and if you run into the others, maybe you should tell them where the Hidden Master is...",starts={{npcID=56111,x=0.198,y=0.57,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.198,y=0.57,source="quest_giver",zoneID=5805},questType="standard"},
[29992] = {id=29992,name="Tenderpaw By Name, Tender Paw By Reputation",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I'd like to go tell Xiao, Kang, and the others that I've found the hidden master, but now he won't let me leave! He says I have to pass that test of bamboo first. How'd you do that, by the way? It looks like, for the time being, I'm stuck here practicing my punches against this rock. And my knuckles are about to cave in. If you could gather some jademoon leaves, I could prepare an ointment and at least numb some of this pain.",starts={{npcID=56111,x=0.198,y=0.57,zoneID=5805}},ends={{npcID=56111,x=0.198,y=0.57,zoneID=5805}},coords={x=0.198,y=0.57,source="quest_giver",zoneID=5805},questType="standard"},
[29993] = {id=29993,name="Find the Boy",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Have you seen my son, Lo? He was here a moment ago and I told him we were leaving today. I'm sure he's off trying to woo that young Syra Goldendraft. That is the very reason we need to leave! No son of mine is going to run off with a Goldendraft! I'm going to search around here for them. I do keep catching those two sneaking off to the Arboretum. Any chance you could head out there and look for them?",starts={{npcID=59173,x=0.47,y=0.46,zoneID=5785}},ends={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},coords={x=0.47,y=0.46,source="quest_giver",zoneID=5785},questType="standard"},
[29995] = {id=29995,name="Shrine of the Dawn",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The \"children\" you seek are not actually children but grown pandaren, despite what their elders might claim. Their love will not be held in check by the feuds of their families. You will find both Syra and Lo at the Shrine of the Dawn, ever seeking an answer to their dilemma amongst the pandriarchs of old.",starts={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},ends={{npcID=56708,x=0.526,y=0.38,zoneID=5785}},coords={x=0.546,y=0.442,source="quest_giver",zoneID=5785},questType="standard"},
[29997] = {id=29997,name="The Scryer's Dilemma",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Since you were so helpful at the mines, would you be willing to help us with a small problem here at the temple? Wise Mari has been complaining recently of a disturbance in his temple. The water elementals have gotten quite playful recently, and made off with his ceremonial staff. If you could help him, I would be most grateful. I may even put in a word with the Jade Serpent for you. Just follow the path to the north.",starts={{npcID=56782,x=0.58,y=0.586,zoneID=5785}},ends={{npcID=56787,x=0.576,y=0.56,zoneID=5785}},coords={x=0.58,y=0.586,source="quest_giver",zoneID=5785},questType="standard"},
[29998] = {id=29998,name="The Librarian's Quandary",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Lorewalker Stonestep is in charge of the entire temple library. Lately, something has been troubling him and his work. With thousands of ancient tomes to be transcribed, I can't afford to have him distracted. Would you follow the path south to the library and see what ails him?",starts={{npcID=56782,x=0.58,y=0.586,zoneID=5785}},ends={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},coords={x=0.58,y=0.586,source="quest_giver",zoneID=5785},questType="standard"},
[29999] = {id=29999,name="The Rider's Bind",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Have you seen the young serpents in the training yard? The littles ones tend to be mischievous, and some of them ran off to play before the training session. The Mistress will get angry if she discovers they're missing. Would you go find them and bring them back to me? I don't want them to get into trouble. They like to play out in the open, so look for them in courtyards and around the spires.",starts={{npcID=56784,x=0.58,y=0.59,mapID=371}},ends={{npcID=56784,x=0.58,y=0.59,mapID=371}},coords={x=0.58,y=0.59,source="quest_giver",mapID=371},questType="standard"},
[30000] = {id=30000,name="The Jade Serpent",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="You came to deliver a message to the Jade Serpent, right? I guess it's time you met her.",starts={{npcID=56784,x=0.58,y=0.59,mapID=371}},ends={{npcID=57242,x=0.558,y=0.57,mapID=371}},coords={x=0.58,y=0.59,source="quest_giver",mapID=371},questType="standard"},
[30001] = {id=30001,name="Moth-Ridden",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Moths have infested the library. Moths! Any librarian worth his letters knows that moths are the most dangerous threat to paper, second only to bookworms. As it turns out, my assistants are a useless bunch of insect-fearing cowards. Please, you MUST help me get rid of the moths immediately! The works of a thousand pandaren storytellers depend on you!",starts={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},ends={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},coords={x=0.562,y=0.604,source="quest_giver",zoneID=5785},questType="standard"},
[30002] = {id=30002,name="Pages of History",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The worst possible thing has happened, . We. Have. Bookworms . This is a critical situation. All Bookworms in the library must be eradicated at once to prevent their spread. We must squash this problem, literally! Please examine the infested books in the library and squash any Bookworms that you find.",starts={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},ends={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},coords={x=0.562,y=0.604,source="quest_giver",zoneID=5785},questType="standard"},
[30003] = {id=30003,name="A Book By Its Cover",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[30004] = {id=30004,name="Everything In Its Place",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You have helped us more than you can ever imagine, . I do not know what I would do if our precious scrolls were ever to be lost. Please return to the Elder Sage Rain-Zhu and tell him that the library is in order.",starts={{npcID=56786,x=0.562,y=0.604,zoneID=5785}},ends={{npcID=56782,x=0.58,y=0.586,zoneID=5785}},coords={x=0.562,y=0.604,source="quest_giver",zoneID=5785},questType="standard"},
[30005] = {id=30005,name="Lighting Up the Sky",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Do you like fireworks, ? I love them! In older times we would set them off to frighten away demons, but I just like them because they're pretty! I think there are still some old launchers lying around the temple. Would you go set off some big fireworks for me? It would make me so happy!",starts={{npcID=56784,x=0.58,y=0.59,zoneID=5785}},ends={{npcID=56784,x=0.58,y=0.59,zoneID=5785}},coords={x=0.58,y=0.59,source="quest_giver",zoneID=5785},questType="standard"},
[30006] = {id=30006,name="The Darkness Around Us",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Despite our best efforts, the sha broke the seals around the main temple. If we cannot hold them back here, their darkness will spread to the rest of the Jade Forest . We need your help immediately. Kill any sha creatures that you see. They should not be difficult to find.",starts={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30011] = {id=30011,name="A New Vision",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Please tell the Elder Sage Rain-Zhu that I will begin my work at once.",starts={{npcID=56787,x=0.576,y=0.56,zoneID=5785}},ends={{npcID=56782,x=0.58,y=0.586,zoneID=5785}},coords={x=0.576,y=0.56,source="quest_giver",zoneID=5785},questType="standard"},
[30015] = {id=30015,name="Dawn's Blossom",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=5785,description="Blood and Thunder! My axe hungers! We won't return to Orgrimmar until every last Alliance is purged from this land. I will train these natives myself, if I have to. One way or another, this land will be made ready for Horde settlement. In the meantime, their chief gave me this to pass on to you - a map and a message in some fancy script. Do what you must, but be quick about it. War is brewing...",starts={{npcID=56339,x=0.282,y=0.476,zoneID=5785},{npcID=56490,x=0.297,y=0.501,zoneID=5785}},ends={{npcID=63577,x=0.468,y=0.46,zoneID=5785}},coords={x=0.282,y=0.476,source="quest_giver",zoneID=5785},questType="standard"},
[30027] = {id=30027,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need a weapon suited to your talents. Retrieve a staff from one of the weapon racks below, bring it to me, and show me that you know how to equip it properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30028] = {id=30028,name="Grain Recovery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Since you are heading south, can you try to recover some of the grain that these thieves made off with? We saw birds and sprites running off with entire bags of our best bulk stock into the fields east and south of here.",starts={{npcID=57211,x=0.526,y=0.628,zoneID=5805}},ends={{npcID=57211,x=0.526,y=0.628,zoneID=5805}},coords={x=0.526,y=0.628,source="quest_giver",zoneID=5805},questType="standard"},
[30029] = {id=30029,name="Wee Little Shenanigans",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="So... we bought some cheap grains in bulk. It turned out the grain was infested with sprites. I HATE sprites. With their wee beady eyes and constant smiling. I would like to resolve this quietly. Can I buy your services to discreetly eliminate some of these grain thieves?",starts={{npcID=57211,x=0.526,y=0.628,zoneID=5805}},ends={{npcID=57211,x=0.526,y=0.628,zoneID=5805}},coords={x=0.526,y=0.628,source="quest_giver",zoneID=5805},questType="standard"},
[30030] = {id=30030,name="Out of Sprite",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Just to be clear, what happened was an accident. What I did, I did for INDUSTRY! There was no way I could have known that a sprite invasion would happen at any time, or that one of them would try to eat my new \"Pan's Miracle Gro\" formula. Now not only do they have a big sprite leading them, but he's one angry beast. If I pay you, will you take him out?",starts={{npcID=57209,x=0.526,y=0.628,zoneID=5805}},ends={{npcID=57209,x=0.526,y=0.628,zoneID=5805}},coords={x=0.526,y=0.628,source="quest_giver",zoneID=5805},questType="standard"},
[30031] = {id=30031,name="Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life. You should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30032] = {id=30032,name="The Quest for Better Barley",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Looking for sweet grain? My father once mentioned a malted cave barley that sounds about right. If you are willing to brave the peril, there is an ancient cave at the base of the Winds' Edge south of here. There is even an old lift my father made when he would travel into the jungle. In the cave is a bush as old as my family. From that bush you can pluck a grain so sweet it will humble your senses. Just watch out for its guardians.",starts={{npcID=57211,x=0.526,y=0.628,zoneID=5805}},ends={{npcID=56138,x=0.688,y=0.432,zoneID=5805}},coords={x=0.526,y=0.628,source="quest_giver",zoneID=5805},questType="standard"},
[30033] = {id=30033,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need weapons suited to your talents. Retrieve a spellblade and a hand fan from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30034] = {id=30034,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need a weapon suited to your talents. Retrieve a crossbow from one of the weapon racks below, bring it to me, and show me that you know how to hold it properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30035] = {id=30035,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need weapons suited to your talents. Retrieve a mace and a book of prayers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30036] = {id=30036,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need weapons suited to your talents. Retrieve a pair of daggers from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30037] = {id=30037,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30038] = {id=30038,name="The Lesson of the Iron Bough",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="First, you will need weapons suited to your talents. Retrieve an axe and a shield from one of the weapon racks below, bring them to me, and show me that you know how to hold them properly.",starts={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},coords={x=0.66,y=0.228,source="quest_giver",zoneID=5736},questType="standard"},
[30039] = {id=30039,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Freshly arrived for your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30040] = {id=30040,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30041] = {id=30041,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30042] = {id=30042,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30043] = {id=30043,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30044] = {id=30044,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30045] = {id=30045,name="Much to Learn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5736,description="Fresh to your training, your first task is simple: Speak to Master Shang Xi .",ends={{npcID=53566,x=0.66,y=0.228,zoneID=5736}},questType="standard"},
[30046] = {id=30046,name="Chen's Resolution",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You know what? I don't have to take this. I'll show that Uncle Gao what it means to be a real brewer. I'll brew the best beer he's ever tasted, with ingredients I've never even used before. I'm Chen Stormstout , and I'm the best brewer alive.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[30047] = {id=30047,name="The Chen Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that. Let's get this grain back to him at Halfhill.",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30048] = {id=30048,name="Li Li and the Grain",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I'll let you in on my brewing plan, : I'm planning on making an Emperor Stout. Done right, it should be dark, roasty, and high in alcohol. I just realized... I never told my plans to Li Li . She'll have no idea what type of grain to bring back! Could you speak with her? I need her to bring back the sweetest malted grains she can find.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30049] = {id=30049,name="Doesn't Hold Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Would you mind checking in on Mudmug ? He may need some assistance bringing that water back. I'm sure he'll appreciate the help of a big, strong like yourself to help him shoulder the load.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56474,x=0.686,y=0.432,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30050] = {id=30050,name="Gardener Fran and the Watering Can",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You want me to just GIVE you some hops? Pfshh! This is the third time today some little like you has come up to me asking for food! You want food? Then you'd better work! Now go water my plants!",starts={{npcID=62377,x=0.482,y=0.334,zoneID=5805}},ends={{npcID=62377,x=0.482,y=0.334,zoneID=5805}},coords={x=0.482,y=0.334,source="quest_giver",zoneID=5805},questType="standard"},
[30051] = {id=30051,name="The Great Water Hunt",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Look at it, : the Gilded Fan. I heared lots of good things about the water they got here. Lots of bad things, too. No sayin' what kind of water Chen's gonna be needin', so what say we make him a little sampler platter? Come on, let's get movin'. We'll go scoop up some water together.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[30052] = {id=30052,name="Weed War",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You want some hops? I've got plenty in the shed out back. I'll gladly share some with you... if you'll help me weed my field. Now \"hop\" to it! Get it?",starts={{npcID=57385,x=0.386,y=0.516,zoneID=5805}},ends={{npcID=57385,x=0.386,y=0.516,zoneID=5805}},coords={x=0.386,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30053] = {id=30053,name="Hop Hunting",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="With Li Li fetching grain, and Mudmug handling our water, all we need is hops, and some good wood barrels. I'll handle the barrels... but I need you to gather the hops. I don't know much about the hops from this land, but I'm sure the nearby farmers have something worth brewing with. Go see what you can rustle up.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=57385,x=0.386,y=0.516,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30054] = {id=30054,name="Enough is Ookin' Enough",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Virmen, they bite too much. They bite Mung-Mung 's carrot. They bite Mung-Mung 's pumpkin. Mung-Mung try to shoo them away, and the dookers bite Mung-Mung 's tail and foot. Enough is ookin' enough. You fight way better than Mung-Mung does. Bring back their bitey teeth. Then we see who does the biting.",starts={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},ends={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},coords={x=0.442,y=0.342,source="quest_giver",zoneID=5805},questType="standard"},
[30055] = {id=30055,name="Stormstout's Hops",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="All three farmers have delivered their hops to Halfhill. Perhaps you should check in with Chen to make sure that he received them.",ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},questType="standard"},
[30056] = {id=30056,name="The Farmer's Daughter",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Brave , you could not have arrived at a better time. My daughter is missing! I've got a suspicion that the virmen took her down into that stinking little warren of theirs. I'm too old to fight virmen, and my farmhand is already exhausted from fighting them off all morning. Could you look for her?",starts={{npcID=62385,x=0.442,y=0.342,zoneID=5805}},ends={{npcID=57408,x=0.412,y=0.382,zoneID=5805}},coords={x=0.442,y=0.342,source="quest_giver",zoneID=5805},questType="standard"},
[30057] = {id=30057,name="Seeing Orange",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Those virmen... they make me do horrible, horrible, silly things. All involving carrots. I couldn't tell you how many carrots they threw at me. Let's not waste any more time. Get me out of here!",starts={{npcID=57408,x=0.412,y=0.382,zoneID=5805}},ends={{npcID=62385,x=0.442,y=0.342,zoneID=5805}},coords={x=0.412,y=0.382,source="quest_giver",zoneID=5805},questType="standard"},
[30058] = {id=30058,name="Mothallus!",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The esteemed Journeyman Chu would appear to have created a monster. It is silken death with wings. Mothallus . You have already faced its brood. Now we ask that you help us face the creature itself. Please, , venture into the pit and rifle the bait. This will bring the beast to you. Our mothfighters will assist you as you need, though silk tends to stick to them more than most so you may need to help them, should they become overwhelmed.",starts={{npcID=57407,x=0.636,y=0.584,zoneID=5805}},ends={{npcID=57407,x=0.636,y=0.584,zoneID=5805}},coords={x=0.636,y=0.584,source="quest_giver",zoneID=5805},questType="standard"},
[30059] = {id=30059,name="The Moth Rebellion",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Oh... oh good! A ! Could you help me? I created a strain of vile monsters during my experiments to improve silk output. The result was a full-scale moth rebellion. Can you use your iness and destroy some of these mutants?",starts={{npcID=57424,x=0.634,y=0.584,zoneID=5805}},ends={{npcID=57424,x=0.634,y=0.584,zoneID=5805}},coords={x=0.634,y=0.584,source="quest_giver",zoneID=5805},questType="standard"},
[30063] = {id=30063,name="Behind the Masks",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The sha may seem unstoppable, but this is not true. Their masks seem to be the source of their power. When a sha and its mask are separated, the creature's essence is banished back to its own realm. Bring me intact masks, for I wish to study them further. Do be careful. I'm sure the sha will not part with them easily.",starts={{npcID=57319,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57319,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30064] = {id=30064,name="Saving the Sutras",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="My adepts had to abandon their studies when the sha invasion began. Unfortunately, they left their books scattered around the temple grounds. These priceless works of knowledge must be saved! The sutras can be found near the Training Pit and the Adept's Ring to the northeast.",starts={{npcID=57319,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57319,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30065] = {id=30065,name="Arrows of Fortune",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Our war supplies grow low, but especially needed are additional arrows. Our serpent riders are skilled marksmen, but they can do little without ammunition. We need someone to brave the battlefields and retrieve any undamaged arrows to refill our stores. Every arrow you retrieve will be used wisely.",starts={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30066] = {id=30066,name="Hidden Power",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Our temple defenders have battled relentlessly for hours. No doubt they grow tired. I will give you mantras to deliver to our fighters. Do not be fooled by these pieces of paper. These ancient scriptures hold words of untold power.",starts={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30067] = {id=30067,name="The Shadow of Doubt",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="A terrible manifestation of the sha has appeared to the south. It is trying to destroy an ancient relic, the Bell of a Thousand Whispers. This bell has never been rung in the temple's history, for it is rumored to be an ancient instrument of power. Please go and defeat this demon where it stands! We must save this relic!",starts={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30068] = {id=30068,name="Flames of the Void",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Do you see the violent black and white flames erupting all around the temple? The greater our doubt, the stronger they rage. Unchecked, they will devour the entire temple. We have but one hope. Take flight on one of our war serpents. Fly it near the pure springs of water, and then douse the fires with water from the pools.",starts={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},ends={{npcID=57324,x=0.538,y=0.618,zoneID=5785}},coords={x=0.538,y=0.618,source="quest_giver",zoneID=5785},questType="standard"},
[30069] = {id=30069,name="No Plan Survives Contact with the Enemy",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Quickly and quietly; that's how SI:7 prefers to operate. That was the plan, at least. Rell Nightwind is already inside Garrosh'ar Point looking for signs of Anduin and Taylor, but it's getting hot in there and he needs support. Fight yer way through these dogs and find Rell!",starts={{npcID=54616,x=0.436,y=0.906,zoneID=5785}},ends={{npcID=54617,x=0.462,y=0.848,zoneID=5785}},coords={x=0.436,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[30070] = {id=30070,name="The Fall of Ga'trul",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=5785,description="Alright . We've taken enough jabs at this warlock army... now it's time to cut off the head. Ga'trul 's back there, in that big ol' temple ruin. Give him a good what-for, and the Horde will have lost its last stake here in Pandaria.",starts={{npcID=54616,x=0.436,y=0.906,zoneID=5785}},ends={{npcID=54617,x=0.462,y=0.848,zoneID=5785}},coords={x=0.436,y=0.906,source="quest_giver",zoneID=5785},questType="standard"},
[30072] = {id=30072,name="Where Silk Comes From",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Would you like to be a Silkmaster for a day? The first thing you'll need are fresh mulberry leaves . You can find them in our grove of mulberry bushes to the northwest. Next you will need to feed them to a hungry silkworm in our feeding pit to the west. And finally you should get some raw silk from our processing hut on the south side of our farm. Have fun!",starts={{npcID=57405,x=0.626,y=0.596,zoneID=5805}},ends={{npcID=57405,x=0.626,y=0.596,zoneID=5805}},coords={x=0.626,y=0.596,source="quest_giver",zoneID=5805},questType="standard"},
[30073] = {id=30073,name="The Emperor",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We have everything we need. It's time to start brewing. Pay attention, ... you might learn a thing or two.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[30074] = {id=30074,name="Knocking on the Door",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Now, onward to the Stormstout Brewery! It's high time that I was reunited with the rest of the Stormstouts... and what better way to reunite than over a few mugs of ale? You know where the brewery is, right? Just follow this road to the west. You can't miss it. Of course, you're free to share the road with us - we'll be leaving any moment now.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[30075] = {id=30075,name="Clear the Way",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Are you seeing this? Virmen, hozen, and water sprites... all pouring out of the brewery doors and windows! What the heck is going on in there!? There is another entrance, on the eastern side of the brewery. I'm going to run over there and try to figure out what's going on. In the meantime, see if you can't get rid of these creatures. There's nothing worse than a drunken hozen.",starts={{npcID=56133,x=0.86,y=0.22,mapID=376}},ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},coords={x=0.86,y=0.22,source="quest_giver",mapID=376},questType="standard"},
[30076] = {id=30076,name="The Fanciest Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I've heard lots of cockamamie rumors about this here brewery. I thought they were all false... until I saw that giant hozen. So, it got me thinkin', what if the other rumors are true? I heard this one rumor just the other day about some water sprites that run around inside the brewery, causin' a ruckus and whatnot. Their bodies are actually MADE OF WATER. I reckon a man could make some mighty fine beer with some fancy water like that. If you find any, could you bring me some?",starts={{npcID=56474,x=0.686,y=0.432,mapID=376}},ends={{npcID=56474,x=0.686,y=0.432,mapID=376}},coords={x=0.686,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30077] = {id=30077,name="Barrels, Man",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I can't believe that giant hozen! He's just throwing barrels everywhere! Barrels, man! It looks like he managed to get pretty much all the pandaren that were working out in front of the brewery. If I were you, I'd help some of them break out. Put some of those ridiculous muscles to use. We're headed over to the brewery's rear entrance, to the east. Meet you there!",starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30078] = {id=30078,name="Cleaning House",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5963,description="That's it, . I've had enough of this. If somebody doesn't do SOMETHING to take care of this brewery, we'll lose it forever. And there's far too much family history - and beer - in there to risk wasting. So... we're going to break in through the back door. You, Li Li, Mudmug, and me. It's gonna be a brawl in there. Let me know when you're ready.",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="standard"},
[30079] = {id=30079,name="What's Eating Zhu's Watch?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Pandaren always welcome travelers with open arms - and open kegs! But this town full of jerks! Everyone so busy sulking, they won't talk to Ken-Ken at all! Can you find someone in town who will talk to us? Maybe normal pandaren just hiding in the houses?",starts={{npcID=56115,x=0.762,y=0.07,mapID=418}},ends={{npcID=56115,x=0.762,y=0.07,mapID=418}},coords={x=0.762,y=0.07,source="quest_giver",mapID=418},questType="standard"},
[30080] = {id=30080,name="Finding Yi-Mo",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="My nephew, Yi-Mo, has always been sort of a downer. When this wave of despair hit the town, he took it harder than most. He sat around for days refusing to eat, just staring off into the horizon. Now he's wandered off toward the cliffs northeast of here, where the thunderbirds nest and hunt. Please, , will you look for him?",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=58376,x=0.812,y=0.068,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30081] = {id=30081,name="Materia Medica",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Alright, Ken-Ken pretty sure he knows what wrong with pandaren! Got old, old hozen remedy that do the trick. Need to mix honey, fish oil, and salt. Ken-Ken saw lots of beehives in the trees around town, and there must be fish left in the dry ponds. That just leave salt... Mei might know where we can find some.",starts={{npcID=56115,x=0.762,y=0.07,mapID=418}},ends={{npcID=56115,x=0.762,y=0.07,mapID=418}},coords={x=0.762,y=0.07,source="quest_giver",mapID=418},questType="standard"},
[30082] = {id=30082,name="Cheer Up, Yi-Mo",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Ever since this storm began, I've just been... tired. Not physically... no. It's like my very soul is exhausted. Worthless. Hopeless. I imagine it's what one feels when a mate leaves them for someone with a rounder belly, but I've never had a mate so how would I know? How can I claim to know anything? I'm worthless to everyone but these thunderbirds. At least they'll have a good meal out of me.",starts={{npcID=58376,x=0.812,y=0.068,zoneID=6134}},ends={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},coords={x=0.812,y=0.068,source="quest_giver",zoneID=6134},questType="standard"},
[30083] = {id=30083,name="Securing the Province",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="With our grip on the province loosening, saurok from the wilds have already moved in to the cave just north of town. Most of our hunters are face-down in their own tears, so the saurok just walk in here like they own the place and grab whatever they want! I want to send a message that Zhu's Watch is not to be crossed. Will you be my messenger?",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30084] = {id=30084,name="Borderlands",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Bonfires are surprisingly effective at discouraging beasts from wandering out of the wilds. We have three along the border to the southwest which we normally keep lit at all times. Nobody's been there for days, though, and the fires must be out by now. It's only a matter of time before the wilds creep back in and overtake the land we have kept safe for centuries. Please, re-ignite the bonfires. They are critical in keeping the province safe, and they are memorials to the founders of our way of life.",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30085] = {id=30085,name="Into the Brewery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5963,description="We need to find out what's going on inside that brewery, ! We may have cleared out some of the bigger pests, but I'm certain there's plenty more where they came from. Gather up a few of your friends, and meet me inside!",starts={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.86,y=0.22,source="quest_giver",zoneID=5805},questType="dungeon"},
[30086] = {id=30086,name="The Search for the Hidden Master",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I are trying to decide something. We can talk again afterwards.",starts={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},ends={{npcID=56110,x=0.84,y=0.212,zoneID=5805}},coords={x=0.84,y=0.212,source="quest_giver",zoneID=5805},questType="standard"},
[30087] = {id=30087,name="FLAG - Kung Fu Intro",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,description="Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you. Now if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.",questType="standard"},
[30088] = {id=30088,name="Why So Serious?",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Okay, so that not work. Well... it cheer Ken-Ken up! But pandaren still sad... We try another old hozen remedy - this time, we go back even further than gramma, way WAY back to ancient times. Hozen still do this sometimes... mostly at parties. Ken-Ken got woodworking to do - you bring him teeth! Not yours; big ones, like a panther would have! Oh, and some paint! Mei might know where to find.",starts={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},ends={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},coords={x=0.762,y=0.07,source="quest_giver",zoneID=6134},questType="standard"},
[30089] = {id=30089,name="Apply Directly to the Forehead",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Well... THAT was unexpected! Come to think of it, now Ken-Ken remember why hozen use mask in the first place... A legend about the Monkey King says he used a mask to cure old pandaren emperor, Shaohao, when he was too sad to lead his people. Then they buried mask--with all his sadness--in the ground. We should use the mask on more pandaren, but instead of putting sad away in ground, we gonna PUNCH ITS BUTT. Let's do this, !",starts={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},ends={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},coords={x=0.762,y=0.07,source="quest_giver",zoneID=6134},questType="standard"},
[30090] = {id=30090,name="Zhu's Despair",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Hmm... Is that Yi-Mo kid over there? Ken-Ken squints against the increasing torrents of rain.> It is! He's at the well, and he's not lookin' so good. Ken-Ken got a bad feeling about this...",starts={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},ends={{npcID=56115,x=0.762,y=0.07,zoneID=6134}},coords={x=0.762,y=0.07,source="quest_giver",zoneID=6134},questType="standard"},
[30091] = {id=30091,name="Tears of Pandaria",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="All of this started with our ponds. In a single day, all of the water retreated down into the earth. When there was no more water in the ponds, it began to fall from the sky. Despite endless torrents of rain, the ponds do not fill. It's as if the land itself thirsts and cannot be quenched. Now the ponds birth horrific manifestations of despair. Elementals made of water from the sky and salt from the earth; the tears of Pandaria.",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30092] = {id=30092,name="Our Man in Gilneas",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=4706,description="If you wish to join my cause and slaughter the black dragons in hiding, prove yourself by taking down Hiram Creed. He's amassing an army in Gilneas. We haven't been able to slip past his defenders, but we've got a man on the scene keeping an eye on him. Zazzo Twinklefingers , a very crafty arcane mage, is waiting for us to contact him just outside of the ruins of the Gilnean capital. Find him and he'll direct you to the target.",starts={{npcID=57777,x=0.714,y=0.456,zoneID=267}},ends={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},coords={x=0.714,y=0.456,source="quest_giver",zoneID=267},questType="standard"},
[30093] = {id=30093,name="Assassinate Creed",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=4706,description="The city has been in chaos for days now. Hiram Creed, disguised as a Gilnean, has infected the lot of those dogs with his own draconic blood. Even the Forsaken are having trouble routing him out. Only a surgical assassination can end this! The bridge behind me is relatively unguarded. Slip in through merchant's square and head south - you'll find Creed in the middle of the military district. I'll keep an eye on you and pull you out if there's any trouble. ...There WILL be trouble!",starts={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},ends={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},coords={x=0.526,y=0.776,source="quest_giver",zoneID=41},questType="standard"},
[30094] = {id=30094,name="The End Time",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5789,description="Nozdormu , the bronze Aspect, has asked for help from the champions of the Horde. You are on his short list. I can share few other details. It is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself. He awaits you at the End Time , in the distant future. I can help you to travel there, if you so choose.",starts={{npcID=52382,x=0.488,y=0.704,zoneID=1637}},ends={{npcID=54476,x=0.796,y=0.45,zoneID=5789}},coords={x=0.488,y=0.704,source="quest_giver",zoneID=1637},questType="dungeon"},
[30095] = {id=30095,name="The End Time",level=35,requiredLevel=35,faction="alliance",expansion=4,zoneID=5789,description="Nozdormu , the bronze Aspect, has asked for help from the champions of the Alliance. You are on his short list. I can share few other details. It is uncharacteristic of my master to request the assistance of mortals, but I suppose that all things change with time... even the Aspect of Time himself. He awaits you at the End Time , in the distant future. I can help you to travel there, if you so choose.",starts={{npcID=52408,x=0.494,y=0.874,zoneID=1519}},ends={{npcID=54476,x=0.796,y=0.45,zoneID=5789}},coords={x=0.494,y=0.874,source="quest_giver",zoneID=1519},questType="dungeon"},
[30096] = {id=30096,name="Murozond",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5789,description="If we are to destroy Deathwing, we will need the power of the Dragon Soul. To obtain the Dragon Soul, I would have to take you back to the Sundering, ten thousand years in the past... but that time passage is blocked to me. The creature that blocks us from accessing this time passage is named Murozond . He must be slain, here, in this twisted future, before we can continue our plot to unmake Deathwing. This is why you were brought here, .",questType="dungeon"},
[30097] = {id=30097,name="Archival Purposes",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5789,description="From what I understand, you intend to avoid this future. If this is true, then we must archive data from this timestrand before it is lost to us. We believe that the most interesting and valuable elements of this future are the powerful \"echoes\" that roam the dragonshrines. Take this vessel with you as you silence these echoes. A portion of their energies will be archived within the bronze dragonflight's depository.",starts={{npcID=57864,x=0.262,y=0.632,zoneID=5788},{npcID=57864,x=0.796,y=0.45,zoneID=5789}},ends={{npcID=57864,x=0.262,y=0.632,zoneID=5788},{npcID=57864,x=0.796,y=0.45,zoneID=5789}},coords={x=0.262,y=0.632,source="quest_giver",zoneID=5788},questType="dungeon"},
[30098] = {id=30098,name="The Well of Eternity",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5788,description="We must move quickly, before any remaining Infinite agents intervene. Time is precious. I will now take you from your distant future into your distant past... the War of the Ancients. Our goal is the Dragon Soul, an artifact of immense power... enough power to break Deathwing, and end his reign over your present.",ends={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},questType="dungeon"},
[30099] = {id=30099,name="In Unending Numbers",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5788,description="Between us and the Dragon Soul lies a legion of demons. They will have to be dispatched before we proceed. If my timing is correct - and it usually is - a young night elf named Illidan Stormrage should be crossing our path shortly. He will undoubtedly be of some use when it comes to demon hunting. Help Illidan disable the demons' portals, then slay their leader, Peroth'arn .",starts={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},ends={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},coords={x=0.274,y=0.64,source="quest_giver",zoneID=5788},questType="dungeon"},
[30100] = {id=30100,name="The Vainglorious",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5788,description="Queen Azshara and her royal guard lie ahead of us. We cannot afford the possibility of any interference with our plan. So we will take the fight to her, before she has a chance to meddle. It is quite unlikely that you will kill Queen Azshara today; very few coherent timelines exist along that branch. Consider it a victory if you are simply able to occupy her attention, however temporarily.",starts={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},ends={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},coords={x=0.274,y=0.64,source="quest_giver",zoneID=5788},questType="dungeon"},
[30101] = {id=30101,name="The Path to the Dragon Soul",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5788,description="I cannot simply fly up and grab the Dragon Soul. The old gods protect it. To make matters worse, their shield is strengthened by the swirling, arcane energies that emanate from the Well of Eternity , and those energies are being focused by the great demon Mannoroth . Distract Mannoroth , and the link between the Dragon Soul and the Well will be broken. Without the Well's power, the old gods' ward will be weakened, and the Dragon Soul will be vulnerable. And then I will take it.",starts={{npcID=55624,x=0.274,y=0.64,zoneID=5788}},ends={{npcID=55532,x=0.82,y=0.576,zoneID=5788}},coords={x=0.274,y=0.64,source="quest_giver",zoneID=5788},questType="dungeon"},
[30102] = {id=30102,name="The Hour of Twilight",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5844,description="There's no need to stand around here forever. Have you forgotten? We can CONTROL TIME. Especially since you got rid of that Murozond fellow, back in the future. That Dragon Soul that you just liberated? Thrall already has it, back in your present day. And he's going to need your help. You ready to go?",starts={{npcID=57913,x=0.872,y=0.496,zoneID=5788}},ends={{npcID=54548,x=0.486,y=0.196,zoneID=5844},{npcID=54972,x=0.438,y=0.452,zoneID=5844},{npcID=55779,x=0.536,y=0.228,zoneID=5844}},coords={x=0.872,y=0.496,source="quest_giver",zoneID=5788},questType="dungeon"},
[30103] = {id=30103,name="To Wyrmrest!",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5844,description="The Dragon Soul... a weapon with enough power to defeat Deathwing. Thanks to you, it is now safely in our hands. Come! The aspects await us. We must bring the Dragon Soul to Wyrmrest Temple, in the center of Dragonblight.",starts={{npcID=54548,x=0.486,y=0.196,zoneID=5844},{npcID=54634,x=0.494,y=0.682,zoneID=5844},{npcID=54972,x=0.438,y=0.452,zoneID=5844},{npcID=55779,x=0.536,y=0.228,zoneID=5844}},ends={{npcID=54548,x=0.486,y=0.196,zoneID=5844},{npcID=54971,x=0.498,y=0.87,zoneID=5844},{npcID=54971,zoneID=5844}},coords={x=0.486,y=0.196,source="quest_giver",zoneID=5844},questType="dungeon"},
[30104] = {id=30104,name="Documenting the Timeways",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5789,description="You... , was it? You assisted with our archival in the past. Well, technically it was the future, but I believe you understand. Time is highly relative. I require more information for our archive. While you and Nozdormu don't intend to overwrite this timestrand, as you did in the End Time, we can still benefit from more data. I require information on Captain Varo'then, one of Azshara's pretty little handmaidens, and... hmm... oh, how about that big felguard, just down those stairs?",starts={{npcID=57864,x=0.262,y=0.632,zoneID=5788},{npcID=57864,x=0.796,y=0.45,zoneID=5789}},ends={{npcID=57864,x=0.262,y=0.632,zoneID=5788},{npcID=57864,x=0.796,y=0.45,zoneID=5789}},coords={x=0.262,y=0.632,source="quest_giver",zoneID=5788},questType="dungeon"},
[30105] = {id=30105,name="The Twilight Prophet",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5844,description="The missive reads as follows: \"The Hour of Twilight is upon us. The world-shaman Thrall approaches Wyrmrest with the Dragon Soul in hand, feebly whimpering one final threat to destroy our glorious master.\" \"Stop Thrall , and we win our war. I will be watching you from nearby.\" ~ The Twilight Prophet",ends={{npcID=54548,x=0.486,y=0.196,zoneID=5844},{npcID=54971,x=0.498,y=0.87,zoneID=5844},{npcID=54971,zoneID=5844}},questType="dungeon"},
[30106] = {id=30106,name="The Deed is Done",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="Prince Wrathion will be pleased to hear that you've succeeded. You should report back to him at Ravenholdt Manor. The Prince has been known to be extremely generous to those who help him.",starts={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},ends={{npcID=57777,x=0.714,y=0.456,zoneID=267}},coords={x=0.526,y=0.776,source="quest_giver",zoneID=41},questType="standard"},
[30107] = {id=30107,name="Cluster Clutch",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="The daggers I have given you are lifeless shells. They can do great things, once they are given a means to contain the power I have in mind. I need for you to acquire Shadowy Gems for me. The facets of these unusual stones are like windows into the infinite. They are often used by minions of the Twilight's Hammer to control the most powerful of elementals. A great battle is raging around Wyrmrest Temple. Collect Elementium Gem Clusters from Deathwing's minions and bring the gems to me.",starts={{npcID=57777,x=0.714,y=0.456,zoneID=267}},ends={{npcID=57777,x=0.714,y=0.456,zoneID=267}},coords={x=0.714,y=0.456,source="quest_giver",zoneID=267},questType="standard"},
[30108] = {id=30108,name="Our Man in Karazhan",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=4706,description="Your next target is the Black Dragon Nalice, who is engaged in some sort of arcane debauchery beneath the ruined tower of Karazhan. Your primary mission is to destroy her, but if you can bring me back a vial of her blood, I'll be able to use it to augment the power of the daggers I've given you. Your accomplice Zazzo has already been dispatched to the scene and awaits you there. He'll have more details.",starts={{npcID=57777,x=0.714,y=0.456,zoneID=267}},ends={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},coords={x=0.714,y=0.456,source="quest_giver",zoneID=267},questType="standard"},
[30109] = {id=30109,name="Blood of the Betrayer",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=4706,description="I've pinpointed Nalice to the Master's Cellar, an extended basement you'll find in the ruins up ahead. Dragon cultists are everywhere, and Nalice has set up some strange arcane storage devices throughout the area. Perhaps you can use those to your advantage? Sneak past the cultists, obliterate Nalice, and grab a vial of her blood for Wrathion. I'll keep my eyes on you and pull you out if you get into any trouble. But I'm NOT coming in there with you!",starts={{npcID=57770,x=0.7,y=0.408,zoneID=4706}},ends={{npcID=57770,x=0.7,y=0.408,zoneID=4706}},coords={x=0.7,y=0.408,source="quest_giver",zoneID=4706},questType="standard"},
[30110] = {id=30110,name="LFGDungeons - Cataclysm - Raid Finder - 1st",level=35,requiredLevel=35,faction="none",expansion=4,questType="standard"},
[30112] = {id=30112,name="A Score to Settle",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=206,description="Utgarde's forces are organizing under the advisory of Prince Keleseth , a san'layn ambassador of the Scourge. We cannot allow the vrykul to benefit from his counsel any further. Silence him.",questType="dungeon"},
[30113] = {id=30113,name="Victory in the Depths",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="Done! You'll want to get this back to Wrathion as soon as possible, along with those two daggers of yours. I don't know what he plans to do with this stuff. Between you and me, sometimes that little dragon kid creeps me out. Good luck!",starts={{npcID=57770,x=0.526,y=0.776,zoneID=41},{npcID=57770,x=0.7,y=0.408,zoneID=4706}},ends={{npcID=57777,x=0.714,y=0.456,zoneID=267}},coords={x=0.526,y=0.776,source="quest_giver",zoneID=41},questType="standard"},
[30116] = {id=30116,name="Sharpening Your Fangs",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="Do you understand why I have you assassinate the dragons, yet spare the mortals? It isn't their fault. They must seek out their own destiny, free from the meddling of my kind. We are nearing the end of our mission, and it is time for you to seek out your own destiny as well. I can continue to augment your weapons, but collecting shadowy gems won't be enough. My work will require entire clusters. Gather them from my father's minions...",starts={{npcID=57777,x=0.714,y=0.456,zoneID=267}},ends={{npcID=57777,x=0.714,y=0.456,zoneID=267}},coords={x=0.714,y=0.456,source="quest_giver",zoneID=267},questType="standard"},
[30117] = {id=30117,name="Stoneplow Thirsts",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Excuse me... ? Did I hear your name correctly? I've come from Stoneplow, in the west. They sent me to pick up some emergency beer rations, but the Stormstout Brewery is all boarded up! It looks like your handsome friend there - no, not Mudmug, the other one - has a few casks with him. Could you spare a keg for a town in need?",starts={{npcID=61026,x=0.362,y=0.684,zoneID=5805}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.362,y=0.684,source="quest_giver",zoneID=5805},questType="standard"},
[30118] = {id=30118,name="Patricide",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=267,description="Your next target has claimed the lives of all of my other assassins. I need you to kill my father himself. You must destroy Deathwing. We are out of time. His madness has already corrupted all the others of my kind, and his darkness will consume the world if he is not stopped. If you by some miracle succeed, and can retrieve for me a piece of him - perhaps a fragment of the armor he uses to disguise his true chaotic nature - the reward I give you will be without equal.",starts={{npcID=57777,x=0.714,y=0.456,zoneID=267}},ends={{npcID=58038,x=0.704,y=0.466,zoneID=267}},coords={x=0.714,y=0.456,source="quest_giver",zoneID=267},questType="standard"},
[30119] = {id=30119,name="Well of Eternity RP Tracker",level=5,requiredLevel=5,faction="both",expansion=4,zoneID=5788,description="I am duty-bound to look into your claims immediately, , which means my mission here now must fall to you. A surge of ancient magic, far too strong to have occurred naturally, drew me here. I have since discovered a most troubling development. A bough from Nordrassil has been ripped from the tree and taken deep into the Firelands. There, a powerful ritual threatens to corrupt Nordrassil, consuming it in flame. You must find a way to interrupt the ritual and reclaim the world tree's branch.",questType="raid"},
[30121] = {id=30121,name="Search Party",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="I sent a diplomat to look for allies in the ruins east of here. My diplomat has not returned and now Kang tells me this jungle is filled with a sinister people known as the mogu. Chezin is my friend and Leza's brother. To lose a brother would cause her to give in to despair. She already has enough to worry about with her fever. Could you investigate the ruins east of here and find out what happened?",starts={{npcID=58113,x=0.604,y=0.254,zoneID=6134}},ends={{npcID=58160,x=0.688,y=0.222,zoneID=6134}},coords={x=0.604,y=0.254,source="quest_giver",zoneID=6134},questType="standard"},
[30122] = {id=30122,name="Silver Filigree Flask",level=10,requiredLevel=10,faction="none",expansion=4,zoneID=6757,mapID=554,description="You have found a beautiful silver flask decorated with ornate filigree. With the right materials and your skill in alchemy, it could become quite magical.",questType="standard"},
[30123] = {id=30123,name="Skitterer Stew",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,description="Leza has a fever. No mother in labor should have a fever. Mama Bramblestaff once told me that Skitterer Stew could heal almost any illness. Let us put this knowledge to the test. Gather some intact skitterer glands for me while I get the herbs we'll need and I'll whip up a batch.",starts={{npcID=56112,x=0.6,y=0.25,zoneID=6134}},ends={{npcID=56112,x=0.6,y=0.25,zoneID=6134}},coords={x=0.6,y=0.25,source="quest_giver",zoneID=6134},questType="standard"},
[30124] = {id=30124,name="Blind Them!",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="These sunwalkers are a tiresome lot. I need soldiers with horde blood in their veins and honor in their hearts. Not some pacifist sun spirit filth. The Alliance are here, $p. Followed us no doubt, or somehow tracked the same visions Leza had that led us here. It doesn't matter. I don't want them to know how divided we are at the moment. Go kill their scout south of here before it can report back. Hellscream's eyes upon you.",starts={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},ends={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},coords={x=0.598,y=0.248,source="quest_giver",zoneID=6134},questType="standard"},
[30127] = {id=30127,name="Threat from Dojan",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Mogu? They seem like the elves, ancient and an over developed sense of entitlement. Everyone of Azeroth must learn, sooner or later, that the Horde is not \"visiting\" this world. We are here. We are staying. Teach them this lesson. Quell their numbers in the ruins south and west of here. Break their amassing forces before they decide to attack. Learn what you can of how these creatures fight, and how they die.",starts={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},ends={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},coords={x=0.598,y=0.248,source="quest_giver",zoneID=6134},questType="standard"},
[30128] = {id=30128,name="The Pools of Youth",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The mogu found the Pools of Youth! Mama Bramblestaff used to tell me old stories about those. During the mogu empire they would use the waters to extend life. Thing is those stories never ended well for some reason. As if the waters were cursed. Either way, we should investigate. There is a good chance those waters might help Leza. It looks like the Pools of Youth are on the northwestern side of the ruins.",ends={{npcID=58113,x=0.604,y=0.254,zoneID=6134}},questType="standard"},
[30129] = {id=30129,name="The Mogu Agenda",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Mogu don't often gather in numbers like this. We should find out what they are up to. I thought I heard someone shouting orders near the center of the ruins. We should probably see if he has information.",starts={{npcID=56112,x=0.6,y=0.25,zoneID=6134}},coords={x=0.6,y=0.25,source="quest_giver",zoneID=6134},questType="standard"},
[30130] = {id=30130,name="Herbal Remedies",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Kang's remedy isn't working. There is something else at work here. A power deep beneath the soil. It is sapping us of hope, hitting us with depression and despair. Kang tells me this land has lotus plants. I might be able to make a tea that would hopefully lend Leza some strength. Please, $p, search the ruins south and west of here for lotus leaves. I will pay you for your efforts.",starts={{npcID=58113,x=0.604,y=0.254,zoneID=6134}},ends={{npcID=58113,x=0.604,y=0.254,zoneID=6134}},coords={x=0.604,y=0.254,source="quest_giver",zoneID=6134},questType="standard"},
[30131] = {id=30131,name="Life",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="My child is coming. I must help as I may. Stay nearby, hero. If my wife and child survive, I would have them look on the face of the one who saved them.",starts={{npcID=58113,x=0.604,y=0.254,mapID=418}},ends={{npcID=58113,x=0.604,y=0.254,mapID=418}},coords={x=0.604,y=0.254,source="quest_giver",mapID=418},questType="standard"},
[30132] = {id=30132,name="Going West",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Leza now walks with the ancestors of this strange land. I must look now to the living. Kor has led a group of our scouts west deeper into the jungle. I sent a scout of my own to investigate the crane temple. Please, $p, seek out my scout, get their report, then meet up with Kor and lend what aid you can to him. We will join you as quickly as we are able.",starts={{npcID=58113,x=0.604,y=0.254,zoneID=6134}},ends={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},coords={x=0.604,y=0.254,source="quest_giver",zoneID=6134},questType="standard"},
[30133] = {id=30133,name="Into the Wilds",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. They should be told of what happened here. If you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone north. When you reach the temple, find Koro Mistwalker .",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=58547,x=0.442,y=0.43,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30135] = {id=30135,name="Beating the Odds",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="At first, the Slitherscale were too frightened to approach the wild serpents. Then, I caught them snatching the eggs under the cover of night. Now, they are slaughtering adults and hatchlings alike! If we do not do something, these gentle creatures will be completely wiped out. Then there won't even be an Order of the Cloud Serpent to join! Go and slay these vile Slitherscales, and then we will talk.",starts={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},ends={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},coords={x=0.654,y=0.316,source="quest_giver",zoneID=5785},questType="standard"},
[30136] = {id=30136,name="Empty Nests",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="When the attacks began, the young hatchlings scattered in terror. They are roaming around the island, lost and scared. If you want to help, take this rope and leash the lost little ones. Take them back to their nests. Return them home.",starts={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},ends={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},coords={x=0.654,y=0.316,source="quest_giver",zoneID=5785},questType="standard"},
[30137] = {id=30137,name="Egg Collection",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Ahhh, I should have known! You have the look of a hungry initiate. I would gladly help you choose a serpent egg , but the Slitherscale have thoroughly raided the cloud serpent nests. I'm terribly sorry. I don't know what to tell you. Unless you're crazy enough to sneak into the saurok camp to the east and retrieve some stolen cloud serpent eggs , I'm afraid I can't help you.",starts={{npcID=58225,x=0.654,y=0.316,mapID=371}},ends={{npcID=58225,x=0.654,y=0.316,mapID=371}},coords={x=0.654,y=0.316,source="quest_giver",mapID=371},questType="standard"},
[30138] = {id=30138,name="Choosing the One",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I have examined each egg, . Out of the lot that you brought me, I have chosen the three eggs with the most promise. You may choose only one egg to take with you. Are you ready to make your final selection?",starts={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},ends={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},coords={x=0.654,y=0.316,source="quest_giver",zoneID=5785},questType="standard"},
[30139] = {id=30139,name="The Rider's Journey",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.",starts={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},ends={{npcID=58228,x=0.574,y=0.45,zoneID=5785}},coords={x=0.654,y=0.316,source="quest_giver",zoneID=5785},questType="standard"},
[30140] = {id=30140,name="The Rider's Journey",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.",starts={{npcID=58225,x=0.654,y=0.316,zoneID=5785}},ends={{npcID=58228,x=0.574,y=0.45,zoneID=5785}},coords={x=0.654,y=0.316,source="quest_giver",zoneID=5785},questType="standard"},
[30141] = {id=30141,name="The Rider's Journey",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Excellent, just excellent! I will return the other eggs to their nests, undisturbed. In the meantime, deliver your egg to Instructor Skythorn at The Arboretum.",starts={{npcID=58225,x=0.654,y=0.316,mapID=371}},ends={{npcID=58228,x=0.574,y=0.45,mapID=371}},coords={x=0.654,y=0.316,source="quest_giver",mapID=371},questType="standard"},
[30142] = {id=30142,name="It's A...",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Oh my! This egg is going to hatch at any second! Well, looks like this little guy is eager to meet you. Are you ready?",starts={{npcID=58228,x=0.574,y=0.45,mapID=371}},ends={{npcID=58228,x=0.574,y=0.45,mapID=371}},coords={x=0.574,y=0.45,source="quest_giver",mapID=371},questType="standard"},
[30143] = {id=30143,name="They Grow Like Weeds",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Ahh, it is you again, . Instructor Windblade is looking for you. You can find her on the ridge to the east. She has some news about your cloud serpent.",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="standard"},
[30144] = {id=30144,name="Flight Training: Ring Round-Up",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Now that your serpent is fully grown, you are ready to begin flight training. As with all novices, you must start at the beginning. Your first task is simple. Fly through 6 of the cloud rings between the spires to the east.",starts={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},ends={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},coords={x=0.586,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[30145] = {id=30145,name="Flight Training: Full Speed Ahead",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The next task will be a little harder. Are you ready?",starts={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},ends={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},coords={x=0.586,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[30146] = {id=30146,name="Snack Time",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=13644,description="Cloud serpents love to eat, and one of their favorite treats is the sugar minnow . These fish can be found in salt or fresh water anywhere in Pandaria. I trust you have some skill in fishing, and your own fishing pole to catch them? Bring me a fresh catch and I'm sure the hungry beasts around here will be very grateful.",starts={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},ends={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},coords={x=0.574,y=0.446,source="quest_giver",zoneID=5785},questType="standard"},
[30147] = {id=30147,name="Fragments of the Past",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=9105,description="The Order of the Cloud Serpent's history stretches back thousands of years, and although we have tried to preserve the old ways, there are ancient techniques that have been lost over time. You can help us recover some of this knowledge by searching Pandaria's dig sites for clues to our past. Use your archaeology skill to survey around Pandaria and bring me whatever you find.",starts={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},ends={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},coords={x=0.574,y=0.446,source="quest_giver",zoneID=5785},questType="standard"},
[30148] = {id=30148,name="Just a Flesh Wound",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Many of the baby hatchlings at Windward Isle have been injured as a result of all the fighting. I have been told that you may be able to help them, with your access to powerful bandages. Please go northeast and use some of the best bandages you can acquire to save the injured hatchlings.",starts={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},ends={{npcID=58413,x=0.574,y=0.446,zoneID=5785}},coords={x=0.574,y=0.446,source="quest_giver",zoneID=5785},questType="standard"},
[30149] = {id=30149,name="A Feast for the Senses",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="I have heard that you know a thing or two about cooking. As it so happens, serpents love to eat Fish Cakes . If you use your culinary skills and bring me 5 of these dishes, the cloud serpents around here will be very happy.",starts={{npcID=58413,x=0.574,y=0.446,mapID=371}},ends={{npcID=58413,x=0.574,y=0.446,mapID=371}},coords={x=0.574,y=0.446,source="quest_giver",mapID=371},questType="standard"},
[30150] = {id=30150,name="Sweet as Honey",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="From the cloud serpent's behavior, you have a hunch that it wants a sweet treat. The fragrant trees in The Arboretum are home to many honey hives. It will be a simple matter to collect combs from the nearby honeykeepers.",starts={{npcID=58384,x=0.565,y=0.444,zoneID=5785},{npcID=65669,x=0.574,y=0.452,zoneID=5785},{npcID=65670,x=0.574,y=0.452,zoneID=5785},{npcID=65671,x=0.574,y=0.452,zoneID=5785}},ends={{npcID=58384,x=0.565,y=0.444,zoneID=5785},{npcID=65669,x=0.574,y=0.452,zoneID=5785},{npcID=65670,x=0.574,y=0.452,zoneID=5785},{npcID=65671,x=0.574,y=0.452,zoneID=5785},{npcID=65672,x=0.574,y=0.452,zoneID=5785},{npcID=65673,x=0.574,y=0.452,zoneID=5785},{npcID=65674,x=0.574,y=0.452,zoneID=5785}},coords={x=0.565,y=0.444,source="quest_giver",zoneID=5785},questType="standard"},
[30151] = {id=30151,name="Catch!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="You have a feeling the serpent is tired of being cooped up all day. How about playing a little game of catch?",starts={{npcID=65669,x=0.574,y=0.452,zoneID=5785},{npcID=65670,x=0.574,y=0.452,zoneID=5785},{npcID=65671,x=0.574,y=0.452,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.574,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[30152] = {id=30152,name="The Sky Race",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The time for the great race is upon us! Traverse the course among the spires and pass through the checkered flags on each of the 10 balloon checkpoints . Make sure to pass underneath the finish line when you are done. The competition will be fierce, but I wish you luck. Speak to me when you are ready to begin.",starts={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.586,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[30154] = {id=30154,name="The Easiest Way To A Serpent's Heart",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Uh-oh, looks like someone is in a bad mood today! Luckily, you know just the thing that will cheer up the little beast. Cloud serpents love the taste of tiger meat, but the tender flanks can be... challenging... to acquire. Luckily, you recall there are some fat, juicy tigers to the northeast, on Windward Isle. Sure, you might suffer some scratches and a little mauling, but it's all worth it for your serpent, right?",starts={{npcID=65669,x=0.574,y=0.452,zoneID=5785},{npcID=65670,x=0.574,y=0.452,zoneID=5785},{npcID=65671,x=0.574,y=0.452,zoneID=5785},{npcID=65672,x=0.574,y=0.452,zoneID=5785},{npcID=65673,x=0.574,y=0.452,zoneID=5785},{npcID=65674,x=0.574,y=0.452,zoneID=5785},{npcID=65679,x=0.574,y=0.452,zoneID=5785},{npcID=65723,x=0.574,y=0.452,zoneID=5785},{npcID=65724,x=0.574,y=0.452,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.574,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[30155] = {id=30155,name="Restoring the Balance",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="The situation at the islands remains dire, . The Slitherscale saurok have not responded to our attempts at peace, so only one option remains. In order to protect the wild cloud serpents, we must rid the island of their presence. Only then can the cloud serpents be left to live in peace.",starts={{npcID=58228,x=0.574,y=0.45,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.574,y=0.45,source="quest_giver",zoneID=5785},questType="standard"},
[30156] = {id=30156,name="Feeding Time",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Ouch! It seems, without a doubt, that the little beast is hungry. You recall that some meaty-looking turtles can be found on the wild cloud serpent island to the northeast. Perhaps some turtle meat will fill the hatchling's voracious appetite.",starts={{npcID=65669,x=0.574,y=0.452,zoneID=5785},{npcID=65670,x=0.574,y=0.452,zoneID=5785},{npcID=65671,x=0.574,y=0.452,zoneID=5785},{npcID=65672,x=0.574,y=0.452,zoneID=5785},{npcID=65673,x=0.574,y=0.452,zoneID=5785},{npcID=65674,x=0.574,y=0.452,zoneID=5785},{npcID=65724,x=0.574,y=0.452,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.574,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[30157] = {id=30157,name="Emptier Nests",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Oh, thank goodness, another cloud serpent trainer! I just received word that the wild hatchlings at Windward Isle to the northeast are in serious trouble! While the adults fight those terrible saurok, who is watching the cute little babies? No one, that's who! WE HAVE TO SAVE THEM! I'm sending every trainer I can find to go and help. If you aren't too busy, can you make sure the hatchlings are safely delivered back to their mothers' nests?",starts={{npcID=58510,x=0.584,y=0.446,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.584,y=0.446,source="quest_giver",zoneID=5785},questType="standard"},
[30158] = {id=30158,name="Disarming the Enemy",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="If we are to stop the poachers, we need to take more aggressive action. If we can remove the enemies' primary tools for killing and capturing serpents, we may be able to stop their operation altogether. I need you to go into their territory on the eastern end of Windward Isle and steal their weapons. A cat without claws cannot strike.",starts={{npcID=58228,x=0.574,y=0.45,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.574,y=0.45,source="quest_giver",zoneID=5785},questType="standard"},
[30159] = {id=30159,name="Preservation",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Oh no! We must stop them! , is it? The Order needs your help! Do you know what those horrible Slitherscale saurok are doing? They have the audacity to steal cloud serpent eggs straight from the matriarch's nests! While the cloud serpents become ever rarer, those brutes are... are... ...they're eat their eggs for dinner! It's horrible! Go to Windward Isle to the northeast and recover any unbroken eggs that you can. As students of the Order, it's our duty!",starts={{npcID=58510,x=0.584,y=0.446,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.584,y=0.446,source="quest_giver",zoneID=5785},questType="standard"},
[30160] = {id=30160,name="A Ruby Shard for Ella",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30163] = {id=30163,name="For the Tribe",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="We fell back to the refuge when the mogu attacked but lost a number of our people along the way. Travel west and north of here and look for any captives you can rescue that could help us in our fight. Leave any Alliance you find to their fate.",starts={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},ends={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},coords={x=0.598,y=0.248,source="quest_giver",zoneID=6134},questType="standard"},
[30164] = {id=30164,name="The Stoneplow Convoy",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="I tried to save as many of the Stoneplow envoys as I could but these \"mantid\" dragged many of them off into the jungle. These are civilians in need of our help. Please take the herbs you gathered earlier. I've infused them with what gifts of the Light are still granted me. Use them on as many of the Stoneplow envoys as you can.",starts={{npcID=58607,x=0.288,y=0.508,zoneID=6134}},ends={{npcID=58607,x=0.288,y=0.508,zoneID=6134}},coords={x=0.288,y=0.508,source="quest_giver",zoneID=6134},questType="standard"},
[30168] = {id=30168,name="Thieving Raiders",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Saurok! These vile creatures are obsessed with killing and stealing. They attacked our settlement without provocation or warning. Please, , can you aid us? Help us recover our lost possessions from these Riverblade raiders that march along the river and we will gladly reward you.",starts={{npcID=58278,x=0.296,y=0.39,zoneID=6134}},ends={{npcID=58278,x=0.296,y=0.39,zoneID=6134}},coords={x=0.296,y=0.39,source="quest_giver",zoneID=6134},questType="standard"},
[30169] = {id=30169,name="Raid Leader Slovan",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="The raiders are led by a particularly violent saurok known as Slovan . The Crane Temple usually comes to our aid when he attacks but now we find ourselves outmatched and outmaneuvered. Please, , aid us by destroying this raid leader. You can find him in his den behind the Krasari Falls.",starts={{npcID=58278,x=0.296,y=0.39,zoneID=6134}},ends={{npcID=58278,x=0.296,y=0.39,zoneID=6134}},coords={x=0.296,y=0.39,source="quest_giver",zoneID=6134},questType="standard"},
[30172] = {id=30172,name="Barreling Along",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="No, no, no, don't you worry about pickin' 'em up. I can hold these here barrels. I may not be the handsomest pandaren, or the smartest, or any fun to be around in the slightest, but I'm stronger than a mushan beast. I'mma just need you to lead the way.",starts={{npcID=56474,x=0.686,y=0.432,zoneID=5805}},ends={{npcID=56133,x=0.86,y=0.22,zoneID=5805}},coords={x=0.686,y=0.432,source="quest_giver",zoneID=5805},questType="standard"},
[30174] = {id=30174,name="For Family",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Kor should have caught up by now. He said he was going to secure the Ruins of Korja east of here and meet us to help with the mantid threat. He may need help against Groundbreaker Brojai . Could you assist him? Kang and I will follow shortly.",starts={{npcID=58607,x=0.288,y=0.508,zoneID=6134}},ends={{npcID=58607,x=0.288,y=0.508,zoneID=6134}},coords={x=0.288,y=0.508,source="quest_giver",zoneID=6134},questType="standard"},
[30175] = {id=30175,name="The Mantid",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,description="The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that. Now they are preparing to hit Stoneplow. Please, , destroy some of these beasts before they get sufficient numbers to flank our home. If my cousin, Ambassador Len , is still alive and at our convoy he should be able to reward you for your help.",starts={{npcID=58630,x=0.248,y=0.342,zoneID=6134}},ends={{npcID=58954,x=0.156,y=0.396,zoneID=6134}},coords={x=0.248,y=0.342,source="quest_giver",zoneID=6134},questType="standard"},
[30177] = {id=30177,name="Daily Heroic Random (1st) (Cataclysm)",level=5,requiredLevel=5,faction="both",expansion=4,questType="standard"},
[30178] = {id=30178,name="Into the Wilds",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Deep in the wilds, on the southern coast where the Krasarang River meets the sea, rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. They should be told of what happened here. If you're headed that way, I have a favor to ask; We often send supplies to the temple, but our last courier has not returned. Please look for signs of him as you travel - where the road forks at the Dojani River, he'd have gone south. When you reach the temple, find Koro Mistwalker .",starts={{npcID=57744,x=0.758,y=0.076,zoneID=6134}},ends={{npcID=58547,x=0.442,y=0.43,zoneID=6134}},coords={x=0.758,y=0.076,source="quest_giver",zoneID=6134},questType="standard"},
[30179] = {id=30179,name="Poisoned!",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="The... mogu. Do not trust. Poison. Get sample... sample blades. Bring to Dezco... in Thunder Cleft, west of here.",starts={{npcID=58160,x=0.688,y=0.222,mapID=418}},ends={{npcID=58113,x=0.604,y=0.254,mapID=418}},coords={x=0.688,y=0.222,source="quest_giver",mapID=418},questType="standard"},
[30181] = {id=30181,name="Mushan Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Mushan! Would ya look at the size o' 'em. Old as the dirt they walk on probably. A fine trophy. If you are lookin' to test your mettle as a big game hunter, start with them.",starts={{npcID=58422,x=0.16,y=0.826,zoneID=5805}},ends={{npcID=58422,x=0.16,y=0.826,zoneID=5805}},coords={x=0.16,y=0.826,source="quest_giver",zoneID=5805},questType="standard"},
[30182] = {id=30182,name="Fox Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="So, when I was scouting east of here I saw a collection of foxes. That's what I first learned to hunt when back on the Wandering Isle. If you want to see the challenge a young pandaren hunter faced when growing up, head east and face off against a bunch of foxes. They tend to be clever and cunning so be on your guard.",starts={{npcID=63822,x=0.162,y=0.824,zoneID=5805}},ends={{npcID=63822,x=0.162,y=0.824,zoneID=5805}},coords={x=0.162,y=0.824,source="quest_giver",zoneID=5805},questType="standard"},
[30183] = {id=30183,name="Stalker Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Tigers! No matter what land I go to I hear about these big fanged beasts. And yet I haven't had a chance to hunt any of them. Let's go hunt some tigers. I'll go east, you go west. I think I saw some near Dustback Gorge. I'm sure there are tons near those mushan.",starts={{npcID=63822,x=0.162,y=0.824,zoneID=5805}},ends={{npcID=63822,x=0.162,y=0.824,zoneID=5805}},coords={x=0.162,y=0.824,source="quest_giver",zoneID=5805},questType="standard"},
[30184] = {id=30184,name="Mushan Mastery: Darkhide",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="My boy here is a talented hunter... in training. Let's show him an old 'Nessy style hunt shall we? I saw a mighty big mushan east of here with a hide dark as night. It looked like it had taken down a number of hunters in its day. If you want a big game hunt, go try an' take it on.",starts={{npcID=58421,x=0.16,y=0.824,zoneID=5805}},ends={{npcID=58421,x=0.16,y=0.824,zoneID=5805}},coords={x=0.16,y=0.824,source="quest_giver",zoneID=5805},questType="standard"},
[30185] = {id=30185,name="Tortoise Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Granted, tortoises are not big game but they can be mean game. They also work as the perfect bait for bigger game! Gotcher found some ol' tablets sayin' that the Torjari Pit is a sacrificin' site. The old empire used ta' feed unruly sorts to the waters as it were. Well ah mean to see me what's down in that water. Gather up some fresh tortoise shells and meet me at the pit. Let's see if ol' legends be true.",starts={{npcID=58422,x=0.16,y=0.826,zoneID=5805}},ends={{npcID=58422,x=0.16,y=0.826,zoneID=5805}},coords={x=0.16,y=0.826,source="quest_giver",zoneID=5805},questType="standard"},
[30186] = {id=30186,name="Parental Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="If them tablets were correct, all ay got ta do is a small dance ritual and the big thing o' the deep will be summoned. When it comes out, we'll get 'em and show me pop we are both true big game hunters like him.",starts={{npcID=58422,x=0.16,y=0.826,zoneID=5805}},ends={{npcID=58421,x=0.16,y=0.824,zoneID=5805}},coords={x=0.16,y=0.826,source="quest_giver",zoneID=5805},questType="standard"},
[30187] = {id=30187,name="Flight Training: In Due Course",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="Now that you have learned the basics of the race, you should go learn the course. Explore the spires and collect a race flag from each of the checkpoints . Fly through each checkered flag to collect it.",starts={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},ends={{npcID=58420,x=0.586,y=0.436,zoneID=5785}},coords={x=0.586,y=0.436,source="quest_giver",zoneID=5785},questType="standard"},
[30188] = {id=30188,name="Riding the Skies",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I can no longer call myself your teacher, . You have proven yourself worthy of your cloud serpent. Today, you shall join our ranks. Are you ready?",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="standard"},
[30189] = {id=30189,name="A Lovely Apple for Ella",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30197] = {id=30197,name="Cart Ride",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="The vale has been quiet all morning. I'm sending Rook with a cart of supplies out to the XXX Village. You should join him.",questType="standard"},
[30198] = {id=30198,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30199] = {id=30199,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30201] = {id=30201,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30202] = {id=30202,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30203] = {id=30203,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30209] = {id=30209,name="Tracking Event: 3rd Place",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5974,questType="standard"},
[30229] = {id=30229,name="The Greater Danger",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="I apologize for my harsh words earlier. Dezco might have been right to wait and move west with a unified strength. The mogu hit us hard when we were searching the ruins west of here. They ambushed us using summoning portals and some dark magics. I haven't seen such evil sorcery used since Outland. We need a respite. Head west, kill their summoners, cut their supply line.",starts={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},ends={{npcID=58114,x=0.598,y=0.248,zoneID=6134}},coords={x=0.598,y=0.248,source="quest_giver",zoneID=6134},questType="standard"},
[30230] = {id=30230,name="Re-Reclaim",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Mogu are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic. But these mogu are using arcane portals and spells. We need to stop them! $p, look for any artifacts the mogu are using to cast their magics with. I saw a number of their collectors and reclaimers to the west and north that were gathering these items.",starts={{npcID=56112,x=0.6,y=0.25,mapID=418}},ends={{npcID=56112,x=0.6,y=0.25,mapID=418}},coords={x=0.6,y=0.25,source="quest_giver",mapID=418},questType="standard"},
[30240] = {id=30240,name="Survival Ring: Flame",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare. Survive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.",starts={{npcID=58743,x=0.186,y=0.714,zoneID=5840}},ends={{npcID=58743,x=0.186,y=0.714,zoneID=5840}},coords={x=0.186,y=0.714,source="quest_giver",zoneID=5840},questType="standard"},
[30241] = {id=30241,name="Warn Stoneplow",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,mapID=376,description="So much death. And more to come, if Ambassador Han's stories of the mantid are to be believed. We must help. We must do our part to save lives. Travel to Stoneplow. Warn them of the coming mantid attack. I will join you with what forces I can muster once I have laid Kor's body to rest.",starts={{npcID=58607,x=0.288,y=0.508,mapID=418}},ends={{npcID=56720,x=0.194,y=0.568,mapID=376}},coords={x=0.288,y=0.508,source="quest_giver",mapID=376},questType="standard"},
[30242] = {id=30242,name="Survival Ring: Blades",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="This is one of the challenges I put upon my warriors to keep them strong and fast. Let's see how you fare. Survive the ring for 60 seconds without getting pushed out or killed. Stay on your toes.",starts={{npcID=58743,x=0.186,y=0.714,zoneID=5840}},ends={{npcID=58743,x=0.186,y=0.714,zoneID=5840}},coords={x=0.186,y=0.714,source="quest_giver",zoneID=5840},questType="standard"},
[30243] = {id=30243,name="Mantid Under Fire",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The mantid are attacking again, and we're a bit short-handed up on the wall. In hopes that you'd help, I saved one of the more fun posts for you: the hot oil! It's a bit more violent and a bit less scandalous than it sounds. It's simple really. Get up on the wall, find one of the oil stations, and dump it on any of the mantid pouring up against the wall. It's very effective.",starts={{npcID=58920,x=0.214,y=0.716,zoneID=5840}},ends={{npcID=58920,x=0.214,y=0.716,zoneID=5840}},coords={x=0.214,y=0.716,source="quest_giver",zoneID=5840},questType="standard"},
[30247] = {id=30247,name="Roll Club: Vale of Eternal Blossoms",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="Follow the flags. Make the checkpoints. Round the loop. Get back to me before your time is up. Speak to me when you're ready to roll.",questType="standard"},
[30252] = {id=30252,name="A Helping Hand",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've been pushing and shoving and hammering all morning, but it's hopeless. These rocks won't budge! \"It will be a breeze,\" Grandpa said. \"Farming's like breathing!\" he said. Maybe for him, but not for me! How am I supposed to succeed at this whole FARMING thing if I can't even clear my farm for planting? Hey, wait a minute. You look like you've got some muscle on you. Would you be willing to help me out? Just until I can catch my breath.",starts={{npcID=58721,x=0.52,y=0.48,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.52,y=0.48,source="quest_giver",zoneID=5805},questType="standard"},
[30254] = {id=30254,name="Learn and Grow II: Tilling and Planting",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Okay, now we've got our seeds, it's time to plant them. First, we have to prepare the soil! You gotta till the soil and break it up to make a nice bed for our little sprouts. Till those two plots of soil over there, then plant the seeds in them.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30255] = {id=30255,name="Learn and Grow III: Tending Crops",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="My grandfather used to say \"Yoonie, a cabbage is like a woman: ignore her and she'll turn rotten. Pamper her and she'll grow big and plump and you can put a ribbon on her and take her to market to show her off to your frie-\" look, he was from a different time, okay? The point is, now that our cabbages have sprouted, they need attention! Today they look a little dry, so you should water them. Here's the old watering can grandpa left. It will always be near the field if you need it.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30256] = {id=30256,name="Learn and Grow IV: Harvesting",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="It's time for our hard work to pay off! Normally we'd have to wait a day before the crops are ready to harvest. Fortunately, those seeds Greenfield gave us were specially designed to grow FAST. The yield won't be worth much, but they're good for stepping new farmers through the process. Our cabbages should be ready to harvest. I'll let you do the honors, of course!",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30257] = {id=30257,name="Learn and Grow V: Halfhill Market",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="All right friend, all of that farming was just for practice! Are you ready to try the real thing? There's a lady by the name of Gina Mudclaw who runs the Halfhill Market, which is across the street to the south. I heard she's looking to buy some vegetables. Since it's your first time meeting her, you shouldn't go empty-handed. Why don't you look around the ranch and see if there are any items hiding around? Might be that we'll find a good gift to take to our new neighbor!",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58706,x=0.532,y=0.516,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30258] = {id=30258,name="Mung-Mung's Vote I: A Hozen's Problem",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've been thinkin' about how to get into the Tiller's good graces, . Now, the Tiller's Union accepts new farmers each year, and there are five members on the voting council. We already got Gina's vote, but we'll have to prove ourselves to the other four members of their board. Why don't you go over and say hello to Mung-Mung ? He works with Mr. Mudclaw out on the Mudclaw's farm to the northwest.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30259] = {id=30259,name="Mung-Mung's Vote II: Rotten to the Core",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Dem virmen's back! They been biting Mr. Mudclaw's carrots. Ruining his crop. And who is gonna pay? Mung-Mung , that's who! You go get the chewed up carrots before Mr. Mudclaw sees. They all over the fields to the southwest, and down under the ground in the virmen's tunnels, too. Otherwise, Mung-Mung in big trouble. You do this for me?",starts={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},ends={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},coords={x=0.442,y=0.342,source="quest_giver",zoneID=5805},questType="standard"},
[30260] = {id=30260,name="Growing the Farm I: The Weeds",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Hey , I've been thinkin' recently about expanding my farm. See that plot there that's just covered in weeds? If we can get rid of those weeds, we could use that land for planting. I heard there's a farmer by the name of Gai Lan who knows a thing or two about weed whackin'. His farm is just out west. Go talk to him and see if he'd be willing to help us.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=57385,x=0.386,y=0.516,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30261] = {id=30261,name="Roll Club: Serpent's Spine",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Get to the bottom of the wall in the fastest time possible. Speak to me when you're ready to roll.",starts={{npcID=58704,x=0.182,y=0.634,zoneID=5840}},ends={{npcID=58704,x=0.182,y=0.634,zoneID=5840}},coords={x=0.182,y=0.634,source="quest_giver",zoneID=5840},questType="standard"},
[30262] = {id=30262,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30266] = {id=30266,name="Bloodied Skies",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=9105,description="We have cannons set up on the top of the towers flanking the main gate. They are our best method to clear the skies when the flying mantid try to pass over the wall, like they are now. Looks like you're on, .",starts={{npcID=58920,x=0.214,y=0.716,zoneID=5840}},ends={{npcID=58920,x=0.214,y=0.716,zoneID=5840}},coords={x=0.214,y=0.716,source="quest_giver",zoneID=5840},questType="standard"},
[30267] = {id=30267,name="Watery Woes",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I love fishing. I'd be enjoying myself much more, however, if I had my bait and my lures. They were thrown away in a... a misunderstanding with my wife, Rin. Gladecaster Lang sighs.> Should I let a whole day of fishing be ruined, just because of a little domestic squabble? No! All I need is bugs and feathers, after all, and this glade is filled with those two things. Care to help a fisherman out?",starts={{npcID=58736,x=0.61,y=0.33,zoneID=5805}},ends={{npcID=58736,x=0.61,y=0.33,zoneID=5805}},coords={x=0.61,y=0.33,source="quest_giver",zoneID=5805},questType="standard"},
[30268] = {id=30268,name="The Murksweats",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Take a good look. The river nearby is swarming with these snakes. Their venom causes a condition the locals call \"the murksweats.\" Several refugees were bitten as they fled the temple and have already begun to show symptoms: nausea, vomiting, and intense sweating as the body rejects all fluids, causing dehydration and potentially death. We are administering anti-venom as quickly as possible, but we'll need more venom glands. Don't bother removing the glands yourself - just bring back the whole head.",starts={{npcID=58609,x=0.404,y=0.346,mapID=418}},ends={{npcID=58609,x=0.404,y=0.346,mapID=418}},coords={x=0.404,y=0.346,source="quest_giver",mapID=418},questType="standard"},
[30269] = {id=30269,name="Unsafe Passage",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="As we say at the temple: \"Never fight a tiger with a hozen on your back.\" We will deal with the sha, but first we must see to the more immediate... nuisance. Groups of refugees from the temple are heading for a camp to the north, but they're being ambushed by saurok. Help me see the next group to the camp and we'll figure out our next move from there.",starts={{npcID=58547,x=0.442,y=0.43,zoneID=6134}},ends={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},coords={x=0.442,y=0.43,source="quest_giver",zoneID=6134},questType="standard"},
[30270] = {id=30270,name="Blinding the Riverblades",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="\"A hooded falcon catches no quarry.\" This is one of the first mantras we teach young monks at the temple. It means that even a foe as swift and lethal as a falcon can be neutralized by depriving its senses. The saurok have scouts all over the region acting as eyes for their raiding parties. It's time we put their eyes out, don't you think?",starts={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},ends={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},coords={x=0.406,y=0.336,source="quest_giver",zoneID=6134},questType="standard"},
[30271] = {id=30271,name="Sha Can Awe",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="The sha have the mysterious ability to evoke powerful, often overwhelming, emotional responses in their victims. As we fled the temple, senior members of the Crane Wing order stayed behind to cover our escape. They are no doubt being subjected to intense emotional trauma, and I fear they are not all strong enough to resist falling into despair. $p, we have to show them there is still hope! Show them that despair CAN be defeated!",starts={{npcID=59188,x=0.406,y=0.336,zoneID=6134},{npcID=59189,x=0.404,y=0.346,zoneID=6134},{npcID=59608,x=0.423,y=0.489,zoneID=6134}},ends={{npcID=59608,x=0.423,y=0.489,zoneID=6134}},coords={x=0.406,y=0.336,source="quest_giver",zoneID=6134},questType="standard"},
[30272] = {id=30272,name="Striking the Rain",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Now as for that \"striking the rain\" part... well, sometimes you have to. \"Hope is the sun behind a stormy sky - ever in the heart, but veiled to the eye.\" There seems to be no end to the sha pouring out of the temple. But in order to see beyond the veil of despair, you must carve through it. With any luck, you'll find a sun behind the clouds...",starts={{npcID=59138,x=0.406,y=0.336,zoneID=6134}},ends={{npcID=59608,x=0.423,y=0.489,zoneID=6134}},coords={x=0.406,y=0.336,source="quest_giver",zoneID=6134},questType="standard"},
[30273] = {id=30273,name="In the House of the Red Crane",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="\"Broken are the bodies wherein hopeless hearts reside - the blight of despair strikes forth from inside.\" This was the last piece of wisdom the Red Crane imparted to me, just hours before the Sha outbreak. It makes sense now... $p, when the Sha attacked, they broke forth from the temple's basement... All of his teachings - the very Way of the Crane itself... it's all been preparation for facing the Sha of Despair . The Red Crane has been expecting this conflict for centuries!",starts={{npcID=59608,x=0.423,y=0.489,zoneID=6134}},ends={{npcID=59719,x=0.404,y=0.492,zoneID=6134}},coords={x=0.423,y=0.489,source="quest_giver",zoneID=6134},questType="standard"},
[30274] = {id=30274,name="The Arcanic Oubliette",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="An Alliance member? Here? Elune be praised. My team has encountered a snag. We opened a portal to this land using some ancient scrolls we had found that predated Azshara's rule. Unfortunately, the coordinates provided on the tablets were warded and the portal that meant to take us to our destination landed us in this oubliette. We have been trapped here for days, and it is slowly leaching our energies to power itself. Can you find the nearby shackles that bind the oubliette and disable them?",ends={{npcID=58745,x=0.674,y=0.326,zoneID=6134}},questType="standard"},
[30275] = {id=30275,name="A Crocolisk Tale",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="How could this crocolisk have grown so large? Certainly, rumors exist of very old crocolisks that have grown to enormous sizes... but this female can't be more than a dozen years old. Perhaps someone in New Cifera can shed some light on the subject.",ends={{npcID=56773,x=0.606,y=0.338,zoneID=5805}},questType="standard"},
[30277] = {id=30277,name="The Crumbling Hall",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="An ancient mogu artifact has been uncovered in the Guo-Lai Vault, beyond the Hall of Statues. We've made repeated attempts to retrieve it, but none have been successful. We cannot let this artifact fall into the hands of the Shao-Tien. I need someone capable to retrieve it, and quickly. Are you in?",starts={{npcID=58919,x=0.214,y=0.716,zoneID=5840}},ends={{npcID=58919,x=0.214,y=0.716,zoneID=5840}},coords={x=0.214,y=0.716,source="quest_giver",zoneID=5840},questType="standard"},
[30280] = {id=30280,name="The Thunder Below",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Roars have been echoing out from inside the Guo-Lai Halls. The mogu have awakened some ancient beast, and it will not be long before they attempt to release it upon my men. Find your way to the Hall of the Serpent and slay the beast before it can be unleashed upon us. I would trust no other with such a dangerous and important task.",starts={{npcID=58919,x=0.214,y=0.716,zoneID=5840}},ends={{npcID=58919,x=0.214,y=0.716,zoneID=5840}},coords={x=0.214,y=0.716,source="quest_giver",zoneID=5840},questType="standard"},
[30303] = {id=30303,name="NOT USED",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[30306] = {id=30306,name="The Battle Ring",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,mapID=1530,description="We have some fresh trainees that are far from being a danger to you, but in numbers, they may prove enough of a challenge. And if not, they could use the lesson in humility. Step into the battle ring when you're ready. Don't go easy on them.",starts={{npcID=58962,x=0.204,y=0.736,mapID=1530}},ends={{npcID=58962,x=0.204,y=0.736,mapID=1530}},coords={x=0.204,y=0.736,source="quest_giver",mapID=1530},questType="standard"},
[30311] = {id=30311,name="High Standards",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5840,mapID=1530,description="If I had to pick the most important quality for a battle standard, it would be that it's standing up... and not on fire, but mostly the first one. So needless to say, I'm a bit concerned about our standard situation at the moment. If some unknown were to be so kind as to take a walk out on the battlefield to our northwest and stand our standards back up, both myself and my extremely sexy yet somewhat commanding wife would be very grateful.",questType="standard"},
[30317] = {id=30317,name="Water, Water Everywhere",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="How'd you like to make yourself useful? The season's been awful dry lately. I need someone to water the crops out in the Heartland. Here's the thing: I need you to water ALL of the crops. I keep a few kites with Wing Nga, the flightmaster across the way. Grab one of those kites, then throw water on any areas that look dry and dusty.",starts={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},ends={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},coords={x=0.482,y=0.338,source="quest_giver",zoneID=5805},questType="standard"},
[30318] = {id=30318,name="Chasing the Chicken",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Say, you there! , was it? I've got a problem, and I need someone with better legs than mine to help me solve it. My prize-winning chicken has flown the coop! Now she's out in the open, mingling with the other hens, wild birds, and... ill-intentioned roosters. My farm is west of here, south of the Skyrange. Could you find her, and bring her back to me?",starts={{npcID=58707,x=0.53,y=0.518,zoneID=5805}},ends={{npcID=58707,x=0.53,y=0.518,zoneID=5805}},coords={x=0.53,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[30319] = {id=30319,name="Pest Problems",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="One of my farmhands, Wika-Wika, has been tilling the soil in my westernmost field. I understand he's had some problems with pests. He's got plenty of pesticide to spray the bugs that eat my crops, but I'm afraid he has no way to deal with the marmots. Would you lend him a hand? With rampant hozen and virmen attacks, I can't afford to lose crops to simple pests.",starts={{npcID=57402,x=0.446,y=0.34,zoneID=5805},{npcID=59594,x=0.518,y=0.478,zoneID=5805}},ends={{npcID=57402,x=0.446,y=0.34,zoneID=5805}},coords={x=0.446,y=0.34,source="quest_giver",zoneID=5805},questType="standard"},
[30321] = {id=30321,name="Weed War II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Ssshhay... d'you know that guy over on the farm, with the... the *hic*... the weed problem? Gai Lan, I think his name was. I love that guy, man. Anywayshh, he said that if I *hic* sent an adventurer over to go pick his weeds, he'd get me some ale. It's jusht a few weeds, not too many, probably. *hic*",starts={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},ends={{npcID=58710,x=0.534,y=0.524,zoneID=5805}},coords={x=0.534,y=0.524,source="quest_giver",zoneID=5805},questType="standard"},
[30322] = {id=30322,name="Money Matters",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I love working in the market, although there's one aspect of this job I really dislike: collecting debts. While most pandaren debts are simply due to laziness, there are a few unsavory characters around town who simply don't want to pay, and there's some who are just too poor. A few people here in town owe me money. Could you go talk to them, and remind them about what they owe?",starts={{npcID=58706,x=0.532,y=0.516,zoneID=5805}},ends={{npcID=58706,x=0.532,y=0.516,zoneID=5805}},coords={x=0.532,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30323] = {id=30323,name="They Don't Even Wear Them",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="A few weeks ago, a group of those jumpy little Springtail virmen broke into my lockbox and stole several handfuls of my jewelry. I've since found a few pieces, but they still have most of my collection. If you're headed up to the Springtail Crag, in the cliffs to the north, you should keep an eye out for them. I'd love to get my jewelry back.",starts={{npcID=58761,x=0.45,y=0.338,zoneID=5805}},ends={{npcID=58761,x=0.45,y=0.338,zoneID=5805}},coords={x=0.45,y=0.338,source="quest_giver",zoneID=5805},questType="standard"},
[30324] = {id=30324,name="Not in Chee-Chee's Backyard",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5840,description="Not all hozen are the same. Chee-Chee's tribe was forest hozen... came from Jade Forest. Pretty easy to get along with. The Kunzen invaders... they come from mountains, far to the north. Not nearly as nice as Chee-Chee. They come into our green land, take our things, leave big mess behind. Chee-Chee wants to kill them. You like to help?",starts={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58709,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[30325] = {id=30325,name="Where It Counts",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've been watching those Kunzen hozen, and I've noticed a consistent pattern. Whenever they're getting ready to attack, they participate in strange, barbaric rituals around their totem. If we can disrupt this ritual, not only will we put off any impending attacks, we can deal a huge blow to their morale! So get in there, rough them up, and make as much of a mess as possible!",starts={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[30326] = {id=30326,name="The Kunzen Legend-Chief",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've heard people talk about the hozen like they're just some tribe of barely-functional idiots... but that's not true! They have brains, too - they just don't all like to use them that much. I've heard that the Kunzen tribe has two chiefs - one in charge of fighting, and one in charge of stories, lore, and history. What I wouldn't give to see what kind of stories they tell...",starts={{npcID=58705,x=0.528,y=0.518,zoneID=5805},{npcID=59517,x=0.516,y=0.478,zoneID=5805}},ends={{npcID=58705,x=0.528,y=0.518,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[30327] = {id=30327,name="You Have to Burn the Ropes",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I, umm... well... Oh, never mind. It was a stupid idea. It's just that, I was thinking that maybe we can stop the Kunzen hozen from attacking us without having to, you know... KILL anything. I noticed a few ropes on the side of the mountain. I think they're using them to climb down to our farms and... No, forget it. It was a silly idea anyways.",starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30328] = {id=30328,name="The Thousand-Year Dumpling",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="One of my most popular recipes is the Thousand-Year Dumpling, which is filled with preserved vegetables . I normally let the vegetables ferment in a hole underneath my house, but when I looked for them this morning, they were gone! I blame those thieving virmen. Bring them back, and I'll let you help me cook!",starts={{npcID=58715,x=0.526,y=0.516,zoneID=5805}},ends={{npcID=58715,x=0.526,y=0.516,zoneID=5805}},coords={x=0.526,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30329] = {id=30329,name="Cindergut Peppers",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="A certain few pandaren around here prefer their dishes unbearably spicy. Unfortunately, my access to such peppers is limited. The Kunzen hozen, in the mountains to the west, often carry cindergut peppers . A few of those and I'll be set for a few days. Say, could you collect some for me? You might want to wear gloves if you'll be handling them directly.",starts={{npcID=58713,x=0.528,y=0.518,zoneID=5805}},ends={{npcID=58713,x=0.528,y=0.518,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[30330] = {id=30330,name="The Truffle Shuffle",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="I like to bake with truffles... when I can find them. They only grow up on the Skyrange, and in very, very scarce amounts. They're a fantastic ingredient, but we can't risk over-farming them. That's why we need to replace what we've taken. Bring me a handful of adult truffles, and plant some of these spores in their place.",starts={{npcID=58716,x=0.532,y=0.516,zoneID=5805}},ends={{npcID=58716,x=0.532,y=0.516,zoneID=5805}},coords={x=0.532,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30331] = {id=30331,name="The Mile-High Grub",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="Have you ever tried Mushan Tail Stew ? Chances are, if you have, that it was stringy and tasteless. You see, there's a trick to making the perfect Mushan Tail Stew : you need to cook it at high elevation. I've already gathered the ingredients. Take this pot up to the Kunzen Village, up in the mountains to the west, and prepare the stew over their bonfire.",starts={{npcID=58714,x=0.526,y=0.516,zoneID=5805}},ends={{npcID=58714,x=0.526,y=0.516,zoneID=5805}},coords={x=0.526,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[30332] = {id=30332,name="Fatty Goatsteak",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="You know what? I think I want to grill up some goatsteak today. No, not from the puny little shaghorns they keep around here. They don't have nearly enough fat on them. You think I got to this size eating no-fat-havin' goats? Now, the shaghorns up on the Skyrange, to the west... those'll do just fine.",starts={{npcID=58712,x=0.53,y=0.514,zoneID=5805}},ends={{npcID=58712,x=0.53,y=0.514,zoneID=5805}},coords={x=0.53,y=0.514,source="quest_giver",zoneID=5805},questType="standard"},
[30333] = {id=30333,name="The Lesser of Two Evils",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Like any farming community, we have the occasional virmen troubles. The most powerful Springtail virmen live high up in the cliffs to the north, and only come down when they run out of veggies to nibble on. Frankly, I've dealt with virmen before. They're nothing but a pest that must be kept in check, and there's no better way to do that than by killing their warren-mother. Easy as that.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30334] = {id=30334,name="Stealing is Bad... Re-Stealing is OK",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The hozen, up in the mountains to the west, continue to steal vegetables from my fellow farmers. Being so close to Halfhill, I very rarely suffer hozen attacks, but my friends have not been so lucky. Seems to me like they steal way more than they can eat. If you can find any intact vegetables up there in those mountains... steal them back!",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30335] = {id=30335,name="Stalling the Ravage",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5840,description="The Kunzen hozen, up in the mountains to the west, have been acting up, lighting their fires and shouting their chants. Based on what I've heard and seen around here, that means that a ravage is coming. There's not much we can do to stop the ravage, but we can at least thin their numbers before they attack.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30336] = {id=30336,name="The Kunzen Hunter-Chief",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="From what I've gathered, the Kunzen hozen have two chiefs. One is harmless - he deals with potions, medicines, and ancient fables. The other one is in charge of the Kunzen's hunters - and the only thing they've been hunting lately is our crops. The Hunter-Chief is a problem waiting to be solved. I'm sure the local farmers would be grateful if you went up there and, you know, \"took care\" of him.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30337] = {id=30337,name="Simian Sabotage",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The hozen steal from us, and we keep stealing our stuff back. It has to stop sometime. Farmer Yoon hands you a barrel of fireworks .> Find some of our stolen supplies in their mountain camp to the west, and place these fireworks beside them. Hopefully, if they see the explosions, they'll think our supplies are defective and stop stealing altogether. It's worth a shot, right?",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[30343] = {id=30343,name="To the Waterline!",level=5,requiredLevel=5,faction="horde",expansion=4,zoneID=6040,questType="dungeon"},
[30344] = {id=30344,name="The Lost Dynasty",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="I wonder if I could bother you for another task. My daughter, the good Sentinel Commander Lyalia here, refuses to let me go into the field. I have spent everyday in that oubliette staring at the ruins to our north, itching to investigate. If we are where I suspect we are those ruins could contain the key we need to finding the fabled Pools of Youth! Please, ! Go to those ruins and salvage any tablets that still have writing on them.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30346] = {id=30346,name="Where are the Pools",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Perhaps these mogu know where the pools are. Our scouts have reported seeing a commander along the southern side of the Ruins of Dojan. Kill him and take whatever information he is carrying. They should lead you to the pool.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30347] = {id=30347,name="The Pools of Youth",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="North! Go north to the Pools of Youth. Get some of the water but be on your guard. The mogu list this as a \"high value\" target. Kang Bramblestaff will meet you there if he has not already arrived by your side.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30348] = {id=30348,name="Immortality?",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Something is... off. The water feels strange. When we arrived here I felt the presence of the Light, strong and vibrant, far to the north. I thought it would be the Pools of Youth. But this... this water is tainted somehow. Stained with mogu magics. I think it best I try only a sip and we see what happens.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30349] = {id=30349,name="Threat from Dojan",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="While you were at the ruins dusting off tablets for my father I lost five scouts to wandering mogu patrols. These creatures apparently have little interest in peace and are about as trustworthy as the Horde. They are too numerous and we are too weak, however. Go to the ruins west of here and cull the mogu numbers. They won't be expecting a .",starts={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
[30350] = {id=30350,name="Squirmy Delight",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="The hidden master may have to wait. Look at these people, $p. They are so THIN! They must be starving. You know what we need? A big steaming bowl of Squirmy Delight . If you find yourself near a river, try rounding up some intact skitterer glands and I'll cook up a batch.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=376},questType="standard"},
[30351] = {id=30351,name="Lotus Tea",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="The mogu really like their poisons and curses. Mama Bramblestaff always said lotus tea cures any mogu curse. I saw some imperial lotus plants in the nearby Ruins of Dojan. We should go gather some of their leaves and keep them on hand just in case the mogu get unruly. Also, this will give me a chance to introduce my fists to some mogu faces.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418},{npcID=58814,x=0.548,y=0.382,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30352] = {id=30352,name="Crane Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,description="Thing about hunting birds is you need ammo - and I ain't got any. Thing about hunting with Nesingwary is you need to prove you can keep your tally and bragging rights up. Can't hunt, can't brag. And I like bragging so this is no good. Can I hire you to go kill me some carp hunters ? You'll find them up and down the river west of here. There are a bunch of them so don't hesitate to hunt while doing other stuff.",starts={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},ends={{npcID=58779,x=0.676,y=0.256,zoneID=6134}},coords={x=0.676,y=0.256,source="quest_giver",zoneID=6134},questType="standard"},
[30353] = {id=30353,name="Profit Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6134,mapID=418,description="Two words: Tiger Blood! This is gonna sell better than saronite back on the black market. Especially once I finish spreading a rumor about how it makes you all buff and stuff. And this jungle is just full of tigers. Can you round up a few vials of tiger blood for me? I'll cut you in on the scam.",starts={{npcID=58779,x=0.676,y=0.256,mapID=418}},ends={{npcID=58779,x=0.676,y=0.256,mapID=418}},coords={x=0.676,y=0.256,source="quest_giver",mapID=418},questType="standard"},
[30354] = {id=30354,name="No Sister Left Behind",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="We were searching the ruins south of here when the mogu fell upon us out of nowhere. Some of us were able to retreat to this encampment but many others were captured. The mogu have also caught a number of the Horde who happened to be in the area as well. Please, $p, rescue any sentinels that you can. Leave the Dawnchasers to their fate.",starts={{npcID=58821,x=0.248,y=0.34,mapID=418}},ends={{npcID=58821,x=0.248,y=0.34,mapID=418}},coords={x=0.248,y=0.34,source="quest_giver",mapID=418},questType="standard"},
[30355] = {id=30355,name="Re-Reclaim",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Mogu do NOT use arcane magics. They are thugs. They have always been thugs. Only when they ruled their empires in the old stories did they ever know any kind of magic. But these mogu are using arcane portals and old artifacts. We need to stop them! $p, look for any artifacts the mogu are using to cast their magics with. I saw piles of these items being collected near the Ruins of Korja south of here.",starts={{npcID=56114,x=0.674,y=0.326,mapID=418}},ends={{npcID=56114,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30356] = {id=30356,name="Sever Their Supply Line",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The mogu reclaimers are using portals to connect to Kun-Lai Summit, bringing in reinforcements and supplies. What is worse, they are sending their captives through these portals. Go to the Ruins of Korja and destroy as many of these Korjan Reclaimers as you can find.",starts={{npcID=58821,x=0.248,y=0.34,zoneID=6134}},ends={{npcID=58821,x=0.248,y=0.34,zoneID=6134}},coords={x=0.248,y=0.34,source="quest_giver",zoneID=6134},questType="standard"},
[30357] = {id=30357,name="The Stoneplow Convoy",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Help me, $p. These poor pandaren are in need of healing, and my powers are weakened. I did find an old tome in my collection that allowed me to convert the herbs you collected earlier into a healing poultice. Use this on the injured pandaren and it should get them back on their feet.",starts={{npcID=58745,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58745,x=0.674,y=0.326,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
[30358] = {id=30358,name="Gryphon, Down",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30359] = {id=30359,name="The Lord Reclaimer",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="They have my daughter! Brojai... that Lord Reclaimer! I can see him clearly through Lyalia's eyes. That foolish girl must have tried to take him head on. Please, $p! Go to the Ruins of Korja and try to free her. I'll get Kang and try to draw out Brojai from the ruins with a distraction.",starts={{npcID=58745,x=0.674,y=0.326,mapID=418}},ends={{npcID=58745,x=0.674,y=0.326,mapID=418}},coords={x=0.674,y=0.326,source="quest_giver",mapID=418},questType="standard"},
[30360] = {id=30360,name="Warn Stoneplow",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="My father gave me his life. Tyrande gave me her trust. My sentinels gave me their allegiance. It is time I repaid them all. With Brojai dead we can mop up the remaining mogu. The next threat is the mantid. Go north to Stoneplow and lend them your help. Tell them I will be bringing what sentinels I can muster to aid in the defense of their city against the mantid.",starts={{npcID=58821,x=0.248,y=0.34,mapID=418}},ends={{npcID=56720,x=0.194,y=0.568,mapID=376}},coords={x=0.248,y=0.34,source="quest_giver",mapID=376},questType="standard"},
[30361] = {id=30361,name="The Mantid",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,description="The mantid! They came out of nowhere and smashed our convoy to ruin, scattering our people this way and that. Now they are preparing to hit Stoneplow. Please, , destroy some of these beasts before they get sufficient numbers to flank our home. If my cousin, Ambassador Len , is still alive and at our convoy he should be able to reward you for your help.",starts={{npcID=58630,x=0.248,y=0.342,mapID=418}},ends={{npcID=58954,x=0.156,y=0.396,mapID=418}},coords={x=0.248,y=0.342,source="quest_giver",mapID=376},questType="standard"},
[30362] = {id=30362,name="Tanks for Nothing!",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30363] = {id=30363,name="Going on the Offensive",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Ha! So my father just wasted twenty years of our lives on a fool's errand! I'm taking charge. When Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it. I want you to look for my scout. I sent her to investigate the Crane Temple but she hasn't returned. Get her report and rendezvous with us at the Sentinel Basecamp further west.",starts={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58821,x=0.248,y=0.34,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
[30364] = {id=30364,name="Fly, Spy!",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30376] = {id=30376,name="Hope Springs Eternal",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="The Shado-Pan are likely dealing with similar outbreaks elsewhere in Pandaria. Seek out Loon Mai , the Shado-Pan Watch Commander in Stoneplow on the western end of the Valley of the Four Winds . Let him know that we have the situation here under control; the Shado-Pan need not send any aid. Quite the opposite, in fact - I will be sending many of my followers on pilgrimage, to bring a message of hope to those in need. Thank you again, $p. Farewell.",starts={{npcID=59719,x=0.404,y=0.492,zoneID=6134}},ends={{npcID=56720,x=0.194,y=0.568,zoneID=5805}},coords={x=0.404,y=0.492,source="quest_giver",zoneID=6134},questType="standard"},
[30377] = {id=30377,name="Minimum Safe Distance",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
[30378] = {id=30378,name="The Blastmaster",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=6040,questType="dungeon"},
