[30384] = {id=30384,name="Blind Them!",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived. I don't know how he got here but I can guarantee you he isn't alone. They never are. Kill the sunwalker scout before he reports our position.",starts={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},ends={{npcID=58735,x=0.674,y=0.326,zoneID=6134}},coords={x=0.674,y=0.326,source="quest_giver",zoneID=6134},questType="standard"},
