[31397] = {id=31397,name="FLAG - Wodin's Mantid Shanker",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[31398] = {id=31398,name="Falling to Pieces",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Why would the saurok have amber? More importantly, why would Oracle Hiss'ir be so protective of it? It is unlikely this came from the heavily guarded Zan'vess, so where did it come from? Perhaps the Klaxxi will know what to make of it.",starts={{npcID=214062,x=0.419,y=0.638,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.419,y=0.638,source="quest_giver",zoneID=6138},questType="standard"},
