[31439] = {id=31439,name="Dropping Our Signal",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The beacon in Amberglow Hollow seems to have been tampered with. Right before the signal cut out the Klaxxi'va picked up a signal for another paragon nearby. They believe he is hidden in that wretched little swamp, Duskroot Fen. I will meet you in the fen to set up a temporary beacon until I can get Amberglow operational again. You will wake the paragon and then you will help me.",starts={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},ends={{npcID=64569,x=0.562,y=0.582,zoneID=6138},{npcID=64672,x=0.562,y=0.582,zoneID=6138}},coords={x=0.548,y=0.34,source="quest_giver",zoneID=6138},questType="standard"},
[31440] = {id=31440,name="The Four Tomes",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6066,description="There are four tomes of great necromantic evil studied in Scholomance : \" In the Shadow of the Light \", \" Kel'Thuzad's Deep Knowledge \", \" Forbidden Rites and other Rituals Necromantic \" and \" The Dark Grimoire \". As we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.",questType="dungeon"},
[31441] = {id=31441,name="Corruption Runs Deep",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Today you learn that no one can be trusted in times of war, Wakener. Even those closest to the Klaxxi are susceptible to corruption. Who knows how long this traitor has been corrupted. He must be destroyed! You appear confused. Do you not see the traitor in our midst? Allow me to adjust your vision.",starts={{npcID=64569,x=0.562,y=0.582,zoneID=6138},{npcID=64672,x=0.562,y=0.582,zoneID=6138}},ends={{npcID=64705,x=0.562,y=0.576,zoneID=6138},{npcID=65454,x=0.562,y=0.582,zoneID=6138}},coords={x=0.562,y=0.582,source="quest_giver",zoneID=6138},questType="standard"},
[31442] = {id=31442,name="The Four Tomes",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6066,description="There are four tomes of great necromantic evil studied in Scholomance : \" In the Shadow of the Light \", \" Kel'Thuzad's Deep Knowledge \", \" Forbidden Rites and other Rituals Necromantic \" and \" The Dark Grimoire \". As we make our way through this cursed place, find and destroy each book so that no other fool can come along later and learn their vile secrets.",questType="dungeon"},
[31443] = {id=31443,name="Flying Tiger Gourami",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6006,mapID=379,description="You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31444] = {id=31444,name="Spinefish Alpha",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6757,mapID=554,description="You have fished up something special. It looks pretty aggressive. Maybe Nat Pagle at the Anglers Wharf might know more about it?",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31445] = {id=31445,name="zzOld",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=5840,mapID=1530,questType="standard"},
[31446] = {id=31446,name="Mimic Octopus",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6661,description="You aren't sure how, but you've caught an extraordinary cephalopod. Nat Pagle at Anglers Wharf would be very interested to see it.",ends={{npcID=63721,x=0.684,y=0.434,mapID=418}},questType="standard"},
[31447] = {id=31447,name="An End to the Suffering",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=6066,description="The key to lifting the curse of this place rests in the final death of Darkmaster Gandling . Do it, $p, and make him suffer!",questType="dungeon"},
[31448] = {id=31448,name="An End to the Suffering",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6066,description="The key to lifting the curse of this place rests in the final death of Darkmaster Gandling . Do it, $p, and make him suffer!",questType="dungeon"},
[31450] = {id=31450,name="A New Fate",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=14,description="These new allies have shed light on a great and important truth: it is not just Shen-zin Su that is ailing, but all of the land beyond the clouds. The world needs healing, and I think that you should be the ones to heal it. I would like you, Ji, and Aysa to leave and bring your strength and wisdom to the world. These Alliance and Horde have different ideals, but at the core of both lies noble intent. I will leave the choice of who you wish to accompany to you.",starts={{npcID=56013,x=0.514,y=0.484,zoneID=5736}},ends={{npcID=60566,x=0.742,y=0.924,zoneID=1519},{npcID=60570,x=0.456,y=0.126,zoneID=14}},coords={x=0.514,y=0.484,source="quest_giver",zoneID=5736},questType="standard"},
[31451] = {id=31451,name="The Missing Merchant",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,description="Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here... I'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?",starts={{npcID=63535,x=0.624,y=0.796,zoneID=5841}},ends={{npcID=59263,x=0.748,y=0.888,zoneID=5841}},coords={x=0.624,y=0.796,source="quest_giver",zoneID=5841},questType="standard"},
[31452] = {id=31452,name="The Missing Merchant",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,description="Usually, Merchant Shi comes through Kun-Lai Summit to trade with the Jinyu and Grummle. We've heard word that he hadn't been seen at Binan, and we haven't seen him here... I'm worried something has happened to him. Can you go to the Inkgill Mere and see if he's there?",starts={{npcID=63542,x=0.546,y=0.842,zoneID=5841}},ends={{npcID=59263,x=0.748,y=0.888,zoneID=5841}},coords={x=0.546,y=0.842,source="quest_giver",zoneID=5841},questType="standard"},
[31453] = {id=31453,name="The Shado-Pan",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,description="Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive. It's clear that, no matter what happens here in Kun-Lai, making an alliance with these Shado-Pan will be critical to our foothold in Pandaria. That's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You will go there, and curry their favor. For the Horde!",starts={{npcID=59442,x=0.716,y=0.932,zoneID=5841}},ends={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},coords={x=0.716,y=0.932,source="quest_giver",zoneID=5841},questType="standard"},
[31455] = {id=31455,name="The Shado-Pan",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,description="Our new recruits have spoken in hushed tones about a group of Pandaren they call the \"Shado-Pan\". They are apparently very strong, and secretive. That's where you come in. Rumor is they have a base of operations to the southeast, near Firebough Nook. You should travel there as an envoy of the Alliance. Give them any help they require.",starts={{npcID=59441,x=0.716,y=0.93,zoneID=5841}},ends={{npcID=60161,x=0.444,y=0.898,zoneID=5841}},coords={x=0.716,y=0.93,source="quest_giver",zoneID=5841},questType="standard"},
[31456] = {id=31456,name="Muskpaw Ranch",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,description="There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion. You've been so helpful - you should go check up on them, friend!",starts={{npcID=63754,x=0.538,y=0.84,zoneID=5841}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={x=0.538,y=0.84,source="quest_giver",zoneID=5841},questType="standard"},
[31457] = {id=31457,name="Muskpaw Ranch",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,description="There's another Pandaren settlement out here, Muskpaw Ranch. I don't know if they're alright, what with everything that's been going on with the Yaungol invasion. You've been so helpful - you should go check up on them, friend!",starts={{npcID=63751,x=0.636,y=0.866,zoneID=5841}},ends={{npcID=59353,x=0.71,y=0.692,zoneID=5841}},coords={x=0.636,y=0.866,source="quest_giver",zoneID=5841},questType="standard"},
[31458] = {id=31458,name="Damage Control",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Kor'ik has been sending signals to the empress for weeks. Everything the Klaxxi have done, the empress knows about. That stops now! Kypari Ik will be the first to receive news of Kor'ik's demise. It would benefit us to make sure that message does not make it to the empress. Destroying the whisperers and beacon there will buy us enough time to come up with a plan before the empress can act.",starts={{npcID=64705,x=0.562,y=0.576,zoneID=6138},{npcID=65454,x=0.562,y=0.582,zoneID=6138}},ends={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},coords={x=0.562,y=0.576,source="quest_giver",zoneID=6138},questType="standard"},
[31459] = {id=31459,name="Cho's Missive",level=20,requiredLevel=20,faction="horde",expansion=4,zoneID=5841,description="One of those grummles came by and said that Lorewalker Cho sent for you. You should go ahead and meet up with him, he might have something important to say. The grummel said he's at Onekeg, to the north.",starts={{npcID=59449,x=0.626,y=0.806,zoneID=5841}},ends={{npcID=61847,x=0.574,y=0.616,zoneID=5841}},coords={x=0.626,y=0.806,source="quest_giver",zoneID=5841},questType="standard"},
[31460] = {id=31460,name="Cho's Missive",level=20,requiredLevel=20,faction="alliance",expansion=4,zoneID=5841,description="One of those adorable little grummles came by and said that Lorewalker Cho sent for you. You should meet up with him! The grummel said he's at Onekeg, to the north.",starts={{npcID=59451,x=0.536,y=0.832,zoneID=5841}},ends={{npcID=61847,x=0.574,y=0.616,zoneID=5841}},coords={x=0.536,y=0.832,source="quest_giver",zoneID=5841},questType="standard"},
[31465] = {id=31465,name="Extracting Answers",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,mapID=422,description="Kypari Ik is just one of many locations that houses some of Empress Shek'zeer's offspring. In their juvenile state the young are reckless and difficult to control. They are also deadly. Swarmborn are hatched with a highly toxic venom that diminishes in potency with age. The venom can incapacitate even the strongest and most skilled fighter if it hits flesh. I would like you to bring me some of this venom.",starts={{npcID=63785,x=0.548,y=0.36,mapID=422},{npcID=64705,x=0.562,y=0.576,mapID=422},{npcID=65454,x=0.562,y=0.582,mapID=422}},ends={{npcID=63785,x=0.548,y=0.36,mapID=422}},coords={x=0.548,y=0.36,source="quest_giver",mapID=422},questType="standard"},
[31467] = {id=31467,name="Strong as a Tiger",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="With the grill, you can transform those raw tiger steaks into food that makes you stronger. Learn the recipe for charbroiled tiger steaks from me. Show me what you can do.",starts={{npcID=58712,x=0.53,y=0.514,zoneID=5805}},ends={{npcID=58712,x=0.53,y=0.514,zoneID=5805}},coords={x=0.53,y=0.514,source="quest_giver",zoneID=5805},questType="standard"},
[31470] = {id=31470,name="Way of the Wok",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="If you wish to make dishes that enhance agility, you should bring some carrots and rice to the Master of the Wok. The virmen around here tend to carry a lot of carrots around. You can also grow your own, if you have a farm.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=58713,x=0.528,y=0.518,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31471] = {id=31471,name="Agile as a Tiger",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="To cook with the wok, you need to be nimble. Your first lesson is sauteed carrots .",starts={{npcID=58713,x=0.528,y=0.518,zoneID=5805}},ends={{npcID=58713,x=0.528,y=0.518,zoneID=5805}},coords={x=0.528,y=0.518,source="quest_giver",zoneID=5805},questType="standard"},
[31472] = {id=31472,name="Way of the Pot",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6757,description="The cuisine of the Way of the Pot help expand your intellect. Bring some jade lungfish to the Master of the Pot and she will teach you. You can fish for jade lungfish in the Jade Forest.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=58714,x=0.526,y=0.516,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31474] = {id=31474,name="The Soup of Contemplation",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="Watching over the pot, you get a lot of time to think. Let me show you how to make swirling mist soup and you'll know what I mean.",starts={{npcID=58714,x=0.526,y=0.516,zoneID=5805}},ends={{npcID=58714,x=0.526,y=0.516,zoneID=5805}},coords={x=0.526,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31475] = {id=31475,name="Way of the Steamer",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6661,description="A great meal can lift your spirits, and none more so than food from the Way of the Steamer . Bring the Master some giant mantis shrimp and he will show you. You can fish for giant mantis shrimp in the ocean.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=58715,x=0.526,y=0.516,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31476] = {id=31476,name="The Spirit of Cooking",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="When I cook with steam, I infuse the food with my love. Let me teach you the recipe for shrimp dumplings .",starts={{npcID=58715,x=0.526,y=0.516,zoneID=5805}},ends={{npcID=58715,x=0.526,y=0.516,zoneID=5805}},coords={x=0.526,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31477] = {id=31477,name="Endurance",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="They say that the crane appointed sentry by its flock stands guard with a stone in its beak, so that, should it fall asleep, the stone drops and it awakens. To be skilled with the oven, you need to have endurance and patience. Learn the recipe for wildfowl roast and show me that you understand.",starts={{npcID=58716,x=0.532,y=0.516,zoneID=5805}},ends={{npcID=58716,x=0.532,y=0.516,zoneID=5805}},coords={x=0.532,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31478] = {id=31478,name="Way of the Oven",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="If you are looking for a hearty meal that will sustain you and increase your stamina, you should seek out the Way of the Oven . Bring some wildfowl breasts to the Master of the Oven and she will teach you. There are plenty of cranes in the Valley of the Four Winds and in the Jade Forest, but you can obtain wildfowl breasts from other birds as well.",starts={{npcID=64231,x=0.536,y=0.512,mapID=376}},ends={{npcID=58716,x=0.532,y=0.516,mapID=376}},coords={x=0.536,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31479] = {id=31479,name="Way of the Brew",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="The Pandaren Way of the Brew produces... Well, I'll let the Master of the Brew explain it. Bring him some ginseng and he will show you the way.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=58717,x=0.53,y=0.52,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31480] = {id=31480,name="Have a Drink",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="My siblings are so serious. I think life's too short to be so serious all the time. Let's have some tea together. Let me teach you how to make ginseng tea .",starts={{npcID=58717,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58717,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31486] = {id=31486,name="Everything I Know About Cooking",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="I'm so glad you enjoy my food. Are you interested in the recipes? If so, you should learn them properly, from my teachers in Halfhill Market. Everything I know about the kitchen, I learned from them. Say, if you happen to pass through there, would you deliver this note to Sungshin Ironpaw for me? She was my favorite teacher, and I want her to know that I miss her.",starts={{npcID=56707,x=0.462,y=0.454,zoneID=5785},{npcID=62872,x=0.514,y=0.772,zoneID=6134}},ends={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},coords={x=0.462,y=0.454,source="quest_giver",zoneID=5785},questType="standard"},
[31487] = {id=31487,name="Sonic Disruption",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Relying on sonic whispers to manipulate the kunchong was only the most primitive stage of my research, and yet the Empire seems to have adopted the practice wholly. The manipulators of the Shek'zeer are too impatient to form a proper bond with their kunchong. Their laziness will cost them dearly. Strike this tuning fork near the dread kunchong in the clutches - watch as they reel in confusion and lash out at their masters. Use this to your advantage and put them down.",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31490] = {id=31490,name="Rank and File",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6052,description="First things first; let's kill us some crusaders. And when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.",questType="dungeon"},
[31492] = {id=31492,name="The Torch of Strength",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="Xuen has this challenge he says helps \"refine strength.\" I am starting to think the word \"strength\" means something different to him than the rest of us. Here, take this torch to the top of the gates of the temple. If you can get it there without the torch being extinguished, you pass the challenge. Whatever you do, do not try carrying the torch on a mount. It will blow out if you do. Trust me on that one.",starts={{npcID=60981,x=0.684,y=0.564,zoneID=5841}},ends={{npcID=60981,x=0.684,y=0.564,zoneID=5841}},coords={x=0.684,y=0.564,source="quest_giver",zoneID=5841},questType="standard"},
[31493] = {id=31493,name="Just for Safekeeping, Of Course",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6052,description="There is a book of great value to me here in the halls. Unfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out. You might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library. He'll probably burn the Scarlet Halls down in the process.",questType="dungeon"},
[31494] = {id=31494,name="Free From Her Clutches",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The Shek'zeer manipulators are corralling young kunchong into that clutch and exposing them to raw fear energies, twisting them and accelerating their growth. Disgusting! I will not allow it! Break open the cages and set those hatchlings free.",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31495] = {id=31495,name="Rank and File",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6052,description="First things first; let's kill us some crusaders. And when I say kill the Scarlet Crusade, I mean wipe them out, root and branch, rank and file.",questType="dungeon"},
[31496] = {id=31496,name="Sampling the Empire's Finest",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The wonders of the kypari sap never cease to amaze me. Among its numerous properties and applications, the sap can be refined into a nutritious and extremely delectable elixir. Nowhere in the Empire will you find a finer execution of this brew than the palace itself. Surely, the homes of the loyalists have feeders brimming with this sweet nectar. Fill this jar at their feeders and return it to me. I long to sample the imperial ambrosia once more.",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31497] = {id=31497,name="Just for Safekeeping, Of Course",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6052,description="There is a book of great value to me here in the halls. Unfortunately, it's in the possession of Flameweaver Koegler. I've tried to get close to him before, but it's never quite worked out. You might have better luck. Just watch out -- I hear that he's gone well and truly insane. The Flameweaver plans to burn every tome they have in the library. He'll probably burn the Scarlet Halls down in the process.",questType="dungeon"},
[31502] = {id=31502,name="Wing Clip",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The young fliers of this era are fascinating. Their exceptional agility and endurance were, in my time, the feats of incredibly skilled or mature fliers. This would seem to indicate some kind of evolution in wing structure... Or perhaps a result of advancements in training? Induced genetic mutation? Selective breeding? Gah! There's no way to know for certain without tissue samples. Bring me their wings! And try not to ruin them in the process, will you? I need them intact!",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31503] = {id=31503,name="Shortcut to Ruin",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="There is a champion among the loyalists, Vess-Guard Na'kal , whose strength comes not from experience or development, but from genetic modification. He was meant to be an example of the future of mantid - the sick idea that we can be born strong, without earning it. He's a mockery of my work! Gene augmentation was meant for mature, post-swarm veterans ONLY! End him. Perhaps it will serve as a lesson to Grand Empress Shek'zeer that taking shortcuts leads to ruin.",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31504] = {id=31504,name="Ordnance Disposal",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="If the Grand Empress's agents are still operating under security standards from my time, they would have hidden powerful pheromone mines all around the clutches. With mere whisper she could detonate them all simultaneously, engulfing the palace and rendering entire siege armies powerless. If we hope to have any success in a large scale standoff, we need to disable those mines. My... \"gift\" to you when we met will allow you to see the mines. Disturb them and get to a safe distance.",starts={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31505] = {id=31505,name="Vess-Guard Duty",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Vess-Guard Vik'az co-ordinates the defense forces at Zan'vess. He is worth ten mantid in battle, and his presence inspires the Zan'thik who fight alongside him. Needless to say, we need him dead. He patrols the housing area at the center of the island.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31506] = {id=31506,name="Shackles of Manipulation",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The Zan'thik employ a sizable force of... indentured labor. Yaungol are bound in special shackles which enhance and prolong the effects of sonic manipulation. It is this technology that allows the Zan'thik manipulators to command such large quantities of thralls to endlessly toil for them in the quarries. I would like to study these shackles.",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31507] = {id=31507,name="Meltdown",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The venomsting scorpions on Zan'vess are fed sap from a young age, causing a fascinating mutation in which their natural armor plating becomes infused with amber. Effectively, it's organic kyparite, the same substance used in forging most of the empire's weapons and armor. I think I've found a way to chemically break down kyparite, but it needs testing. Use these grenades on the Zan'thik venomstings and observe the results.",starts={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},ends={{npcID=62180,x=0.544,y=0.36,zoneID=6138}},coords={x=0.544,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31508] = {id=31508,name="Specimen Request",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Kyparite worms have shown extreme adaptations in order to mimic the environment around them. They can also grow to immense sizes at rates which are nearly unheard of for most creatures. Their physiology could provide valuable insight into further mutations. Bring me sample shards from the muck tunnelers in the shallows near Zan'vess.",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31509] = {id=31509,name="Fear Takes Root",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The fallout from Shek'zeer's madness will continue long after her reign has ended. We will struggle to heal our lands for many years to come, and even then our efforts may prove fruitless. A new species of sha-twisted flora has begun taking root near Zan'vess. Destroy any that you find, but beware - there is no telling what kind of sinister defenses it may have.",starts={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138}},coords={x=0.544,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31510] = {id=31510,name="Quiet Now",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="On the southwestern corner of Zan'vess lie the Whispering Stones. Much like the towers here, they are critical in transmitting long-range sonic signals. An adjunct of the Empress operates the stones, keeping her in communication with the Zan'thik forces. Disrupt the signal, then silence him.",starts={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},ends={{npcID=63785,x=0.548,y=0.36,zoneID=6138}},coords={x=0.548,y=0.36,source="quest_giver",zoneID=6138},questType="standard"},
[31513] = {id=31513,name="Blades of the Anointed",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6109,description="The problem with the Scarlet Crusade is that they keep coming back, even after death. Behind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade. To give her the final rest, we need two swords of legend, each with a lost but storied history. Luckily for me... er, us, these two blades of the anointed are at rest here within the monastery. Find them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.",questType="dungeon"},
[31514] = {id=31514,name="Unto Dust Thou Shalt Return",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6109,questType="dungeon"},
[31515] = {id=31515,name="Blades of the Anointed",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6109,description="The problem with the Scarlet Crusade is that they keep coming back, even after death. Behind those resurrections is High Inquisitor Whitemane. With her death, so goes the Crusade. To give her the final rest, we need two swords of legend, each with a lost but storied history. Luckily for me... er, us, these two blades of the anointed are at rest here within the monastery. Find them and once you've killed Whitemane, plunge the blades into her corpse to make the death permanent.",questType="dungeon"},
[31516] = {id=31516,name="Unto Dust Thou Shalt Return",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6109,mapID=18,questType="dungeon"},
[31517] = {id=31517,name="Contending With Bullies",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=5841,description="We honor strength here, not brutality. It is unfortunate but there are some who come to my doorstep oblivious to this distinction. I have turned away one such challenger. In retaliation, he sacked the village of Yinying. Go to Yinying Village southeast of the temple, and face this \" Shonuf .\" Give him a lesson in true strength.",starts={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},ends={{npcID=60968,x=0.664,y=0.464,zoneID=5841}},coords={x=0.664,y=0.464,source="quest_giver",zoneID=5841},questType="standard"},
[31518] = {id=31518,name="The Vale of Eternal Blossoms",level=20,requiredLevel=20,faction="none",expansion=4,zoneID=5841,mapID=379,questType="standard"},
[31519] = {id=31519,name="A Worthy Challenge: Yan-zhu the Uncasked",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a hearty group and lead them into Stormstout Brewery . Activate the Challenger's Orb therein, and evaporate Yan-zhu the Uncasked. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31520] = {id=31520,name="A Worthy Challenge: Sha of Doubt",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a hearty group and lead them into the Temple of the Jade Serpent . Activate the Challenger's Orb therein, and vanquish the Sha of Doubt. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31521] = {id=31521,name="To Be a Master",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="There will come a day when you have mastered all that we have to teach you. When that day comes, it will be time for you to teach others in turn. When you have proven to yourself that you have mastered all the Ways, come back and speak with me.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31522] = {id=31522,name="A Worthy Challenge: Sha of Hatred",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a tranquil group and lead them into the Shado-Pan Monastery . Activate the Challenger's Orb therein, and rescue Taran Zhu from the Sha of Hatred. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31523] = {id=31523,name="A Worthy Challenge: Xin the Weaponmaster",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a nimble group and lead them into Mogu'shan Palace . Activate the Challenger's Orb therein, and put an end to Xin the Weaponmaster. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31524] = {id=31524,name="A Worthy Challenge: Raigonn",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a cracking group and lead them into the Gate of the Setting Sun . Activate the Challenger's Orb therein and lay waste to Raigonn. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31525] = {id=31525,name="A Worthy Challenge: Wing Leader Ner'onok",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,mapID=1530,description=", I need you to assemble an eagle-eyed group and lead them into the Siege of Niuzao Temple . Activate the Challenger's Orb and ground Wing Leader Ner'onok. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,mapID=1530}},ends={{npcID=63994,x=0.612,y=0.208,mapID=1530}},coords={x=0.612,y=0.208,source="quest_giver",mapID=1530},questType="dungeon"},
[31526] = {id=31526,name="A Worthy Challenge: Durand",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,mapID=1530,description=", I need you to assemble a stout group and lead them into Scarlet Monastery . Activate the Challenger's Orb therein, and smite Durand with righteous fury. Return to me when you've completed this challenge, and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,mapID=1530}},ends={{npcID=63994,x=0.612,y=0.208,mapID=1530}},coords={x=0.612,y=0.208,source="quest_giver",mapID=1530},questType="dungeon"},
[31527] = {id=31527,name="A Worthy Challenge: Flameweaver Koegler",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a cunning group and venture forth into the depths of Scarlet Halls . Activate the Challenger's Orb therein, and put a stop to Flameweaver Koegler's book-burning ways.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31528] = {id=31528,name="A Worthy Challenge: Darkmaster Gandling",level=35,requiredLevel=35,faction="horde",expansion=4,zoneID=5840,description=", I need you to assemble a fearless group and lead them into the depths of Scholomance . Activate the Challenger's Orb, and cleanse Scholomance of Darkmaster Gandling's evil presence. Return to me when you've completed this challenge and I shall reward you handsomely.",starts={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},ends={{npcID=63994,x=0.612,y=0.208,zoneID=5840}},coords={x=0.612,y=0.208,source="quest_giver",zoneID=5840},questType="dungeon"},
[31529] = {id=31529,name="Mission: Culling The Vermin",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="I was sent to this valley to protect The Heartland from any potential threats. I've identified a high priority target. The Springtail vermin burrow into the mountain cliffs, high above the farmlands. Left unchecked, their numbers will multiply, and they will make their way down to the fields below. They must be eliminated.",starts={{npcID=58708,x=0.53,y=0.52,mapID=376}},ends={{npcID=58708,x=0.53,y=0.52,mapID=376}},coords={x=0.53,y=0.52,source="quest_giver",mapID=376},questType="standard"},
[31530] = {id=31530,name="Mission: The Hozen Dozen",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=5840,mapID=1530,description="I've been watching the hozen since I arrived, and I don't like the pattern of activity that I'm seeing in their camp. Multiple hozen travel down the mountain under the cover of night, pillaging supplies from the farmlands below. We must stop their rampant theft. I have been thinning their numbers when I can, but one soldier alone is not enough. I need your help. Kill as many of the hozen as you can.",questType="standard"},
[31531] = {id=31531,name="Mission: Aerial Threat",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I've identified another high risk target, one that most people would not suspect. The cliff kites soaring above the hills to the east are quite dangerous. I have seen them swooping down to the farms, snatching grain and seed when no one is looking. In order to protect the farms, we must thin their numbers.",starts={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31532] = {id=31532,name="Mission: Predator of the Cliffs",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="During my routine patrol of the mountains this morning, I spotted a huge white bird diving down to the farmlands. It lifted an entire yak in its talons and disappeared among the cliffs. Today a yak, tomorrow a farmhand! We must eliminate this bird before it chooses its next victim.",starts={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},ends={{npcID=58708,x=0.53,y=0.52,zoneID=5805}},coords={x=0.53,y=0.52,source="quest_giver",zoneID=5805},questType="standard"},
[31534] = {id=31534,name="The Beginner's Brew",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Can you keep a secret, ? I've been trying my hand at brewing. All I've got is this old hand-made still, but it still works pretty good. I've got an idea for a new brew, but I need some ingredients. I'm awful shy around the townsfolk, but I've seen you making friends all around. Would you be willing to ask the farmers for some ingredients for me?",starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31535] = {id=31535,name="Replenishing the Pantry",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,mapID=376,description="People come from all over Pandaria to learn cooking from the Ironpaw family. We take great pride not only in being the best chefs, but also in passing what we know onto others. That's why we try to charge as little as possible for cooking lessons. This means, however, that we often find ourselves in shortage of cooking ingredients for the lessons. Would you donate some to the school, to help out students who cannot afford it?",starts={{npcID=64395,x=0.534,y=0.512,mapID=376}},ends={{npcID=64395,x=0.534,y=0.512,mapID=376}},coords={x=0.534,y=0.512,source="quest_giver",mapID=376},questType="standard"},
[31536] = {id=31536,name="Preserving Freshness",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="To preserve maximum freshness, cooking ingredients need to be stored properly. Fortunately, Merchant Cheng over there sells good containers. I hate to send you on such a menial errand, but would you go purchase an empty tiger meat basket for me?",starts={{npcID=64395,x=0.534,y=0.512,zoneID=5805}},ends={{npcID=64395,x=0.534,y=0.512,zoneID=5805}},coords={x=0.534,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[31537] = {id=31537,name="Ella's Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Well, I finally got the brew made, but I won't know if it's any good unless some people taste it. Would you take my brew and see what the folks in Halfhill think? I... I couldn't face them myself.",starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31538] = {id=31538,name="A Worthy Brew",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="There's one final person who needs to taste my brew. I've heard that he's traveled far and wide, and tasted drinks from all over the world. He happens to be in town, and I'd like to know what he thinks of my skills.",starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31539] = {id=31539,name="A Thing of Beauty",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="We live in a world of magic.The few among us who are skilled can imbue this magic into the things we craft and give them power. Such things are valued. Fewer still, however, are those among us who can create things that are cherished through the ages not because they are imbued with power, but because of their great beauty. The Temple of the Jade Serpent has commissioned us for such a work, and I believe you are the worthiest among us. Will you accept the commission?",starts={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},ends={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},coords={x=0.546,y=0.442,source="quest_giver",zoneID=5785},questType="standard"},
[31540] = {id=31540,name="Staves for Tian Monastery",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="It seems like the Tian Monsatery is training a lot of monks this year. We've received a huge commission for staves. And by huge, I mean HUGE. Could you take on part of the commission? I'd very much appreciate it. You will receive the rewards for your portion, of course.",starts={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},ends={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},coords={x=0.546,y=0.442,source="quest_giver",zoneID=5785},questType="standard"},
[31541] = {id=31541,name="Set in Jade",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="One of the greatest poets of our time is Master Kwang. He has composed a poem of great beauty, and a merchant in Halfhill would like to have these words inscribed in stone, to display proudly in her home. She has requested a scribe of great skill to take on this job. Will you accept the commission?",starts={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},ends={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},coords={x=0.552,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[31542] = {id=31542,name="Incarnadine Ink",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="The practice of caligraphy is an old custom in Pandaria. I am working on a piece about an ancient war, so I seek an ink that is suitable to the subject matter. I have searched high and low for the right hue, but it eludes me. Can you think of a way to achieve the color I am seeking?",starts={{npcID=56064,x=0.548,y=0.452,mapID=371}},ends={{npcID=56064,x=0.548,y=0.452,mapID=371}},coords={x=0.548,y=0.452,source="quest_giver",mapID=371},questType="standard"},
[31543] = {id=31543,name="Portrait of a Lady",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,mapID=371,description="Many great pieces of art are results of great love. A merchant in Halfhill wishes to have a portrait made for his beloved, as a birthday present. Will you accept this commission?",starts={{npcID=56064,x=0.548,y=0.452,mapID=371}},ends={{npcID=56064,x=0.548,y=0.452,mapID=371}},coords={x=0.548,y=0.452,source="quest_giver",mapID=371},questType="standard"},
[31544] = {id=31544,name="A Tribute to the Dead",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="All things must come to an end - even the life of a good man. A family in Kun Lai has commissioned a monument for their beloved patriarch who has passed on recently. Will you accept the commission?",starts={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},ends={{npcID=56063,x=0.552,y=0.452,zoneID=5785}},coords={x=0.552,y=0.452,source="quest_giver",zoneID=5785},questType="standard"},
[31545] = {id=31545,name="The Finer Things",level=10,requiredLevel=10,faction="none",expansion=4,description="The Pandaria Treasure Society is interested in purchasing finely crafted goods from skilled jewelcrafters such as yourself. The items will be catalogued, and the most exceptional cuts stored in a secret vault, while the rest are sold to refresh our funds. Our goal is to eventually create a unique collection for a special event.",questType="standard"},
[31548] = {id=31548,name="Learning the Ropes",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1,description="Now that you are a pet trainer, it's time to test your skills! Head out into the valley and pick a fight with a battle pet. Come back to me after you have won and I will continue your training. Good luck!",starts={{npcID=63075,x=0.538,y=0.5,zoneID=1}},ends={{npcID=63075,x=0.538,y=0.5,zoneID=1}},coords={x=0.538,y=0.5,source="quest_giver",zoneID=1},questType="standard"},
[31549] = {id=31549,name="On The Mend",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1,description="Now that you have won a battle, we need to heal up your pets so they can fight another day! Visit Shelby Stoneflint, our local stable master, to heal and revive your pets.",starts={{npcID=63075,x=0.538,y=0.5,zoneID=1}},ends={{npcID=63075,x=0.538,y=0.5,zoneID=1}},coords={x=0.538,y=0.5,source="quest_giver",zoneID=1},questType="standard"},
[31550] = {id=31550,name="Got one!",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=12,description="Great work so far . You are going to be a pro at this pet stuff before you know it. Now it's time to catch a pet of your own! Head back out and find a battle pet to fight, engage it in battle and throw your trap once it's low on health. Bring your catch back for me to see once you are finished. Remember, you need at least one pet at level 3 to use your trap!",starts={{npcID=63014,x=0.402,y=0.66,zoneID=12}},ends={{npcID=63014,x=0.402,y=0.66,zoneID=12}},coords={x=0.402,y=0.66,source="quest_giver",zoneID=12},questType="standard"},
