[31603] = {id=31603,name="Seeds of Fear",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,starts={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},ends={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31605] = {id=31605,name="The Zan'thik Dig",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="We have just intercepted a message from an adjunct on Zan'vess. Yaungol laborers there have unearthed a paragon in the amber quarry on the back side of the island. Get there immediately and free him before the Zan'thik destroy him!",starts={{npcID=64815,x=0.548,y=0.34,zoneID=6138}},ends={{npcID=65253,x=0.318,y=0.89,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},coords={x=0.548,y=0.34,source="quest_giver",zoneID=6138},questType="standard"},
[31606] = {id=31606,name="The Dissector Wakens",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="You are... not like the others... I hear the Klaxxi calling... I just need a moment.",starts={{npcID=65253,x=0.318,y=0.89,zoneID=6138}},ends={{npcID=63072,x=0.544,y=0.358,zoneID=6138},{npcID=67091,x=0.318,y=0.89,zoneID=6138}},coords={x=0.318,y=0.89,source="quest_giver",zoneID=6138},questType="standard"},
[31609] = {id=31609,name="The Wrath of Shek'zeer",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="The rest of the freed paragons are scattered around the Heart of Fear, fighting off the mantid swarm. They may need your help!",starts={{npcID=64599,x=0.55,y=0.354,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31611] = {id=31611,name="The Kun-Lai Kicker",level=20,requiredLevel=20,faction="both",expansion=4,zoneID=6426,description="Have you ever seen the Brewmoon Festival ? The good folks of Binan Village host quite a party. And tonight's festivities are brew-catered by none other than yours truly here. I am making my famous Kun-Lai Kicker! Think you might come and join us for the festivities? It should be a completely relaxing event with absolutely no danger whatsoever.",starts={{npcID=63367,x=0.726,y=0.93,zoneID=5841},{npcID=63367,x=0.52,y=0.438,zoneID=6006}},ends={{npcID=63367,x=0.726,y=0.93,zoneID=5841},{npcID=63367,x=0.52,y=0.438,zoneID=6006},{npcID=64901,x=0.428,y=0.788,zoneID=6426}},coords={x=0.726,y=0.93,source="quest_giver",zoneID=5841},questType="dungeon"},
[31612] = {id=31612,name="Shadow of the Empire",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="You only understand part of our order. You are an outsider, and have been treated as such. It is no longer appropriate that we keep our secrets from you. There is something you should see.",starts={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},ends={{npcID=62538,x=0.55,y=0.358,zoneID=6138}},coords={x=0.55,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31613] = {id=31613,name="Volatile Greenstone Brew",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=6209,description="I am working on a batch of my famous Volatile Greenstone Brew. Should be superb in countering the rascals and mischievous elementals we have been seeing around the mines lately. Tell you what, how about you round up some of your friends and bring them back here to try out a round. First one's on the house!",starts={{npcID=62321,x=0.474,y=0.37,zoneID=5785}},ends={{npcID=62321,x=0.474,y=0.37,zoneID=5785},{npcID=61203,x=0.508,y=0.702,zoneID=6209}},coords={x=0.474,y=0.37,source="quest_giver",zoneID=5785},questType="dungeon"},
