[31808] = {id=31808,name="Rampage Against the Machine",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Kovok has progressed at an astonishing rate. Perhaps the years in hibernation effected his growth process... Whatever the reason, this could not have come at a better time. I believe it is time to test his abilities. You have done so much to aid in his training. It is only fitting that you assist him in his first battle. I've already guided him to the edge of the scar. Find him and destroy Shek'zeer's army!",starts={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},ends={{npcID=63758,x=0.542,y=0.358,zoneID=6138}},coords={x=0.542,y=0.358,source="quest_giver",zoneID=6138},questType="standard"},
[31809] = {id=31809,name="Remnants of Anger",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5841,mapID=379,description="As you look upon the severed claw of the defeated Sha of Anger, you realize that Ban Bearheart , commander of the Shado-Pan in Townlong Steppes , would want to know of your victory.",ends={{npcID=62304,x=0.49,y=0.704,mapID=388}},questType="standard"},
[31810] = {id=31810,name="Riding the Skies",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I can no longer call myself your teacher, . You have proven yourself worthy of your cloud serpent. Today, you shall join our ranks. Are you ready?",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="standard"},
[31811] = {id=31811,name="Riding the Skies",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I can no longer call myself your teacher, . You have proven yourself worthy of your cloud serpent. Today, you shall join our ranks. Are you ready?",starts={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},ends={{npcID=58564,x=0.576,y=0.448,zoneID=5785}},coords={x=0.576,y=0.448,source="quest_giver",zoneID=5785},questType="standard"},
[31812] = {id=31812,name="Zunta, The Pet Tamer",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,description="I can tell you have been honing your pet battle skills, . I think it's time for you to take on a real challenge. Zunta can be found near the Tor'kren Farm south of Orgrimmar. He is an up and coming wild pet tamer and I think it's time you faced him in battle!",starts={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},ends={{npcID=66126,x=0.438,y=0.288,zoneID=14}},coords={x=0.524,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[31813] = {id=31813,name="Dagra the Fierce",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=17,description="Der be another trainer not far from here that you ought to fight to test your worth. Dagra the Fierce waits on the northern slope of Thorn Hill, east of The Crossroads. If you be beatin' her, you just might have what it takes.",starts={{npcID=66126,x=0.438,y=0.288,zoneID=14}},ends={{npcID=66135,x=0.586,y=0.53,zoneID=17}},coords={x=0.438,y=0.288,source="quest_giver",zoneID=14},questType="standard"},
[31818] = {id=31818,name="Zunta",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=14,mapID=1,description="Think you can take me again, eh?",starts={{npcID=66126,x=0.438,y=0.288,mapID=1}},ends={{npcID=66126,x=0.438,y=0.288,mapID=1}},coords={x=0.438,y=0.288,source="quest_giver",mapID=1},questType="standard"},
[31819] = {id=31819,name="Dagra the Fierce",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=17,mapID=10,description="You climbed this mountain once more only to face your own demise.",starts={{npcID=66135,x=0.586,y=0.53,mapID=10}},ends={{npcID=66135,x=0.586,y=0.53,mapID=10}},coords={x=0.586,y=0.53,source="quest_giver",mapID=10},questType="standard"},
[31821] = {id=31821,name="Level Up!",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,description="Good, good. It's important to keep your pets healthy and ready for battle. My next task for you is to fight a few battles and raise a pet to level 3. Once you do that, come back and see me and we can talk about catching your own pets!",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},ends={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
