[31834] = {id=31834,name="Begin Your Training: Master Cheng",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5841,description="Greetings, . Welcome to the Peak of Serenity. It is here that we monks train and hone our skills in the martial arts. The time has come for you to begin your training. Speak with Master Cheng in the Training Grounds below us to begin.",starts={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={x=0.486,y=0.428,source="quest_giver",zoneID=5841},questType="standard"},
[31835] = {id=31835,name="Continue Your Training: Master Kistane",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5841,description="Welcome back , the time has come for the next step of your training. Speak with Master Kistane in the Training Grounds below us for your next lesson.",starts={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={x=0.486,y=0.428,source="quest_giver",zoneID=5841},questType="standard"},
