[31871] = {id=31871,name="Traitor Gluk",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=357,mapID=69,description="You beat Gluk before, but now Gluk lay da smackdown on puny !",starts={{npcID=66352,x=0.596,y=0.496,mapID=69}},ends={{npcID=66352,x=0.596,y=0.496,mapID=69}},coords={x=0.596,y=0.496,source="quest_giver",mapID=69},questType="standard"},
[31872] = {id=31872,name="Merda Stronghoof",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=405,mapID=66,description="Just as the land continues to grow, my team is stronger than ever. Are you sure you wish to combat me? There is no shame in admitting defeat now.",starts={{npcID=66372,x=0.572,y=0.458,mapID=66}},ends={{npcID=66372,x=0.572,y=0.458,mapID=66}},coords={x=0.572,y=0.458,source="quest_giver",mapID=66},questType="standard"},
[31876] = {id=31876,name="The Inkmasters of the Arboretum",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei , if you wish to help.",starts={{npcID=64691,x=0.82,y=0.294,zoneID=5840}},ends={{npcID=56065,x=0.546,y=0.442,zoneID=5785}},coords={x=0.82,y=0.294,source="quest_giver",zoneID=5840},questType="standard"},
[31877] = {id=31877,name="The Inkmasters of the Arboretum",level=10,requiredLevel=10,faction="none",expansion=4,description="I have heard that the Inkmasters at the Arboretum are in need of aid from a scribe of great skill. You should speak with Inkmaster Wei, if you wish to help.",questType="standard"},
[31886] = {id=31886,name="Dread Space",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled such as yourself. Take a kite and check in with Bowmistress Li .",starts={{npcID=63498,x=0.56,y=0.702,zoneID=6138}},ends={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},coords={x=0.56,y=0.702,source="quest_giver",zoneID=6138},questType="standard"},
[31887] = {id=31887,name="Pet Battle Trainers: Kalimdor",level=5,requiredLevel=5,faction="alliance",expansion=4,zoneID=33,mapID=50,description="It's time to put your battle skills to a true test. You will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!",questType="standard"},
[31888] = {id=31888,name="Pet Battle Trainers: Kalimdor",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=33,mapID=50,description="It's time to put your battle skills to a true test. You will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!",questType="standard"},
[31889] = {id=31889,name="Battle Pet Tamers: Kalimdor",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=400,description="Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full. There are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade. If you are able to best them, you will be ready to venture further.",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31890] = {id=31890,name="Pet Battle Trainers: Kalimdor",level=5,requiredLevel=5,faction="none",expansion=4,zoneID=33,mapID=50,description="It's time to put your battle skills to a true test. You will find Steven Lisbane wandering the roads in the southern parts of Northern Stranglethorn. Seek him out and see who the superior tamer is!",questType="standard"},
[31891] = {id=31891,name="Battle Pet Tamers: Kalimdor",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=400,description="Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full. There are five tamers throughout Kalimdor that I'd like you to defeat: Traitor Gluk in Feralas, Grazzle the Great in Dustwallow Marsh, Kela Grimtotem in Thousand Needles, Zoltan in Felwood, and Elena Flutterfly in Moonglade. If you are able to best them, you will be ready to venture further.",starts={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},coords={x=0.524,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[31892] = {id=31892,name="Battle Pet Trainers: Kalimdor",level=0,requiredLevel=0,faction="alliance",expansion=4,zoneID=400,mapID=64,description="The very same trainers you bested before in Kalimdor have challenged you once more. No doubt they have not forgotten your last victory! Seek them out and show them your prowess!",questType="standard"},
[31894] = {id=31894,name="A Delicate Balance",level=25,requiredLevel=25,faction="both",expansion=4,zoneID=5842,description="The calling to be a Shado-pan is one to bring balance and harmony to this land. It is our duty to ensure balance is maintained, . The yaungol activity in Townlong is threatening this balance and must be stopped before it is too late. We've had sightings of yaungol in the Sumprushes. The reports indicate they are attacking the mist lurkers in the area. Find out why and put an end to it!",starts={{npcID=60864,x=0.826,y=0.73,zoneID=5842}},ends={{npcID=60857,x=0.678,y=0.676,zoneID=5842}},coords={x=0.826,y=0.73,source="quest_giver",zoneID=5842},questType="standard"},
[31895] = {id=31895,name="Better Off Dread",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=5840,description="It's time we go to the source, ! Shado-Pan marksmen keep a constant watch over the Dread Wastes from the top of the Serpent's Spine. They would surely welcome the aid of a skilled such as yourself. Seek out Bowmistress Li atop the Serpent's Spine on the border of Dread Wastes .",starts={{npcID=61584,x=0.394,y=0.62,zoneID=5842}},ends={{npcID=62112,x=0.14,y=0.77,zoneID=5840}},coords={x=0.394,y=0.62,source="quest_giver",zoneID=5842},questType="standard"},
[31897] = {id=31897,name="Grand Master Trixxy",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=618,description="Word around the master tamers in Kalimdor is you're the new hotshot that's making such a buzz. Why don't you come down to my training grounds in the Ice Thistle Hills in Winterspring so I can show you how it's done?",starts={{npcID=66466,x=0.656,y=0.644,zoneID=618}},ends={{npcID=66466,x=0.656,y=0.644,zoneID=618}},coords={x=0.656,y=0.644,source="quest_giver",zoneID=618},questType="standard"},
[31902] = {id=31902,name="Battle Pet Tamers: Eastern Kingdoms",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=46,description="Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full. There are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer , in Burning Steppes. If you are able to best them, you will be ready to venture further.",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31903] = {id=31903,name="Battle Pet Tamers: Eastern Kingdoms",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=46,description="Now that you've had a real chance to hone your skills, you're ready to venture out into the world of pet battles in full. There are five tamers throughout the Eastern Kingdoms that I'd like you to defeat: David Kosse in The Hinterlands, Deiza Plaguehorn in Eastern Plaguelands, Kortas Darkhammer in Searing Gorge, Everessa in Swamp of Sorrows, and Kortas' brother, Durin Darkhammer , in Burning Steppes.. If you are able to best them, you will be ready to venture further.",starts={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},coords={x=0.524,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[31904] = {id=31904,name="Cassandra Kaboom",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=4709,mapID=199,description="I've loaded my pets with new gyrotechnic training modules. You're going down!",starts={{npcID=66422,x=0.396,y=0.792,mapID=199}},ends={{npcID=66422,x=0.396,y=0.792,mapID=199}},coords={x=0.396,y=0.792,source="quest_giver",mapID=199},questType="standard"},
[31905] = {id=31905,name="Grazzle the Great",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=15,mapID=70,description="You're back?! You're just asking to get eaten by a black dragon!",starts={{npcID=66436,x=0.538,y=0.748,mapID=70}},ends={{npcID=66436,x=0.538,y=0.748,mapID=70}},coords={x=0.538,y=0.748,source="quest_giver",mapID=70},questType="standard"},
[31906] = {id=31906,name="Kela Grimtotem",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=400,mapID=64,description="You're so bold as to venture into the heart of Grimtotem lands once more to challenge me? You will regret your decision!",starts={{npcID=66452,x=0.318,y=0.328,mapID=64}},ends={{npcID=66452,x=0.318,y=0.328,mapID=64}},coords={x=0.318,y=0.328,source="quest_giver",mapID=64},questType="standard"},
[31907] = {id=31907,name="Zoltan",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=361,mapID=77,description="With each passing day my power grows. Resistance is futile.",starts={{npcID=66442,x=0.4,y=0.566,mapID=77}},ends={{npcID=66442,x=0.4,y=0.566,mapID=77}},coords={x=0.4,y=0.566,source="quest_giver",mapID=77},questType="standard"},
[31908] = {id=31908,name="Elena Flutterfly",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=493,mapID=80,description="I see you're ready for another bout in the skies. Let's take flight!",starts={{npcID=66412,x=0.46,y=0.604,mapID=80}},ends={{npcID=66412,x=0.46,y=0.604,mapID=80}},coords={x=0.46,y=0.604,source="quest_giver",mapID=80},questType="standard"},
[31909] = {id=31909,name="Grand Master Trixxy",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=618,mapID=83,description="Freeze! You've finally warmed up from our last encounter, have you? Let's change that.",starts={{npcID=66466,x=0.656,y=0.644,mapID=83}},ends={{npcID=66466,x=0.656,y=0.644,mapID=83}},coords={x=0.656,y=0.644,source="quest_giver",mapID=83},questType="standard"},
[31910] = {id=31910,name="David Kosse",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=47,mapID=26,description="My research has helped my training regimen greatly. I will defeat you this time.",starts={{npcID=66478,x=0.628,y=0.546,mapID=26}},ends={{npcID=66478,x=0.628,y=0.546,mapID=26}},coords={x=0.628,y=0.546,source="quest_giver",mapID=26},questType="standard"},
[31911] = {id=31911,name="Deiza Plaguehorn",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=139,mapID=23,description="You have not yet turned to the true path of undeath. Perhaps another battle will show you the way.",starts={{npcID=66512,x=0.67,y=0.524,mapID=23}},ends={{npcID=66512,x=0.67,y=0.524,mapID=23}},coords={x=0.67,y=0.524,source="quest_giver",mapID=23},questType="standard"},
[31912] = {id=31912,name="Kortas Darkhammer",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=51,mapID=32,description="I hear that you fought my fool of a brother. He lost, eh? Looks like this is my time to shine!",starts={{npcID=66515,x=0.354,y=0.278,mapID=32}},ends={{npcID=66515,x=0.354,y=0.278,mapID=32}},coords={x=0.354,y=0.278,source="quest_giver",mapID=32},questType="standard"},
[31913] = {id=31913,name="Everessa",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=8,mapID=51,description="I believe I'm figuring out the secrets of this place. Soon I will be unstoppable!",starts={{npcID=66518,x=0.766,y=0.414,mapID=51}},ends={{npcID=66518,x=0.766,y=0.414,mapID=51}},coords={x=0.766,y=0.414,source="quest_giver",mapID=51},questType="standard"},
[31914] = {id=31914,name="Durin Darkhammer",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=46,mapID=36,description="My time under the Firelord has prepared me fer anything. Nothing you can throw at me will deter me!",starts={{npcID=66520,x=0.256,y=0.476,mapID=36}},ends={{npcID=66520,x=0.256,y=0.476,mapID=36}},coords={x=0.256,y=0.476,source="quest_giver",mapID=36},questType="standard"},
[31915] = {id=31915,name="Grand Master Lydia Accoste",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=41,description="The master tamers around the Eastern Kingdoms have been talking about you. You think yourself unstoppable? You believe that you are the true grand master? Come, then, . I await you in Deadwind Pass. Come, and know the crushing defeat that's always been yours.",starts={{npcID=66522,x=0.402,y=0.764,zoneID=41}},ends={{npcID=66522,x=0.402,y=0.764,zoneID=41}},coords={x=0.402,y=0.764,source="quest_giver",zoneID=41},questType="standard"},
[31916] = {id=31916,name="Grand Master Lydia Accoste",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=41,mapID=42,description="You wish to face me again? You will regret this decision!",starts={{npcID=66522,x=0.402,y=0.764,mapID=42}},ends={{npcID=66522,x=0.402,y=0.764,mapID=42}},coords={x=0.402,y=0.764,source="quest_giver",mapID=42},questType="standard"},
[31917] = {id=31917,name="A Tamer's Homecoming",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=1519,description="Yer ready to enter the full circuit of pet battlin', matey. Go back to yer trainer, Mish Burnhep, in Stormwind, and prepare for the adventure of a lifetime!",starts={{npcID=65656,x=0.514,y=0.732,zoneID=5287}},ends={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.514,y=0.732,source="quest_giver",zoneID=5287},questType="standard"},
[31918] = {id=31918,name="A Tamer's Homecoming",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=1637,description="If you beat me, then you must be ready for da big time! Go talk to Varzok in Orgrimmar.",starts={{npcID=66422,x=0.396,y=0.792,zoneID=4709}},ends={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},coords={x=0.396,y=0.792,source="quest_giver",zoneID=4709},questType="standard"},
[31919] = {id=31919,name="Battle Pet Tamers: Outland",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=3703,description="You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying. There are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath. You must defeat them to proceed on the path to greatness.",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31920] = {id=31920,name="Grand Master Antari",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3520,description="I've seen the likes of you before. A young, naive tamer that thinks that they deserve victory handed to them on a silver platter. Well no more! I will be your reckoning, . I, Bloodknight Antari of Shadowmoon Valley, await the chance to show you how it feels to be obliterated in battle.",starts={{npcID=66557,x=0.304,y=0.418,zoneID=3520}},ends={{npcID=66557,x=0.304,y=0.418,zoneID=3520}},coords={x=0.304,y=0.418,source="quest_giver",zoneID=3520},questType="standard"},
[31921] = {id=31921,name="Battle Pet Tamers: Outland",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=3703,description="You've bested the master tamers of Kalimdor and the Eastern Kingdoms, but your next challenge will be far more trying. There are four tamers in Outland that you must now defeat: Nicki Tinytech in Hellfire Peninsula, Ras'an in Zangarmarsh, Narrok in Nagrand, and Morulu the Elder in Shattrath. You must defeat them to proceed on the path to greatness.",starts={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},coords={x=0.524,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[31922] = {id=31922,name="Nicki Tinytech",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3483,mapID=100,description="According to my calculations, I have a 32.333% chance of victory. I'll take it!",starts={{npcID=66550,x=0.62,y=0.496,mapID=71},{npcID=66550,x=0.644,y=0.492,mapID=100}},ends={{npcID=66550,x=0.62,y=0.496,mapID=71},{npcID=66550,x=0.644,y=0.492,mapID=100}},coords={x=0.62,y=0.496,source="quest_giver",mapID=100},questType="standard"},
[31923] = {id=31923,name="Ras'an",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3521,mapID=102,description="You want to fight again? I think I've gotten better!",starts={{npcID=66551,x=0.62,y=0.496,mapID=71},{npcID=66551,x=0.172,y=0.504,mapID=102}},ends={{npcID=66551,x=0.62,y=0.496,mapID=71},{npcID=66551,x=0.172,y=0.504,mapID=102}},coords={x=0.62,y=0.496,source="quest_giver",mapID=102},questType="standard"},
[31924] = {id=31924,name="Narrok",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3518,mapID=107,description="I wish to do battle once more. These young ones need to grow stronger.",starts={{npcID=66552,x=0.62,y=0.496,mapID=71},{npcID=66552,x=0.61,y=0.494,mapID=107}},ends={{npcID=66552,x=0.62,y=0.496,mapID=71},{npcID=66552,x=0.61,y=0.494,mapID=107}},coords={x=0.62,y=0.496,source="quest_giver",mapID=107},questType="standard"},
[31925] = {id=31925,name="Morulu The Elder",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3703,mapID=111,description="I have learned much since our last encounter. Do you wish to test your skills once more?",starts={{npcID=66553,x=0.62,y=0.496,mapID=71},{npcID=66553,x=0.59,y=0.7,mapID=111}},ends={{npcID=66553,x=0.62,y=0.496,mapID=71},{npcID=66553,x=0.59,y=0.7,mapID=111}},coords={x=0.62,y=0.496,source="quest_giver",mapID=111},questType="standard"},
[31926] = {id=31926,name="Grand Master Antari",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=3520,mapID=104,description="You capitalized on my mistake last time and emerged victorious. This time, you will not be so fortunate, .",starts={{npcID=66557,x=0.304,y=0.418,mapID=104}},ends={{npcID=66557,x=0.304,y=0.418,mapID=104}},coords={x=0.304,y=0.418,source="quest_giver",mapID=104},questType="standard"},
[31927] = {id=31927,name="Battle Pet Tamers: Northrend",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=66,description="Outland's finest have fallen to your skill, but Northrend now awaits you! There are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak. If you are able to best all of them, then Northrend's Grand Master will surely challenge you!",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31928] = {id=31928,name="Grand Master Payne",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=210,description="In my opinion, my fellow tamers have been far too lenient on your training. True pet taming requires militaristic discipline. I shall honor you with the pleasure of seeing firsthand what that discipline can produce. Come to the Argent Tournament Grounds in Icecrown and see firsthand what you could become!",starts={{npcID=66675,x=0.774,y=0.196,zoneID=210}},ends={{npcID=66675,x=0.774,y=0.196,zoneID=210}},coords={x=0.774,y=0.196,source="quest_giver",zoneID=210},questType="standard"},
[31929] = {id=31929,name="Battle Pet Tamers: Northrend",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=66,description="Outland's finest have fallen to your skill, but Northrend now awaits you! There are four tamers that you must now defeat: Beegle Blastfuse in Howling Fjord, Nearly Headless Jacob in Crystalsong Forest, Okrut Dragonwaste in Dragonblight, and Gutretch in Zul'Drak. If you are able to best all of them, then Northrend's Grand Master will surely challenge you!",starts={{npcID=63626,x=0.524,y=0.592,zoneID=1637}},coords={x=0.524,y=0.592,source="quest_giver",zoneID=1637},questType="standard"},
[31930] = {id=31930,name="Battle Pet Tamers: Pandaria",level=1,requiredLevel=1,faction="alliance",expansion=4,zoneID=5842,description="You must now face the toughest tamers in all of Azeroth, . They make their home in Pandaria, training ground of the grand masters. There are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes. If you think yourself ready, seek out these champions of the trade and prove yourself!",starts={{npcID=63596,x=0.692,y=0.25,zoneID=1519}},coords={x=0.692,y=0.25,source="quest_giver",zoneID=1519},questType="standard"},
[31932] = {id=31932,name="Nearly Headless Jacob",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=2817,mapID=127,description="Time and time again you defy my wisdom. What is it that brings you back to these woods? Ah, you wish to do battle once more. Very well then.",starts={{npcID=66636,x=0.62,y=0.496,mapID=71},{npcID=66636,x=0.502,y=0.59,mapID=127}},ends={{npcID=66636,x=0.62,y=0.496,mapID=71},{npcID=66636,x=0.502,y=0.59,mapID=127}},coords={x=0.62,y=0.496,source="quest_giver",mapID=127},questType="standard"},
[31933] = {id=31933,name="Okrut Dragonwaste",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=65,mapID=115,description="You dare interrupt our work? Then you must battle me again! Take out your pets, and I'll give you a taste of Hellscream's wrath!",starts={{npcID=66638,x=0.59,y=0.77,mapID=115}},ends={{npcID=66638,x=0.59,y=0.77,mapID=115}},coords={x=0.59,y=0.77,source="quest_giver",mapID=115},questType="standard"},
[31934] = {id=31934,name="Gutretch",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=440,mapID=71,description="Me like fighting you. You not so easy like the others. We fight again?",starts={{npcID=66639,x=0.132,y=0.668,mapID=121},{npcID=66639,x=0.62,y=0.496,mapID=71}},ends={{npcID=66639,x=0.132,y=0.668,mapID=121},{npcID=66639,x=0.62,y=0.496,mapID=71}},coords={x=0.132,y=0.668,source="quest_giver",mapID=71},questType="standard"},
[31935] = {id=31935,name="Grand Master Payne",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=210,mapID=118,description="The rebel comes once again to test might again that of a Grand Master. Your bravery will be your undoing this time!",starts={{npcID=66675,x=0.774,y=0.196,mapID=118}},ends={{npcID=66675,x=0.774,y=0.196,mapID=118}},coords={x=0.774,y=0.196,source="quest_giver",mapID=118},questType="standard"},
[31936] = {id=31936,name="The \"Jinyu Princess\" Irrigation System",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="\"Hey there, greenthumb. Are you pouting over parched pumpkins? Crying over crusty cabbage? Are your leeks lame and your melons melancholy? Then it's time you brought home the Jinyu Princess! She'll wash over your garden like a sweet spring rain, dousing that drought with a deep draught of...\"",ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},questType="standard"},
[31937] = {id=31937,name="\"Thunder King\" Pest Repellers",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="\"DO NOT LET WEAK, DISGUSTING INSECTS INFEST YOUR GLORIOUS CROPS. CONQUER THEM WITH THE MIGHT OF THE THUNDER KING AND PROTECT YOUR LEGACY.\"",ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},questType="standard"},
[31938] = {id=31938,name="The \"Earth-Slasher\" Master Plow",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="At his side, a stoic female - of equally impossible physique - balances a massive, overflowing cornucopia gracefully on her head while kicking a virmen in the face.> \"The Earth-Slasher. Master the land. Master your life.\"",ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},questType="standard"},
[31941] = {id=31941,name="Squash Those Foul Odors",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Grandpa always said, \"A squash a week, and your tail won't reek.\" Yup. I think it's been about a week. Could you help me plant a Jade Squash?",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[31942] = {id=31942,name="It's Melon Time",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Farmer Yoon looks up at the sky and sniffs the air.> Hmm... Yup. It's melon time. Could you grab some seeds and help me plant a Striped Melon?",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[31943] = {id=31943,name="Which Berries? Witchberries.",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="That young'un over there, Andi, is going to grow up to be a heck of a farmer some day. I can tell just by lookin' at him. I think I'll plant him some witchberries. Kids love witchberries - it'll be a nice surprise.",starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
[31944] = {id=31944,name="Complete Your Training: The Final Test",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5841,description="Welcome back, . The time has come for you to complete the last step of your training. Head to the Training Grounds for your final test.",starts={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},ends={{npcID=66260,x=0.486,y=0.428,zoneID=5841}},coords={x=0.486,y=0.428,source="quest_giver",zoneID=5841},questType="standard"},
[31945] = {id=31945,name="Learn and Grow VI: Gina's Vote",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="My business is doomed! You see all of the Ironpaws at their cooking stations? Their tasty dishes draw many of the customers to this market, but they're all out of scallions ! It may not look like much, but the scallion is an essential cooking ingredient. Without it, foods are less savory, less flavorful, and less aromatic. This is terrible. I'm not getting another scallion shipment for a week! Wait a second. You're a farmer, aren't you? You think you could help me?",starts={{npcID=58706,x=0.532,y=0.516,mapID=376}},ends={{npcID=58706,x=0.532,y=0.516,mapID=376}},coords={x=0.532,y=0.516,source="quest_giver",mapID=376},questType="standard"},
[31946] = {id=31946,name="Mung-Mung's Vote III: The Great Carrot Caper",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Mung-Mung don't care who steals carrots. Only care what Mr. Mudclaw does to poor Mung-Mung when he finds his crop is ruined! Mung-Mung rubs his chin thoughtfully.> Wait! Mung-Mung have bright idea. You go and grow some juicycrunch carrots . Then, we take your carrots and pretend they are Mr. Mudclaw's. Yes!",starts={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},ends={{npcID=57401,x=0.442,y=0.342,zoneID=5805}},coords={x=0.442,y=0.342,source="quest_giver",zoneID=5805},questType="standard"},
[31947] = {id=31947,name="Farmer Fung's Vote III: Crazy For Cabbage",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Farmer Fung is beaming with a radiant smile.> Thanks to you, I got my precious yaks back! Unfortunately, I noticed that their time out in the wild left them rather gaunt. They must be starving, but I don't feed my prize yaks just any regular old grass. No sir, they eat only the leafiest green cabbages you can find here in the Valley. My stores are a bit low. If you bring me some cabbages for my yaks, I will reward you handsomely.",starts={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},ends={{npcID=57298,x=0.482,y=0.338,zoneID=5805}},coords={x=0.482,y=0.338,source="quest_giver",zoneID=5805},questType="standard"},
[31948] = {id=31948,name="Nana's Vote II: The Sacred Springs",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="You caught me at a good time, . I was just hankering to make a fresh batch of Witchberry Julep. Have you ever heard of this wondrous brew? Each sip takes ten years off your face! How do you think I still look so good? Anyway, I need a special ingredient - thousand-year water - which can be collected from the mouth of the waterfall to the north. I'm afraid the journey is too treacherous for an old matron like me, but if you can get your hands on a pitcher, I'll let you share my brew.",starts={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},ends={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},coords={x=0.546,y=0.47,source="quest_giver",zoneID=5805},questType="standard"},
[31949] = {id=31949,name="Nana's Vote III: Witchberry Julep",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Now that we have the water, I can almost taste the icy cold witchberry julep! Now, we just need to find ourselves some sweet witchberries . My grandson's berries this season have been total slop, so I need to seek a decent harvest elsewhere. Say, do you have any witchberries in the ground this year? How about you bring me some from your farm? If your berries are up to the standard, we'll make ourselves a grand old batch of the old juice!",starts={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},ends={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},coords={x=0.546,y=0.47,source="quest_giver",zoneID=5805},questType="standard"},
[31951] = {id=31951,name="Grand Master Aki",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=9105,description="You have fought hard and well against the trainers of Azeroth. Even the grand masters have fallen to your cunning tactics. I now await you in the Vale of Eternal Blossoms, for you have earned the privilege to face me in battle. Come, , and let us see if you have what it takes to defeat me.",ends={{npcID=66741,x=0.312,y=0.742,zoneID=5840},{npcID=66741,x=0.84,y=0.286,zoneID=9105}},questType="standard"},
[31952] = {id=31952,name="Battle Pet Tamers: Pandaria",level=1,requiredLevel=1,faction="horde",expansion=4,zoneID=5842,mapID=388,description="You must now face the toughest tamers in all of Azeroth, . They make their home in Pandaria, training ground of the grand masters. There are six grand masters left to defeat: Hyuna of the Shrines in The Jade Forest, Farmer Nishi in Valley of the Four Winds, Mo'ruk in Krasarang Wilds, Courageous Yon in Kun-Lai Summit, Seeker Zusshi in Townlong Steppes, and Wastewalker Shu in Dread Wastes. If you think yourself ready, seek out these champions of the trade and prove yourself!",starts={{npcID=63626,x=0.524,y=0.592,mapID=85}},coords={x=0.524,y=0.592,source="quest_giver",mapID=388},questType="standard"},
[31953] = {id=31953,name="Grand Master Hyuna",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5785,mapID=371,description="You seek to do battle once more? Very well, it will strengthen me to better protect the sacred sites of my people.",starts={{npcID=66730,x=0.48,y=0.54,mapID=371}},ends={{npcID=66730,x=0.48,y=0.54,mapID=371}},coords={x=0.48,y=0.54,source="quest_giver",mapID=371},questType="standard"},
[31954] = {id=31954,name="Grand Master Mo'ruk",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6134,mapID=418,description="This time I'm gonna do the beating! You watch!",starts={{npcID=66733,x=0.622,y=0.458,mapID=418}},ends={{npcID=66733,x=0.622,y=0.458,mapID=418}},coords={x=0.622,y=0.458,source="quest_giver",mapID=418},questType="standard"},
[31955] = {id=31955,name="Grand Master Nishi",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5805,mapID=376,description="My pets continue to grow in strength thanks to the fertile land we train on. You don't stand a chance!",starts={{npcID=66734,x=0.46,y=0.436,mapID=376}},ends={{npcID=66734,x=0.46,y=0.436,mapID=376}},coords={x=0.46,y=0.436,source="quest_giver",mapID=376},questType="standard"},
[31956] = {id=31956,name="Grand Master Yon",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5841,mapID=379,description="If you think I am going to let you walk away with another victory in hand, you are sorely mistaken. This time, I will stand over you as the superior trainer!",starts={{npcID=66738,x=0.358,y=0.736,mapID=379}},ends={{npcID=66738,x=0.358,y=0.736,mapID=379}},coords={x=0.358,y=0.736,source="quest_giver",mapID=379},questType="standard"},
[31957] = {id=31957,name="Grand Master Shu",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6138,mapID=422,description="You venture into the heart of the wastes to face me again, only to suffer defeat at the hands of a true grand master. Noble, but foolish.",starts={{npcID=66739,x=0.55,y=0.374,mapID=422}},ends={{npcID=66739,x=0.55,y=0.374,mapID=422}},coords={x=0.55,y=0.374,source="quest_giver",mapID=422},questType="standard"},
[31958] = {id=31958,name="Grand Master Aki",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=9105,mapID=1530,description="You wish to test yourself against me once more? Very well, let us fight.",starts={{npcID=66741,x=0.312,y=0.742,mapID=1530},{npcID=66741,x=0.84,y=0.286,mapID=1530}},ends={{npcID=66741,x=0.312,y=0.742,mapID=1530},{npcID=66741,x=0.84,y=0.286,mapID=1530}},coords={x=0.312,y=0.742,source="quest_giver",mapID=1530},questType="standard"},
[31959] = {id=31959,name="The Empress' Gambit",level=30,requiredLevel=30,faction="both",expansion=4,zoneID=6138,description="Grand Empress Shek'zeer has finally lost her patience with us. We have learned of an enormous army, massing in the shadows of the Heart of Fear, with orders to crush Klaxxi'vess. We have been fortunate to hold out this long, but we cannot survive a siege of this scale. Wakener, you have been invaluable to our efforts. Come, take your place on the field among we paragons. I will see you on the battlefield!",starts={{npcID=62774,x=0.55,y=0.354,zoneID=6138}},coords={x=0.55,y=0.354,source="quest_giver",zoneID=6138},questType="standard"},
[31960] = {id=31960,name="Tracking Event: Vote #1 Complete",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5805,mapID=376,questType="standard"},
