[32038] = {id=32038,name="Stag Mastery",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="I always was a fan of a good stag hunt. Stags are tough, fast, and territorial. They may be plant eaters but they can give any hunter a run for his money. East of here is a whole mess of Wilderland Stags just waiting for a hunter like yourself to give 'em a good run. Happy hunting.",starts={{npcID=58434,x=0.158,y=0.822,zoneID=5805}},ends={{npcID=58434,x=0.158,y=0.822,zoneID=5805}},coords={x=0.158,y=0.822,source="quest_giver",zoneID=5805},questType="standard"},
