[32045] = {id=32045,name="Children of the Water",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="We are all children of the water here in the Valley of the Four Winds . It nourishes us, it grows our vegetables, it brings us life. Some creatures, however, drink too deeply from the water. They grow too large, and must be eliminated before they cause havoc to those around them. I am but a simple stonecarver. You, on the other hand...",starts={{npcID=64315,x=0.552,y=0.474,zoneID=5805}},ends={{npcID=64315,x=0.552,y=0.474,zoneID=5805}},coords={x=0.552,y=0.474,source="quest_giver",zoneID=5805},questType="standard"},
