[32105] = {id=32105,name="Pristine Monument Ledger",level=10,requiredLevel=10,faction="none",expansion=4,description="This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.",questType="standard"},
[32106] = {id=32106,name="A Winter Veil Gift",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=1637,mapID=85,starts={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},ends={{npcID=187236,x=0.335,y=0.66,mapID=87},{npcID=187236,x=0.494,y=0.775,mapID=85}},coords={x=0.335,y=0.66,source="quest_giver",mapID=85},questType="standard"},
[32107] = {id=32107,name="Flying Tiger Gourami",level=15,requiredLevel=15,faction="none",expansion=4,zoneID=6006,mapID=379,description="You've caught a unique fish... with wings. Perhaps it deserves the expert opinion of Nat Pagle in Anglers Wharf.",questType="standard"},
[32108] = {id=32108,name="Domination Point",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Now it is time to show this new land the true strength of the Horde. Return to the beach and light the remaining signal fire . Our fleet is waiting.",ends={{npcID=216274,x=0.085,y=0.638,zoneID=6134}},questType="standard"},
[32109] = {id=32109,name="Lion's Landing",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="For too long the Horde has been allowed to run rampant across Azeroth. I will not see these new lands conquered by some barbaric \"warchief.\" Are you ready to bring Alliance justice to the shores of Pandaria? Let us return to the landing site. Use the flare launcher to bring in the fleet proper, and begin Operation: Shieldwall .",ends={{npcID=216609,x=0.856,y=0.291,zoneID=6134}},questType="standard"},
[32112] = {id=32112,name="FLAG - Been to Fight Club",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[32113] = {id=32113,name="FLAG - Been to Fight Club Today",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6138,mapID=422,questType="standard"},
[32114] = {id=32114,name="So, You Wanted to Test Daily Quests?",level=1,requiredLevel=1,faction="both",expansion=4,description="You wanna test dailies? Well alright then.",questType="standard"},
[32115] = {id=32115,name="Shackles of the Past",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The mogu are a bunch of right bastards! They enslaved the pandaren who worked these caves even after their death. Ye' gotta go free their spirits! It's just not right. Be careful though... so much trauma, they don't know what's a friend and what's an enemy. So they'll probably fight back.",starts={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},ends={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},coords={x=0.802,y=0.164,source="quest_giver",zoneID=6134},questType="standard"},
[32116] = {id=32116,name="Priorities, People!",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="When I ordered the excavation of the tunnel to the northwest, I thought we'd find something useful. Gold, iron... anything! Instead, we found mogu artifacts, and I get a bunch of dwarves from the Explorers' League to baby-sit. I hear from the soldiers that there's trouble in the mines. I have orders from Wrynn that I have to support the Explorers' League, but I can't spare any troops. Can you get down there and find out what's going on?",starts={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},ends={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},coords={x=0.896,y=0.33,source="quest_giver",zoneID=6134},questType="standard"},
[32118] = {id=32118,name="Taking Advantage",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The fools in the Explorers' League have excavated an ancient mogu ruin to the northeast. And - of course - in their bumbling, they've disturbed the mogu spirits within. We are going to take advantage of their ineptitude. Take this portal and meet with Kaelis Sunsoar , my contact within the ruins.",questType="standard"},
[32119] = {id=32119,name="It Is A Mystery",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="There's somethin' down there that was spookin' the workers. Some kind o' anomaly... looks like a ghost, or a magic spell... like nothing I've ever seen. I did manage to get a reading on it and put together this device to try to track it down. The display on the device will let you know roughly how close you are. Once you get close enough, you can use it to draw out the anomaly and get rid of it for good!",starts={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},ends={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},coords={x=0.802,y=0.164,source="quest_giver",zoneID=6134},questType="standard"},
[32120] = {id=32120,name="Legacy of Ogudei",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The ruins which we are occupying were built by Ogudei - an ancient mogu ruler. We know little about who he was, though the rise of the spirits in this area seems to indicate that it was related to spirit binding. When you destroy these spirits, a small amount of their essence will remain in this world. Bring it to us - we will analyze it and hopefully learn more about Ogudei's history - and his power.",questType="standard"},
[32121] = {id=32121,name="The Spirit Trap",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="In the ruins there are a bunch of right nasty blue crystals. Look at 'em the wrong way and bloody angry ghosts run out at ya. I'm gonna be needing ye' to go in and clear some of them out so we can get our people back to work.",starts={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},ends={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},coords={x=0.802,y=0.164,source="quest_giver",zoneID=6134},questType="standard"},
[32122] = {id=32122,name="Ogudei's Lieutenants",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="When we dug through to an ancient section of the mogu ruins, that's when all this nasty business went down - and that's where the two worst o' these ghosties emerged. We need them gone, friend.",starts={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},ends={{npcID=68275,x=0.802,y=0.164,zoneID=6134},{npcID=68275,x=0.312,y=0.27,zoneID=6134}},coords={x=0.802,y=0.164,source="quest_giver",zoneID=6134},questType="standard"},
[32123] = {id=32123,name="Death on Two Legs",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The Alliance has made landfall. If we do not defeat them here, any hope of a Horde presence on this continent is lost. Go to the battlefield south of here and slay Alliance you find. Show them how any Horde who still stands on two legs will be the death of ten Alliance!",starts={{npcID=67618,x=0.102,y=0.556,zoneID=6134}},ends={{npcID=67618,x=0.102,y=0.556,zoneID=6134}},coords={x=0.102,y=0.556,source="quest_giver",zoneID=6134},questType="standard"},
[32126] = {id=32126,name="Tear It Up",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The Alliance may be cowardly, but they are not fools. Their assault would be formidable, if it were directed at lesser creatures. To sustain a siege and put pressure on our troops they are air dropping in supplies to support their ground forces. Search the beaches and docks to the south for any airdropped supplies and smash them. Let the Alliance see their food and ammunition destroyed before their eyes and despair.",starts={{npcID=67767,x=0.102,y=0.538,zoneID=6134}},ends={{npcID=67767,x=0.102,y=0.538,zoneID=6134}},coords={x=0.102,y=0.538,source="quest_giver",zoneID=6134},questType="standard"},
[32127] = {id=32127,name="All Dead, All Dead",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Our Warchief has dispatched me to these shores to deal with this pitiful Alliance threat. These humans and their allies have proven to be very dependent on their leaders. No initiative of their own. As you walk the battlefield today look to the Alliance ships off our southern shores. Find their captains. Slay them. For the Horde!",starts={{npcID=67767,x=0.102,y=0.538,mapID=418}},ends={{npcID=67767,x=0.102,y=0.538,mapID=418}},coords={x=0.102,y=0.538,source="quest_giver",mapID=418},questType="standard"},
[32128] = {id=32128,name="Another One Bites the Dust",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The Alliance have planted themselves off our southern coast and continue to pepper our ground forces with cannon fire. Let us see how great their siege is without such support. Board the enemy vessels and destroy their reserve ammunition. This will take the teeth out of their bite.",starts={{npcID=67880,x=0.1,y=0.538,zoneID=6134}},ends={{npcID=67880,x=0.1,y=0.538,zoneID=6134}},coords={x=0.1,y=0.538,source="quest_giver",zoneID=6134},questType="standard"},
[32129] = {id=32129,name="Defense Daily 06",level=15,requiredLevel=15,faction="horde",expansion=4,questType="standard"},
[32130] = {id=32130,name="Good Luck, Have Fun",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="I've got some customers lined up that wanna collect some good old fashioned ears. But not any old ears. They only want the absolute waxiest ears money can buy! Guess they think they're lucky or something'. Anyways, I need you to go get 'em for me. I don't want to hurt any animals, so you'll need to get 'em from the Alliance over at Lion's Landing. Have fun - and remember, only bring me the waxiest!",starts={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},ends={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=6134},questType="standard"},
[32131] = {id=32131,name="We Require More Minerals!",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Gnomes are excavating a stone quarry to the northeast. They're building stuff with it! They're too stupid to realize it's special mogu stone for creating animated statues. WE can mix with a little Goblin magic juice to make some real big explosions! But the stuff is heavy. They've got some of their stupid bomb-bots there for excavating the stone. Blow 'em up near slabs and you'll get chunks small enough to carry. Or, just kill 'em and take it. Whatever works.",starts={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},ends={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=6134},questType="standard"},
[32132] = {id=32132,name="Worker Harassment",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6609,description="Our goblin friends do not have the grasp of strategy necessary to win a long term engagement, I'm afraid. The key to eliminating any permanent establishment is to attack their ability to replenish their troops and to rebuild. In this case, that means taking out their Peasants. Kill them, and you weaken the foundation. The rest of the keep is bound to crumble.",starts={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},ends={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},coords={x=0.758,y=0.344,source="quest_giver",zoneID=6134},questType="standard"},
[32133] = {id=32133,name="Sentry Wards",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="We've spotted heavy air support over their base, in the form of way too many dwarves on way too many griffons. Means we can't get any vision of the area from above. A troll... friend of mine gave us a set of Sentry Wards, which we can use to spy on their base and get a vantage point on what's going on in there. Bad news, friend - you're going to be the one going in there.",starts={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},ends={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},coords={x=0.758,y=0.344,source="quest_giver",zoneID=6134},questType="standard"},
[32134] = {id=32134,name="Hard Counter",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="We've managed to get some Demolishers on the beach, but the stupid dwarves are also out there with their stupid mortar tubes, preventing the Demolishers from pushing forward and assaulting the keep itself! Get out there, kill some dwarves, and blow up some mortar tubes.",starts={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},ends={{npcID=67402,x=0.758,y=0.342,zoneID=6134}},coords={x=0.758,y=0.342,source="quest_giver",zoneID=6134},questType="standard"},
[32135] = {id=32135,name="Hero Killer",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="There are some situations in which taking out one of their soldiers is more important than killing hundreds. They've deployed some of their heroes to the battlefield to help rally their defenders. Not only will killing them soften their defense, it will also leave their morale crippled. So go, take one down for me. You can handle it.",starts={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},ends={{npcID=67628,x=0.758,y=0.344,zoneID=6134}},coords={x=0.758,y=0.344,source="quest_giver",zoneID=6134},questType="standard"},
[32136] = {id=32136,name="Work Order: Fuel",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Our fuel supplies are running low. Without fuel we won't be able to operate the machinery that's building this place. They might even expect me to start helping them build! I was not built for manual labor! See these nails?! I just had them done! Get down to the refinery and get this fuel order filled! Hurry! They were fitting me for a tool-belt this morning. It didn't even match my outfit!",starts={{npcID=67535,x=0.136,y=0.558,zoneID=6134}},ends={{npcID=67542,x=0.254,y=0.604,zoneID=6134}},coords={x=0.136,y=0.558,source="quest_giver",zoneID=6134},questType="standard"},
[32137] = {id=32137,name="Runnin' On Empty",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="I've never seen this quality of oil! Problem is the oil needed a little extra refinin'. I heard of this system where you use ocean water to speed up the process. I don't have time to waste down here, so I just threw the barrels into the bay. Pretty good idea, I know. Problem is, I'm not sure how to pull it out of the bay... Maybe someone of your expertise could help me out.",starts={{npcID=67542,x=0.254,y=0.604,zoneID=6134}},ends={{npcID=67535,x=0.136,y=0.558,zoneID=6134}},coords={x=0.254,y=0.604,source="quest_giver",zoneID=6134},questType="standard"},
[32138] = {id=32138,name="Work Order: Lumber",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,mapID=418,description="Everyday it's the same thing! \"We're out of this!\", \"We need more of that!\", \"Why don't you ever do anything?!\" I work! I do things! They can be so hurtful! I'm doin' my best down here! Oh yeah, we need more lumber! Go down and tell that good for nothin' Zino to get his shredders in gear!",starts={{npcID=67535,x=0.136,y=0.558,mapID=418}},ends={{npcID=67534,x=0.204,y=0.58,mapID=418}},coords={x=0.136,y=0.558,source="quest_giver",mapID=418},questType="standard"},
[32139] = {id=32139,name="Stacked!",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="We just filled an order this morning. How could they possibly need more already?! My team has been workin' double-time to get these trees chopped and processed. Problem is we have an infestation of Lion's Landing troops down here. I already risked my neck once today, I'm not goin' back out there! Goob will go with you and help you fill this order. He's not the brightest, but he can do the heavy liftin'.",starts={{npcID=67534,x=0.204,y=0.58,zoneID=6134}},ends={{npcID=67534,x=0.204,y=0.58,zoneID=6134}},coords={x=0.204,y=0.58,source="quest_giver",zoneID=6134},questType="standard"},
[32140] = {id=32140,name="Work Order: Iron",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="When they said they found some amazing rocks in that mine I envisioned diamonds. Everyone knows all mines have diamonds, silly! At the very least rubies! Instead, all I got was this strange iron! What am I supposed to do with this? Oh well, no one said this job would be glamorous. I just do what I can to add a little class. We just got another work order for iron. Go see Daxil down near Oregrind's Dig and get it filled pronto!",starts={{npcID=67535,x=0.136,y=0.558,zoneID=6134}},ends={{npcID=67537,x=0.226,y=0.622,zoneID=6134}},coords={x=0.136,y=0.558,source="quest_giver",zoneID=6134},questType="standard"},
[32141] = {id=32141,name="Power Metal",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Sometimes we dig too deep, . Sometimes, we uncover something so horrible we wish we hadn't started diggin'... Just kidding! I mean, don't get me wrong, we did find something unexpected. The ore we're finding down there is not your average run-of-the-mill iron. There is just one problem; Shale Spiders! We're struggling to keep these orders filled. Maybe you can lend us a hand?",starts={{npcID=67537,x=0.226,y=0.622,zoneID=6134}},ends={{npcID=67535,x=0.136,y=0.558,zoneID=6134}},coords={x=0.226,y=0.622,source="quest_giver",zoneID=6134},questType="standard"},
[32142] = {id=32142,name="We Will Rock You",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The orcs can NOT be allowed a foothold in this land. They will defile it just as they did Kalimdor. $p, I need boots on the ground and horde in their graves. Get down to the coastline and bring the full force of Alliance wrath down on their heads! Slay any orcs you find. Take the wind out of their sails. For the King!",starts={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},ends={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},coords={x=0.164,y=0.792,source="quest_giver",zoneID=6134},questType="standard"},
[32143] = {id=32143,name="A Kind of Magic",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Greetings $p! I have heard a lot about your success in the field. I would like to use your services to test my latest \"Siege-o-Matic\", a device of terrible and varied abilities. I promise it is mostly harmless to its users. When you are around Domination Point be on the look out for my Scout-o-Meters. They have been dispatched to get info on good siege targets. When you find one, activate it and I will pilot a Siege-o-Matic to your location. See you in the field... as it were.",starts={{npcID=67976,x=0.164,y=0.792,zoneID=6134}},coords={x=0.164,y=0.792,source="quest_giver",zoneID=6134},questType="standard"},
[32144] = {id=32144,name="Under Pressure",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The Horde are consumed by pride and will fight to the death without a second thought. We need to find a way to break their will that does not involve massive loss of our numbers. Look for the Horde supplies along the coastline and near their ships. Smash their supplies. Nothing breaks the will of a defender like seeing their hope of food go up in a puff of smoke. When you are done, find Sully behind enemy lines. He has the next task for you.",starts={{npcID=67444,x=0.166,y=0.786,zoneID=6134}},ends={{npcID=67444,x=0.166,y=0.786,zoneID=6134}},coords={x=0.166,y=0.786,source="quest_giver",zoneID=6134},questType="standard"},
[32145] = {id=32145,name="Don't Lose Your Head",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="My probes have detected three very dangerous targets in the courtyard of Domination Keep. They have an ogre emissary, a Kor'kron officer, and an insane goblin bomb maker. My siege-o-matics are not ready for one on one combat so it is up to you to eliminate the targets. Good luck! Report back to me on the Skyfire when done.",starts={{npcID=67528,x=0.878,y=0.324,zoneID=6134}},ends={{npcID=67976,x=0.164,y=0.792,zoneID=6134}},coords={x=0.878,y=0.324,source="quest_giver",zoneID=6134},questType="standard"},
[32146] = {id=32146,name="Hammer to Fall",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="It looks like the Horde thinks they can hide behind their heavy hitting mooks. The mooks are tough, powerful, and dumber than an ogre with a hangover. Go down there and bring the hammer of the Alliance fury down on them!",starts={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},ends={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},coords={x=0.164,y=0.792,source="quest_giver",zoneID=6134},questType="standard"},
[32147] = {id=32147,name="Attack Daily 06",level=15,requiredLevel=15,faction="alliance",expansion=4,questType="standard"},
[32148] = {id=32148,name="Attack! Move!",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Sure, they've got about plenty of grunts out there, pounding on our door, waiting to cut our heads off. I'm not worried about grunts. But they've got shamans and raiders, too. The shamans use their magic to empower the grunts, and the raiders are fast and specialize in taking out our buildings. I need you to get out there and kill some of those shamans and raiders. Go! Attack! Move!",starts={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},ends={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},coords={x=0.896,y=0.33,source="quest_giver",zoneID=6134},questType="standard"},
[32149] = {id=32149,name="Resource Gathering",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Oh, the poor peasants... They are cowards, yes, of course. But they don't know how to fight, and they go out to collect lumber for our efforts... the Horde targets them... It's just awful all around! But, we need that lumber if we're going to hold out. Go out and collect any they've dropped.",starts={{npcID=67630,x=0.896,y=0.328,zoneID=6134}},ends={{npcID=67630,x=0.896,y=0.328,zoneID=6134}},coords={x=0.896,y=0.328,source="quest_giver",zoneID=6134},questType="standard"},
[32150] = {id=32150,name="Supply Block",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The Horde decided to put goblins in charge of their logistics. And where you have goblins, you have carelessly placed explosives. Scouts have reported that they have their supplies in carts that also contain demolisher ammunition. Look at those crates the wrong way, and they'll blow sky high. With enough Horde resources destroyed, we'll put a time limit on their attack and save lives. So go and take out those carts!",starts={{npcID=67630,x=0.896,y=0.328,zoneID=6134}},ends={{npcID=67630,x=0.896,y=0.328,zoneID=6134}},coords={x=0.896,y=0.328,source="quest_giver",zoneID=6134},questType="standard"},
[32151] = {id=32151,name="Tower Defense",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The gnomes are running our quarry operation to the northwest. The stone there is especially tough - the gnomes tell me the mogu used it to fashion their constructs. I don't know. What I do know is that we use that stone to build our towers, and the Horde has dispatched the Bilgewater goblins to steal it from us. Get out there and get some back. By the way - collateral damage may break up the stone slabs there. If so, pick that up, too.",starts={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},ends={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},coords={x=0.896,y=0.33,source="quest_giver",zoneID=6134},questType="standard"},
[32152] = {id=32152,name="Siege Damage",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The Horde got the bright idea to send Bilgewater goblins to attack our quarry. They've been packing heavy explosives - heavy explosives that will react with the ammunition in their demolishers. Kill the Bilgewater goblins until you find an explosive, plant it on one of the demolishers... and BOOM! Siege ended.",starts={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},ends={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},coords={x=0.896,y=0.33,source="quest_giver",zoneID=6134},questType="standard"},
[32153] = {id=32153,name="Hero Killer",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Look, you're tough. Tougher than the rest of the men and women I've got here. Which means I need you for a special mission. The Horde is throwing their best against us. Heroes of their armies - Blademasters, Tauren Chieftans, you name it. I need you to go take one out. It'll be a huge blow, not just to their offensive but also to morale.",starts={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},ends={{npcID=67631,x=0.896,y=0.33,zoneID=6134}},coords={x=0.896,y=0.33,source="quest_giver",zoneID=6134},questType="standard"},
[32154] = {id=32154,name="Burn Out!",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,mapID=418,description="Those goblins are gettin' out of hand! First they level the forest and set up that abomination of a rig. Then, they start dumpin' their oil barrels into the bay! We got to put a stop to this madness! At the very least we need ta set them back. We need to take out their fuel supply! Maybe you'll even get to kill a few goblins in the process!",starts={{npcID=68166,x=0.168,y=0.786,mapID=418}},ends={{npcID=68166,x=0.168,y=0.786,mapID=418}},coords={x=0.168,y=0.786,source="quest_giver",mapID=418},questType="standard"},
[32155] = {id=32155,name="Necessary Breaks",level=1,requiredLevel=1,faction="alliance",expansion=4,description="It goes against me nature to break things on purpose, but in this case it's necessary. That rig the goblins are usin' is held together by a wish an' some bubblegum. We need to exploit the situation a little more. We have some saboteurs down there already, but we can use someone of your expertise to hurry the job along. Get down there an' start breakin' and stealin' some valves!",questType="standard"},
[32156] = {id=32156,name="It's Only Right",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="This is barbaric warfare, ! We've lost so many trying to keep the Bilgewater operation from spreading any further. Those fallen soldiers fought honorably and deserved to be given their last rights. At the very least we need to be able to notify their next of kin. Perhaps you can collect their identification tags so we can honor them in some small way.",starts={{npcID=67444,x=0.166,y=0.786,zoneID=6134}},ends={{npcID=67444,x=0.166,y=0.786,zoneID=6134}},coords={x=0.166,y=0.786,source="quest_giver",zoneID=6134},questType="standard"},
[32157] = {id=32157,name="The Only Good Goblin...",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="The destruction in Krasarang is unforgivable, . The only way to put an end to this is to destroy the Bilgewater operation. This is for the greater good of Pandaria and the Alliance. Go to Bilgewater Beach and cut them down! No doubt the Horde will come to their assistance. Destroy them!",starts={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},ends={{npcID=67386,x=0.164,y=0.792,zoneID=6134}},coords={x=0.164,y=0.792,source="quest_giver",zoneID=6134},questType="standard"},
[32158] = {id=32158,name="Two Step Program",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Shredmaster Packle is responsible for much of the devastation down there, . Rumor has it he modified the shredders to work more quickly with less regard for the collateral damage they can inflict. Imagine the agony the trees must endure being hacked at. It will be difficult to recover from this level of destruction. The first step in any recovery is acknowledging the problem. Step two is eliminating that problem.",starts={{npcID=68182,x=0.166,y=0.786,zoneID=6134}},ends={{npcID=68182,x=0.166,y=0.786,zoneID=6134}},coords={x=0.166,y=0.786,source="quest_giver",zoneID=6134},questType="standard"},
[32159] = {id=32159,name="Circle of Life",level=1,requiredLevel=1,faction="alliance",expansion=4,description="We should attempt to offset the destruction being wrought on this continent as much as possible. For every tree they destroy, we will plant a new one! Take these seeds and begin the regrowth process, . Do not linger for too long though. Nature is unpredictable, and no doubt the anger and hate exuding from Domination Point has seeped into the ground. I cannot guarantee that the plant that springs from these seeds will not be hostile.",questType="standard"},
[32161] = {id=32161,name="Beastmaster's Hunt: The Crane",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Along with the snare, you get some advice on crane hunting: The greatest cranes of the Krasarang Wilds are not tempted by simple things like food. You will need to play on the creatures' emotions if you wish to draw them from their hiding places in the jungle. Cranes abound on both the Cradle of Chi-ji and the Narsong Spires, both of which can be found east of here. Pluck those cranes' quills, then place them in a visible spot near the Crane Temple. Your quarry will come running to you.",ends={{npcID=216161,x=0.392,y=0.62,zoneID=6134}},questType="standard"},
[32162] = {id=32162,name="Beastmaster's Hunt: The Tiger",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6138,description="Along with the trap, you get some advice on tiger hunting: Tigers are gluttonous creatures, and large game is hard to come by in this jungle. If you wish to tempt the most elder cats out of their hiding places, you may do so with a meal. Just on the other side of the Serpent's Spine, you will find a herd of yaks. Slay them, bring their meat to the jungle's edge, set up your trap, and wait.",ends={{npcID=216162,x=0.138,y=0.413,zoneID=6134}},questType="standard"},
[32163] = {id=32163,name="Beastmaster's Hunt: The Crab",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="Along with the crate, you get some advice on crab hunting: Crabs are strange, primordial creatures, with wildly different motivations than you or I. Small crabs are easy to find and hunt, but the large ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell. The Unga villagers to the southeast allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.",ends={{npcID=216163,x=0.563,y=0.421,zoneID=6134}},questType="standard"},
[32164] = {id=32164,name="Beastmaster's Hunt: The Crane",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Along with the snare, you get some advice on crane hunting: The greatest cranes of the Krasarang Wilds don't care about simple things like food. You need to play on the creatures' emotions if you want to draw them out of the jungle. There's plenty of cranes on the Cradle of Chi-ji and on the Narsong Spires, both to the west of here. Pluck some of those cranes' quills, then put them in a visible spot near the Crane Temple. Your quarry will come running to you.",ends={{npcID=216161,x=0.392,y=0.62,zoneID=6134}},questType="standard"},
[32165] = {id=32165,name="Beastmaster's Hunt: The Tiger",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6138,description="Along with the trap, you get some advice on tiger hunting: Tigers are gluttons, and big game is hard to come by in this jungle. If you want to tempt the elder cats out of their hiding places, you need a tempting meal. Just on the other side of the Serpent's Spine, you can find a herd of yaks. Kill them, bring their meat to the jungle's edge, set up your trap, and wait.",ends={{npcID=216162,x=0.138,y=0.413,zoneID=6134}},questType="standard"},
[32166] = {id=32166,name="Beastmaster's Hunt: The Crab",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=6134,description="Along with the crate, you get some advice on crab hunting: Crabs are strange, old creatures, with different motivations than us. Small crabs are easy to find and hunt, but the big ones hide beneath the sands, out of danger and out of our reach. To draw them out, we play on their sense of smell. The Unga villagers to the southwest allow their fish to ferment before they eat them. Bring enough rotten fish together, and you will catch yourself a colossal crab.",ends={{npcID=216163,x=0.563,y=0.421,zoneID=6134}},questType="standard"},
[32167] = {id=32167,name="Ancient's Fall",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The crane has fallen.",ends={{npcID=67447,x=0.126,y=0.626,zoneID=6134}},questType="standard"},
[32168] = {id=32168,name="End of an Elder",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The tiger has fallen.",ends={{npcID=67447,x=0.126,y=0.626,zoneID=6134}},questType="standard"},
