[32174] = {id=32174,name="Build Portal 01",level=15,requiredLevel=15,faction="alliance",expansion=4,questType="standard"},
[32175] = {id=32175,name="Darkmoon Pet Battle!",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="Are you prepared to test the mettle of your pets...?",starts={{npcID=67370,x=0.472,y=0.626,zoneID=5861}},ends={{npcID=67370,x=0.472,y=0.626,zoneID=5861}},coords={x=0.472,y=0.626,source="quest_giver",zoneID=5861},questType="standard"},
[32181] = {id=32181,name="Beastmaster's Quarry: The Crane",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The ancient crane is alive, but stunned. You should bring it back to Jorn Skyseer before it wakes up.",starts={{npcID=67436,x=0.122,y=0.626,zoneID=6134}},ends={{npcID=67447,x=0.126,y=0.626,zoneID=6134}},coords={x=0.122,y=0.626,source="quest_giver",zoneID=6134},questType="standard"},
[32182] = {id=32182,name="Beastmaster's Quarry: The Tiger",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The elder cat is alive, but stunned. You should bring it back to Jorn Skyseer before it wakes up.",ends={{npcID=67447,x=0.126,y=0.626,zoneID=6134}},questType="standard"},
[32183] = {id=32183,name="Beastmaster's Quarry: The Crab",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=6134,description="The colossal crab is alive, but stunned. You should bring it back to Jorn Skyseer before it wakes up.",ends={{npcID=67447,x=0.126,y=0.626,zoneID=6134}},questType="standard"},
