[32617] = {id=32617,name="A Mountain of Giant Dinosaur Bones",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=6661,starts={{npcID=70022,x=0.326,y=0.544,zoneID=6661}},ends={{npcID=70022,x=0.326,y=0.544,zoneID=6661}},coords={x=0.326,y=0.544,source="quest_giver",zoneID=6661},questType="standard"},
[32618] = {id=32618,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=12,mapID=37,description="It's time for you to learn how to ride! Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest. Don't forget to buy your mount while you are there!",ends={{npcID=4732,x=0.842,y=0.65,mapID=37}},questType="standard"},
[32621] = {id=32621,name="Lightning Steel",level=32,requiredLevel=32,faction="both",expansion=4,zoneID=6507,description="Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?",ends={{npcID=218637,x=0.6,y=0.283,zoneID=6507}},questType="standard"},
[32622] = {id=32622,name="Intro Flight",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32626] = {id=32626,name="Loot Room Key Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=6507,mapID=504,questType="pvp"},
[32627] = {id=32627,name="Charged Moganite",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here. They have not returned, and I can confirm they have left the Sunreaver base. Search the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32628] = {id=32628,name="Tactical Mana Bombs",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Ah, $p, just the I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest. Here, take these. It is time to give the Sunreavers a taste of their own medicine. Plant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32629] = {id=32629,name="Thunderwing Captured Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=6507,mapID=504,questType="standard"},
[32631] = {id=32631,name="High Recognition",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32632] = {id=32632,name="Made for War",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction. A massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32633] = {id=32633,name="Spellbound",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Grand Magister Rommath has something in his possession that I want. He brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands. Locate Rommath's book of incantations and bring it to me.",starts={{npcID=67994,x=0.634,y=0.734,mapID=504}},ends={{npcID=67994,x=0.634,y=0.734,mapID=504}},coords={x=0.634,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32634] = {id=32634,name="Breaking Down the Defenses",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Even the strongest defense can still have a weakness, . We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible. Scouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly. Disabling them would allow us to keep closer watch on their activities.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32635] = {id=32635,name="Enough with the Bombs!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated. Look for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32636] = {id=32636,name="Captive Audience",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreavers will stoop to even the lowest levels to get what they want, . I received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this. Hopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32637] = {id=32637,name="Overpowered",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain. I think it would be wise to investigate their camp to see if you can find the source of this extra power. Once you find it, use this crystal to overload and destroy it.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",mapID=504},questType="pvp"},
[32638] = {id=32638,name="Mana Scavengers",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Sometimes, even the smallest creatures can be the biggest threat. The Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them. They must be dealt with and quickly.",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32639] = {id=32639,name="Deconstruction",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory. If left unchecked they will pose a considerable threat should the Sunreavers mount an attack. The only answer is a preemptive strike. We'll destroy them before they can attack us!",starts={{npcID=67995,x=0.626,y=0.734,mapID=504}},ends={{npcID=67995,x=0.626,y=0.734,mapID=504}},coords={x=0.626,y=0.734,source="quest_giver",mapID=504},questType="pvp"},
[32640] = {id=32640,name="Champions of the Thunder King",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities. If you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them. Find and destroy members of each group to keep them destabilized, and I will make it worth your time.",starts={{npcID=70160,x=0.514,y=0.46,mapID=504}},ends={{npcID=70160,x=0.514,y=0.46,mapID=504}},coords={x=0.514,y=0.46,source="quest_giver",mapID=504},questType="group"},
[32641] = {id=32641,name="Champions of the Thunder King",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,description="This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities. If you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them. Find and destroy members of each group to keep them destabilized, and I will make it worth your time.",starts={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},ends={{npcID=70160,x=0.514,y=0.46,zoneID=6507}},coords={x=0.514,y=0.46,source="quest_giver",zoneID=6507},questType="group"},
[32642] = {id=32642,name="Work Order: Dominance Offensive I",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,starts={{npcID=218750,x=0.522,y=0.487,zoneID=5805}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32643] = {id=32643,name="Work Order: Dominance Offensive II",level=15,requiredLevel=15,faction="horde",expansion=4,zoneID=5805,description="Once your red blossom leeks are ready to be picked, you'll need only to package them for pick-up. Just think; your red blossom leeks will be a part of your faction's efforts in Pandaria!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32644] = {id=32644,name="The Assault on Shaol'mara",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,description="Our scouting efforts along the coast have given us valuable intelligence about the island, . However, we will accomplish nothing if we do not advance forward onto the mainland. I have assembled a team of our most elite aerial units to begin the attack. I would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment. When you are ready to begin the attack, speak to me.",starts={{npcID=67992,x=0.632,y=0.722,zoneID=6507},{npcID=70370,x=0.346,y=0.894,zoneID=6507}},ends={{npcID=67992,x=0.632,y=0.722,zoneID=6507}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32645] = {id=32645,name="Work Order: Operation: Shieldwall I",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32646] = {id=32646,name="Work Order: Operation: Shieldwall II",level=15,requiredLevel=15,faction="alliance",expansion=4,zoneID=5805,description="Once your witchberries are ready to be picked, you'll need only to package them for pick-up. Just think; your witchberries will be a part of your faction's efforts in Pandaria!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32647] = {id=32647,name="Work Order: Golden Lotus I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,starts={{npcID=218750,x=0.522,y=0.487,zoneID=5805}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32648] = {id=32648,name="Work Order: Golden Lotus II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Well, hopefully these crops will be suitable! Once your white turnips are ready to be picked, you'll need only to package them for pick-up.",starts={{npcID=218765,x=0.517,y=0.487,mapID=376}},ends={{npcID=218765,x=0.517,y=0.487,mapID=376}},coords={x=0.517,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32649] = {id=32649,name="Work Order: Shado-Pan I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32650] = {id=32650,name="Work Order: Shado-Pan II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Well, your work is done for the day! Now to wait for the harvest tomorrow. Once your green cabbages are ready to be picked, you'll need only to package them for pick-up. Only the finest cabbage will do for the Shado-Pan!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32652] = {id=32652,name="To the Skies!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari. Speak to me when you're ready to learn more.",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504},{npcID=69741,x=0.632,y=0.738,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32653] = {id=32653,name="Work Order: The August Celestials I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,starts={{npcID=218750,x=0.522,y=0.487,zoneID=5805}},coords={x=0.522,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32654] = {id=32654,name="Tear Down This Wall!",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon. I suppose we'll have to make a gate of our own then. Let me know when you're ready, .",starts={{npcID=67992,x=0.632,y=0.722,zoneID=6507}},ends={{npcID=67992,x=0.632,y=0.722,zoneID=6507}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32655] = {id=32655,name="A Bold Idea",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6507,mapID=504,description="Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army. If we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure. I have a plan to do just that, and it won't take an entire army.",starts={{npcID=70297,x=0.632,y=0.738,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.738,source="quest_giver",mapID=504},questType="standard"},
[32656] = {id=32656,name="The Fall of Shan Bu",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=6677,description="Lei Shen found a clutch of rare storm dragon eggs early in his campaign. One - known as Nalak - was particularly brutal and killed all of its handlers, so he took it for his own. Now, Shan Bu , one of Lei Shen's most loyal servants, works to resurrect the dragon. It is time for us to strike against Shan Bu ! Speak to me when you are ready to launch the assault!",starts={{npcID=67992,x=0.632,y=0.722,mapID=504}},ends={{npcID=67992,x=0.632,y=0.722,mapID=504}},coords={x=0.632,y=0.722,source="quest_giver",zoneID=6507},questType="standard"},
[32657] = {id=32657,name="Work Order: The August Celestials II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Once your striped melons are ready to be picked, you'll need only to package them for pick-up. A trainee from the Cradle of Chi-Ji will be along shortly to collect their order.",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32658] = {id=32658,name="Work Order: The Klaxxi I",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,starts={{npcID=218750,x=0.522,y=0.487,mapID=376}},coords={x=0.522,y=0.487,source="quest_giver",mapID=376},questType="standard"},
[32659] = {id=32659,name="Work Order: The Klaxxi II",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Once your mogu pumpkins are ready to be picked, you'll need only to package them for pick-up. I wouldn't dilly-dally if I were you. The Klaxxi aren't known for their patience!",starts={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},ends={{npcID=218765,x=0.517,y=0.487,zoneID=5805}},coords={x=0.517,y=0.487,source="quest_giver",zoneID=5805},questType="standard"},
[32662] = {id=32662,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1,mapID=27,description="It's time for you to learn how to ride! Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge. Don't forget to buy your mount while you are there!",ends={{npcID=4772,x=0.712,y=0.484,mapID=27}},questType="standard"},
[32663] = {id=32663,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1,mapID=27,description="It's time for you to learn how to ride! Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh. Don't forget to buy your mount while you are there!",ends={{npcID=7954,x=0.562,y=0.464,mapID=27}},questType="standard"},
[32664] = {id=32664,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1657,mapID=89,description="It's time for you to learn how to ride! Seek out Jartsam at the Cenarion Enclave in Darnassus. Don't forget to buy your mount while you are there!",ends={{npcID=4753,x=0.546,y=0.122,mapID=84},{npcID=4753,x=0.426,y=0.33,mapID=89}},questType="standard"},
[32665] = {id=32665,name="Learn To Ride",level=10,requiredLevel=10,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="It's time for you to learn how to ride! Seek out Mei Lin north of the Dwarven District in Stormwind. Don't forget to buy your mount while you are there!",ends={{npcID=70296,x=0.676,y=0.186,mapID=84}},questType="standard"},
[32666] = {id=32666,name="FLAG - Warlock - Green Fire",level=0,requiredLevel=0,faction="both",expansion=4,zoneID=5785,mapID=371,questType="standard"},
[32667] = {id=32667,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,mapID=85,description="It's time for you to learn how to ride! Seek out Softpaws in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!",ends={{npcID=70301,x=0.698,y=0.408,mapID=85}},questType="standard"},
[32668] = {id=32668,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=3430,description="It's time for you to learn how to ride! Seek out Perascamin at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City. Don't forget to buy your mount while you are there!",ends={{npcID=16280,x=0.612,y=0.54,zoneID=3430}},questType="standard"},
[32669] = {id=32669,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,mapID=85,description="It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!",ends={{npcID=4752,x=0.614,y=0.344,mapID=85}},questType="standard"},
[32670] = {id=32670,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=215,mapID=7,description="It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!",ends={{npcID=3690,x=0.476,y=0.58,mapID=7}},questType="standard"},
[32671] = {id=32671,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=14,mapID=1,description="It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!",ends={{npcID=7953,x=0.552,y=0.754,mapID=1}},questType="standard"},
[32672] = {id=32672,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=85,mapID=18,description="It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!",ends={{npcID=4773,x=0.618,y=0.518,mapID=18}},questType="standard"},
[32673] = {id=32673,name="Learn To Ride",level=10,requiredLevel=10,faction="horde",expansion=4,zoneID=1637,mapID=85,description="It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!",ends={{npcID=48513,x=0.366,y=0.87,mapID=85}},questType="standard"},
[32674] = {id=32674,name="I Believe You Can Fly",level=30,requiredLevel=30,faction="horde",expansion=4,zoneID=1637,mapID=85,description="The skies call out to you! It's time to learn to fly! Visit the flying trainer, Maztha , at the Skyway in Orgrimmar. And don't forget to buy a flying mount!",ends={{npcID=44919,x=0.49,y=0.592,mapID=85}},questType="standard"},
[32675] = {id=32675,name="I Believe You Can Fly",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=1519,mapID=84,description="The skies call out to you! It's time to learn to fly! Visit the flying trainer, Bralla Cloudwing , at the Gryphon Roost in Stormwind. And don't forget to buy a flying mount!",ends={{npcID=43769,x=0.702,y=0.734,mapID=84}},questType="standard"},
[32676] = {id=32676,name="Extended Shore Leave",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort. Simply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault. No captain. No repairs. No warship.",starts={{npcID=69413,x=0.586,y=0.426,mapID=504}},ends={{npcID=67990,x=0.326,y=0.354,mapID=504}},coords={x=0.586,y=0.426,source="quest_giver",mapID=504},questType="standard"},
[32677] = {id=32677,name="Raiding the Vault",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=6507,mapID=504,description="The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same. One artifact in particular, an amulet known as the Choker of Storms , could help us to understand his apparent mastery over lightning. Break into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.",questType="standard"},
[32678] = {id=32678,name="Thunder Calls",level=32,requiredLevel=32,faction="horde",expansion=4,zoneID=5842,description="The time to attack the Thunder King has come! A small group of Sunreavers awaits you near the Shado-Pan Garrison in Townlong Steppes. Report to Scout Captain Elsia for further instructions.",starts={{npcID=64566,x=0.628,y=0.28,zoneID=5840}},ends={{npcID=70358,x=0.508,y=0.732,zoneID=5842}},coords={x=0.628,y=0.28,source="quest_giver",zoneID=5840},questType="standard"},
[32679] = {id=32679,name="Thunder Calls",level=32,requiredLevel=32,faction="alliance",expansion=4,zoneID=5842,description="The time to attack the Thunder King has come! A small group of Kirin Tor awaits you near the Shado-Pan Garrison in Townlong Steppes. Report to Vereesa Windrunner for further instructions.",starts={{npcID=64610,x=0.84,y=0.588,zoneID=5840}},ends={{npcID=70360,x=0.498,y=0.69,zoneID=5842}},coords={x=0.84,y=0.588,source="quest_giver",zoneID=5840},questType="standard"},
[32682] = {id=32682,name="Inherit the Earth",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="As you know, , I'm getting along in my years. One can't stay a spry young pandaren forever, you know. I'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon. He's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart. Do you think he'd be interested?",starts={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},ends={{npcID=64597,x=0.546,y=0.47,zoneID=5805}},coords={x=0.546,y=0.47,source="quest_giver",zoneID=5805},questType="standard"},
[32683] = {id=32683,name="So You Want to Be a Blacksmith...",level=30,requiredLevel=30,faction="alliance",expansion=4,zoneID=9105,description="While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key .",starts={{npcID=64085,x=0.912,y=0.652,zoneID=9105}},ends={{npcID=64085,x=0.912,y=0.652,zoneID=9105}},coords={x=0.912,y=0.652,source="quest_giver",zoneID=9105},questType="standard"},
[32684] = {id=32684,name="You Want Fish?",level=35,requiredLevel=35,faction="both",expansion=4,zoneID=5805,description="Are you looking for golden carp ? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.",starts={{npcID=64231,x=0.536,y=0.512,zoneID=5805}},ends={{npcID=70398,x=0.588,y=0.47,zoneID=5805}},coords={x=0.536,y=0.512,source="quest_giver",zoneID=5805},questType="standard"},
[32685] = {id=32685,name="No Fishing Pole Necessary!",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5805,description="You don't even need to equip a fishing pole in Pandaria! The waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!",starts={{npcID=70398,x=0.588,y=0.47,zoneID=5805}},ends={{npcID=70398,x=0.588,y=0.47,zoneID=5805}},coords={x=0.588,y=0.47,source="quest_giver",zoneID=5805},questType="standard"},
[32686] = {id=32686,name="Pristine Banner of the Mantid Empire",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=9105,mapID=1530,description="This artifact has been restored to a remarkably excellent condition. Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.",ends={{npcID=218958,x=0.828,y=0.322,mapID=1530},{npcID=218958,x=0.833,y=0.297,mapID=1530}},questType="standard"},
